INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u1-C1','math',2,2,'u1',2,'천 알아보기 — 100이 10개인 수 1000을 쓰고 「천」으로 읽으며, 999보다 1·990보다 10·900보다 100만큼 더 큰 수로 나타내기',ARRAY['2수01-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u1-C2','math',2,2,'u1',3,'몇천 알아보기 — 1000이 몇 개인지로 2000~9000을 쓰고 읽으며, 몇천이 1000이 몇 개인지 거꾸로 알기(천 모형과 백 모형 구별)',ARRAY['2수01-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u1-C3','math',2,2,'u1',4,'네 자리 수 쓰고 읽기 — 1000·100·10·1의 개수(수 모형·돈)로 네 자리 수를 쓰고 읽으며, 없는 자리에는 0을 쓰고 0인 자리는 읽지 않기',ARRAY['2수01-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u1-C4','math',2,2,'u1',5,'각 자리의 숫자가 나타내는 값 — 천·백·십·일의 자리 숫자를 찾고, 같은 숫자라도 자리에 따라 값이 다름을 알며, 네 자리 수를 (몇천)+(몇백)+(몇십)+(몇)으로 나타내기',ARRAY['2수01-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u1-C5','math',2,2,'u1',6,'뛰어 세기 — 1000씩·100씩·10씩·1씩 뛰어 세고 거꾸로 세며, 몇씩 뛰었는지 찾고, 윗자리가 바뀌는 문턱(3990→4000, 4999→5000) 넘기',ARRAY['2수01-03']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u1-C6','math',2,2,'u1',7,'네 자리 수의 크기 비교 — 천의 자리부터 차례로 견주어 >·<로 나타내고, 셋 가운데 가장 큰/작은 수·수 카드로 만든 수·□에 들어갈 수와 연도의 차례 찾기',ARRAY['2수01-03']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u1-C7','math',2,2,'u1',9,'수를 여러 가지로 나타내기 — 한 수를 1000·100·10·1의 여러 묶음(100이 몇 개, 돈 바꾸기)으로 나타내고, 한 자리에 10개가 넘게 모이면 윗자리로 바꾸어 세기',ARRAY['2수01-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u1-X01','math',2,'u1',ARRAY['M2-2-u1-C1','M2-2-u1-C5']::text[],'9 다음에 윗자리가 바뀌는 것을 모르고 숫자를 이어 붙인다 — 999 다음을 9910, 900 다음 100을 9100, 3990에서 10 더를 39100','수 모형으로 9개 다음 1개를 더 놓고, 10개가 되면 윗자리 모형 1개로 바꾸는 장면을 보이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u1-X02','math',2,'u1',ARRAY['M2-2-u1-C1','M2-2-u1-C7']::text[],'100이 10개를 10010이나 200처럼 늘어놓거나, 1000 속에 100이 몇 개 있는지 모른다','백 모형 10개를 쌓아 천 모형 1개와 크기가 같음을 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u1-X03','math',2,'u1',ARRAY['M2-2-u1-C2','M2-2-u1-C7']::text[],'1000의 개수를 다른 자리에 쓴다 — 1000이 4개를 1004·400으로, 천 모형 3개를 300으로, 3000을 1000이 30개로','천·백·십·일 칸을 그려 놓고 「1000이 몇 개」는 천의 칸에만 쓰게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u1-X04','math',2,'u1',ARRAY['M2-2-u1-C3','M2-2-u1-C4']::text[],'없는 자리의 0을 빠뜨린다 — 천 3·십 2·일 7을 327로, 「육천삼십오」를 635로','네 칸을 먼저 그리고 빈 칸에 0을 채우는 습관 들이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u1-X05','math',2,'u1',ARRAY['M2-2-u1-C3','M2-2-u1-C4']::text[],'읽은 소리나 각 자리 값을 그대로 이어 쓴다 — 사천삼백오십이를 4000300502로, 4000+300+50+2를 그대로 늘어놓기','네 자리 수는 숫자 네 개 — 칸 하나에 숫자 하나만 들어간다는 것을 수 카드 네 장으로 보이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u1-X06','math',2,'u1',ARRAY['M2-2-u1-C3']::text[],'자리 순서를 섞어 쓴다 — 천 4·백 3·십 9·일 2를 4932·2934로','「천·백·십·일」을 왼쪽부터 손가락으로 짚으며 숫자를 놓기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u1-X07','math',2,'u1',ARRAY['M2-2-u1-C1','M2-2-u1-C2','M2-2-u1-C3']::text[],'읽을 때 자리 이름을 빼먹거나 0을 읽는다 — 6035를 「육영삼오」·「육천영백삼십오」, 1000을 「일영영영」','숫자 뒤에 자리 이름(천·백·십)을 붙여 끊어 읽고, 0인 자리는 건너뛰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u1-X08','math',2,'u1',ARRAY['M2-2-u1-C4']::text[],'자리 이름을 헷갈린다 — 오른쪽부터 세어 천의 자리와 일의 자리를 바꾸거나, 백의 자리 숫자를 다른 자리 값으로 읽는다','자릿값 표에 수를 써 넣고 「왼쪽이 천」을 소리 내어 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u1-X09','math',2,'u1',ARRAY['M2-2-u1-C4']::text[],'숫자와 그 숫자가 나타내는 값을 같게 본다 — 5836의 8을 8로, 1111의 네 1을 같은 값으로','「숫자 × 자리」로 값을 말하게 하기 — 8은 백의 자리라서 800') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u1-X10','math',2,'u1',ARRAY['M2-2-u1-C3','M2-2-u1-C7']::text[],'한 자리에 10개가 넘게 모여도 윗자리로 바꾸지 않는다 — 1000이 2개·100이 13개를 21300이나 2300으로','10개씩 묶어 윗자리 모형 하나로 바꾼 뒤 다시 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u1-X11','math',2,'u1',ARRAY['M2-2-u1-C5']::text[],'뛰어 셀 때 다른 자리 숫자를 바꾼다 — 1000씩 뛰는데 백의 자리나 일의 자리를 1 바꿈','「1000씩이면 천의 자리만 움직인다」 — 바뀌는 자리에 색칠하며 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u1-X12','math',2,'u1',ARRAY['M2-2-u1-C1','M2-2-u1-C5']::text[],'1·10·100·1000 가운데 얼마만큼인지, 몇씩 뛰었는지를 헷갈리거나 방향을 거꾸로 한다','이웃한 두 수에서 바뀐 자리를 찾아 「그 자리만큼」이라고 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u1-X13','math',2,'u1',ARRAY['M2-2-u1-C6']::text[],'낮은 자리부터 견주거나 뒤쪽 숫자에 속는다 — 뒤가 9로 가득한 1999가 2005보다 크다고 한다','두 수를 자릿값 표에 위아래로 써 놓고 천의 자리부터 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u1-X14','math',2,'u1',ARRAY['M2-2-u1-C6']::text[],'>·< 기호의 방향을 거꾸로 쓴다','벌어진 입이 큰 수를 먹는다 — 큰 수 쪽이 벌어진 쪽') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u1-X15','math',2,'u1',ARRAY['M2-2-u1-C6','M2-2-u1-C7']::text[],'묻는 말을 거꾸로 읽는다 — 가장 큰↔가장 작은, 오래전↔최근, 더 필요한 수↔전체 수','물음의 「큰·작은·더·오래」에 동그라미를 치고 답을 넣어 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u1-X16','math',2,'u1',ARRAY['M2-2-u1-C6']::text[],'수 카드로 수를 만들 때 높은 자리부터 놓지 않거나 0을 맨 앞에 놓는다','천의 자리부터 차례로 — 가장 작은 수를 만들 때 0은 천의 자리에 못 온다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L02_basic#1','math',2,2,'u1','L02','g2_2_math_u1_L02_basic','lesson_basic','M2-2-u1-C1',1,'mc','auto','백 모형이 10개 있어요. 모두 얼마인가요?',ARRAY['M2-2-u1-X02']::text[],true,'{"seq":1,"concept":"M2-2-u1-C1","difficulty":1,"kind":"mc","stem":"백 모형이 10개 있어요. 모두 얼마인가요?","options":[{"t":"1000","correct":true},{"t":"10010","mis":"M2-2-u1-X02"},{"t":"100","mis":"M2-2-u1-X02"}],"explanation":["백 모형 하나는 100이에요.","100이 10개이면 1000이에요.","백 모형 10개는 천 모형 1개와 같아요."],"asset":{"type":"blocks4","th":0,"h":10,"t":0,"o":0},"variant_rule":{"alt":[{"stem":"100원짜리 동전 10개는 모두 얼마인가요?","options":[{"t":"1000원","correct":true},{"t":"10010원","mis":"M2-2-u1-X02"},{"t":"110원","mis":"M2-2-u1-X02"}],"explanation":["100원짜리 하나는 100원이에요.","100원이 10개이면 1000원이에요.","100원짜리 10개는 천 원짜리 1장과 같아요."],"asset":{"type":"blocks4","th":0,"h":10,"t":0,"o":0,"unit":"coin"}},{"stem":"연이 한 상자에 100개씩 10상자 있어요. 연은 모두 몇 개인가요?","options":[{"t":"1000","correct":true},{"t":"110","mis":"M2-2-u1-X02"},{"t":"10010","mis":"M2-2-u1-X02"}],"explanation":["한 상자에 100개씩이에요.","100이 10개이면 1000이에요.","상자 수와 연의 수를 헷갈리지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L02_basic#2','math',2,2,'u1','L02','g2_2_math_u1_L02_basic','lesson_basic','M2-2-u1-C1',1,'sa','auto','100이 10개이면 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M2-2-u1-C1","difficulty":1,"kind":"sa","stem":"100이 10개이면 얼마인가요?","answer":["1000"],"explanation":["100씩 세어 보세요 — 100, 200, … 900, 1000.","100이 10개이면 1000이에요.","1000은 「천」이라고 읽어요."],"variant_rule":{"alt":[{"stem":"999보다 1만큼 더 큰 수는 얼마인가요?","answer":["1000"],"explanation":["999 바로 다음 수를 찾아요.","999보다 1 큰 수는 1000이에요.","999 다음은 9910이 아니라 1000이에요."]},{"stem":"900보다 100만큼 더 큰 수는 얼마인가요?","answer":["1000"],"explanation":["900에서 100을 더 뛰어 세어요.","900보다 100 큰 수는 1000이에요.","백 모형 9개에 1개를 더하면 10개 — 1000이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L02_basic#3','math',2,2,'u1','L02','g2_2_math_u1_L02_basic','lesson_basic','M2-2-u1-C1',1,'mc','auto','1000을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u1-X07','M2-2-u1-X02']::text[],true,'{"seq":3,"concept":"M2-2-u1-C1","difficulty":1,"kind":"mc","stem":"1000을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"천","correct":true},{"t":"일영영영","mis":"M2-2-u1-X07"},{"t":"십백","mis":"M2-2-u1-X02"}],"explanation":["1000은 천의 자리가 1인 수예요.","「천」이라고 읽어요.","숫자를 하나씩 따로 읽지 않아요."],"variant_rule":{"alt":[{"stem":"「천」을 수로 쓰면 무엇인가요?","options":[{"t":"1000","correct":true},{"t":"100","mis":"M2-2-u1-X12"},{"t":"10000","mis":"M2-2-u1-X02"}],"explanation":["「천」은 100이 10개인 수예요.","수로 쓰면 1000이에요.","1 뒤에 0을 세 개 써요."]},{"stem":"1000에 대한 설명으로 바른 것은 어느 것인가요?","options":[{"t":"999보다 1 큰 수예요.","correct":true},{"t":"900보다 10 큰 수예요.","mis":"M2-2-u1-X12"},{"t":"100이 1개인 수예요.","mis":"M2-2-u1-X02"}],"explanation":["1000은 999 바로 다음 수예요.","900보다는 100 커요.","100이 10개 모여야 1000이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L02_basic#4','math',2,2,'u1','L02','g2_2_math_u1_L02_basic','lesson_basic','M2-2-u1-C1',1,'mc','auto','999보다 1만큼 더 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X01','M2-2-u1-X12']::text[],true,'{"seq":4,"concept":"M2-2-u1-C1","difficulty":1,"kind":"mc","stem":"999보다 1만큼 더 큰 수는 무엇인가요?","options":[{"t":"1000","correct":true},{"t":"9910","mis":"M2-2-u1-X01"},{"t":"998","mis":"M2-2-u1-X12"}],"explanation":["999 다음 수를 찾아요.","999보다 1 큰 수는 1000이에요.","9 뒤에 10을 붙이지 않아요 — 일·십·백의 자리가 차례로 넘어가 천의 자리가 생겨요."],"variant_rule":{"alt":[{"stem":"997, 998, 999 다음에 오는 수는 무엇인가요?","options":[{"t":"1000","correct":true},{"t":"9910","mis":"M2-2-u1-X01"},{"t":"9100","mis":"M2-2-u1-X01"}],"explanation":["999 다음 수예요.","999보다 1 큰 수는 1000이에요.","세 자리가 모두 9이면 다음은 1000이에요."]},{"stem":"1000보다 1만큼 더 작은 수는 무엇인가요?","options":[{"t":"999","correct":true},{"t":"1001","mis":"M2-2-u1-X12"},{"t":"900","mis":"M2-2-u1-X12"}],"explanation":["1000 바로 앞의 수예요.","1000보다 1 작은 수는 999예요.","1만큼은 바로 앞, 100만큼은 백 모형 하나 차이예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L02_basic#5','math',2,2,'u1','L02','g2_2_math_u1_L02_basic','lesson_basic','M2-2-u1-C1',2,'mc','auto','1000은 900보다 얼마만큼 더 큰 수인가요?',ARRAY['M2-2-u1-X12']::text[],true,'{"seq":5,"concept":"M2-2-u1-C1","difficulty":2,"kind":"mc","stem":"1000은 900보다 얼마만큼 더 큰 수인가요?","options":[{"t":"100","correct":true},{"t":"1","mis":"M2-2-u1-X12"},{"t":"10","mis":"M2-2-u1-X12"}],"explanation":["900에서 100씩 뛰어 세면 바로 1000이에요.","그래서 1000은 900보다 100 큰 수예요.","백 모형 9개에 1개를 더하면 10개예요."],"variant_rule":{"alt":[{"stem":"1000은 990보다 얼마만큼 더 큰 수인가요?","options":[{"t":"10","correct":true},{"t":"1","mis":"M2-2-u1-X12"},{"t":"100","mis":"M2-2-u1-X12"}],"explanation":["990에서 10을 더 뛰면 1000이에요.","그래서 1000은 990보다 10 커요.","십의 자리부터 차례로 넘어가요."]},{"stem":"1000은 800보다 얼마만큼 더 큰 수인가요?","options":[{"t":"200","correct":true},{"t":"2","mis":"M2-2-u1-X12"},{"t":"100","mis":"M2-2-u1-X12"}],"explanation":["800, 900, 1000 — 100씩 두 번 뛰어요.","그래서 1000은 800보다 200 커요.","100씩 몇 번 뛰었는지 세어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L02_basic#6','math',2,2,'u1','L02','g2_2_math_u1_L02_basic','lesson_basic','M2-2-u1-C1',2,'mc','auto','1000은 100이 몇 개인 수인가요?',ARRAY['M2-2-u1-X02','M2-2-u1-X09']::text[],true,'{"seq":6,"concept":"M2-2-u1-C1","difficulty":2,"kind":"mc","stem":"1000은 100이 몇 개인 수인가요?","options":[{"t":"10","correct":true},{"t":"1","mis":"M2-2-u1-X02"},{"t":"100","mis":"M2-2-u1-X09"}],"explanation":["100, 200, 300, … 1000 — 100씩 세어 보세요.","10번 세면 1000이에요.","그래서 1000은 100이 10개예요."],"variant_rule":{"alt":[{"stem":"연 1000개를 한 상자에 100개씩 담으면 몇 상자가 되나요?","options":[{"t":"10","correct":true},{"t":"100","mis":"M2-2-u1-X09"},{"t":"1","mis":"M2-2-u1-X02"}],"explanation":["100개씩 담아요.","1000은 100이 10개 — 10상자예요.","상자 수와 연의 수를 헷갈리지 않아요."]},{"stem":"1000원은 100원짜리 동전 몇 개와 같나요?","options":[{"t":"10","correct":true},{"t":"100","mis":"M2-2-u1-X09"},{"t":"1","mis":"M2-2-u1-X02"}],"explanation":["100원씩 세어요 — 100, 200, … 1000.","100원짜리 10개면 1000원이에요.","그래서 10개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L02_basic#7','math',2,2,'u1','L02','g2_2_math_u1_L02_basic','lesson_basic','M2-2-u1-C1',2,'ox','auto','100이 10개이면 10010이에요.',ARRAY['M2-2-u1-X02']::text[],true,'{"seq":7,"concept":"M2-2-u1-C1","difficulty":2,"kind":"ox","stem":"100이 10개이면 10010이에요.","answer":"X","reason_options":[{"t":"100이 10개 모이면 천의 자리가 생겨 1000이니까","correct":true},{"t":"100 뒤에 10을 붙이면 되니까","mis":"M2-2-u1-X02"}],"mis":"M2-2-u1-X02","explanation":["100씩 10번 세면 1000이에요.","100이 10개 모이면 새 자리, 천의 자리가 생겨요.","그래서 틀린 말이에요."],"variant_rule":{"alt":[{"stem":"1000은 999보다 1 큰 수예요.","answer":"O","reason_options":[{"t":"999 바로 다음 수가 1000이니까","correct":true},{"t":"999 다음은 9910이니까","mis":"M2-2-u1-X01"}],"explanation":["999에 1을 더하면 일의 자리가 10이 돼요.","십·백의 자리로 차례로 넘어가 1000이에요.","그래서 맞는 말이에요."]},{"stem":"1000은 900보다 10 큰 수예요.","answer":"X","reason_options":[{"t":"900보다 100 커야 1000이니까","correct":true},{"t":"9 다음에 10을 더하면 1000이니까","mis":"M2-2-u1-X12"}],"explanation":["900보다 10 큰 수는 910이에요.","1000은 900보다 100 커요.","그래서 틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L02_basic#8','math',2,2,'u1','L02','g2_2_math_u1_L02_basic','lesson_basic','M2-2-u1-C1',2,'blank','auto','1000은 990보다 (        )만큼 더 큰 수예요.',ARRAY['M2-2-u1-X12']::text[],true,'{"seq":8,"concept":"M2-2-u1-C1","difficulty":2,"kind":"blank","stem":"1000은 990보다 (        )만큼 더 큰 수예요.","options":[{"t":"10","correct":true},{"t":"1","mis":"M2-2-u1-X12"},{"t":"100","mis":"M2-2-u1-X12"}],"explanation":["990에서 10을 더 뛰면 1000이에요.","그래서 10만큼 커요.","수 배열표에서 오른쪽으로 한 칸(10) 차이예요."],"variant_rule":{"alt":[{"stem":"1000은 999보다 (        )만큼 더 큰 수예요.","options":[{"t":"1","correct":true},{"t":"10","mis":"M2-2-u1-X12"},{"t":"100","mis":"M2-2-u1-X12"}],"explanation":["999 바로 다음 수가 1000이에요.","바로 다음 수는 1만큼 더 큰 수예요.","그래서 빈칸은 1이에요."]},{"stem":"100이 (        )개이면 1000이에요.","options":[{"t":"10","correct":true},{"t":"1","mis":"M2-2-u1-X02"},{"t":"100","mis":"M2-2-u1-X09"}],"explanation":["100씩 세어 1000까지 가요.","10번 세면 1000이에요.","100이 10개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L02_basic#9','math',2,2,'u1','L02','g2_2_math_u1_L02_basic','lesson_basic','M2-2-u1-C1',2,'match','auto','같은 수끼리 이어 보세요.','{}'::text[],true,'{"seq":9,"concept":"M2-2-u1-C1","difficulty":2,"kind":"match","stem":"같은 수끼리 이어 보세요.","pairs":[{"l":"999보다 1 큰 수","r":"1000"},{"l":"900보다 1 큰 수","r":"901"},{"l":"100이 9개인 수","r":"900"}],"mis":"M2-2-u1-X12","explanation":["999보다 1 큰 수는 1000이에요.","900보다 1 큰 수는 901, 100이 9개인 수는 900이에요.","1만큼과 100만큼을 헷갈리지 않아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 같은 수끼리 이어 보세요.","pairs":[{"l":"900보다 100 큰 수","r":"1000"},{"l":"800보다 100 큰 수","r":"900"},{"l":"990보다 1 큰 수","r":"991"}],"explanation":["900보다 100 큰 수는 1000이에요.","800보다 100 큰 수는 900, 990보다 1 큰 수는 991이에요.","얼마만큼 큰지 잘 읽어요."]},{"stem":"이번에는 다른 보기예요. 같은 수끼리 이어 보세요.","pairs":[{"l":"990보다 10 큰 수","r":"1000"},{"l":"980보다 10 큰 수","r":"990"},{"l":"999보다 1 작은 수","r":"998"}],"explanation":["990보다 10 큰 수는 1000이에요.","980보다 10 큰 수는 990, 999보다 1 작은 수는 998이에요.","큰 수인지 작은 수인지 잘 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L02_basic#10','math',2,2,'u1','L02','g2_2_math_u1_L02_basic','lesson_basic','M2-2-u1-C1',3,'sa','auto','600부터 100씩 뛰어 세었어요. 몇 번 뛰어 세면 1000이 되나요?','{}'::text[],true,'{"seq":10,"concept":"M2-2-u1-C1","difficulty":3,"kind":"sa","stem":"600부터 100씩 뛰어 세었어요. 몇 번 뛰어 세면 1000이 되나요?","answer":["4","4번"],"explanation":["600, 700, 800, 900, 1000이에요.","700·800·900·1000 — 4번 뛰었어요.","처음 수 600은 뛴 횟수에 넣지 않아요."],"variant_rule":{"alt":[{"stem":"960부터 10씩 뛰어 세었어요. 몇 번 뛰어 세면 1000이 되나요?","answer":["4","4번"],"explanation":["960, 970, 980, 990, 1000이에요.","970·980·990·1000 — 4번 뛰었어요.","처음 수는 뛴 횟수에 넣지 않아요."]},{"stem":"995부터 1씩 뛰어 세었어요. 몇 번 뛰어 세면 1000이 되나요?","answer":["5","5번"],"explanation":["995, 996, 997, 998, 999, 1000이에요.","996부터 1000까지 — 5번 뛰었어요.","처음 수는 뛴 횟수에 넣지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L02_challenge#1','math',2,2,'u1','L02','g2_2_math_u1_L02_challenge','lesson_challenge','M2-2-u1-C1',2,'mc','auto','300과 어떤 수를 모으면 1000이 돼요. 어떤 수는 무엇인가요?',ARRAY['M2-2-u1-X02','M2-2-u1-X12']::text[],true,'{"seq":1,"concept":"M2-2-u1-C1","difficulty":2,"kind":"mc","stem":"300과 어떤 수를 모으면 1000이 돼요. 어떤 수는 무엇인가요?","options":[{"t":"700","correct":true},{"t":"7","mis":"M2-2-u1-X02"},{"t":"800","mis":"M2-2-u1-X12"}],"explanation":["300에서 100씩 뛰어 세면 400, 500, … 1000이에요.","100씩 7번 — 700이에요.","300과 700을 모으면 1000이에요."],"variant_rule":{"alt":[{"stem":"800과 어떤 수를 모으면 1000이 돼요. 어떤 수는 무엇인가요?","options":[{"t":"200","correct":true},{"t":"2","mis":"M2-2-u1-X02"},{"t":"300","mis":"M2-2-u1-X12"}],"explanation":["800에서 100씩 뛰면 900, 1000이에요.","100씩 2번 — 200이에요.","800과 200을 모으면 1000이에요."]},{"stem":"1000을 똑같은 두 수로 가르면 한 수는 얼마인가요?","options":[{"t":"500","correct":true},{"t":"5","mis":"M2-2-u1-X02"},{"t":"50","mis":"M2-2-u1-X03"}],"explanation":["500과 500을 모으면 1000이에요.","그래서 한 수는 500이에요.","백 모형 10개를 5개씩 나눈 것과 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L02_challenge#2','math',2,2,'u1','L02','g2_2_math_u1_L02_challenge','lesson_challenge','M2-2-u1-C1',2,'error','auto','친구들이 1000에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u1-X02','M2-2-u1-X01','M2-2-u1-X12']::text[],true,'{"seq":2,"concept":"M2-2-u1-C1","difficulty":2,"kind":"error","stem":"친구들이 1000에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지호: 100이 10개니까 10010이라고 써.","correct":true,"mis_target":"M2-2-u1-X02"},{"t":"하린: 999보다 1 큰 수가 1000이야.","mis":"M2-2-u1-X01"},{"t":"도윤: 1000은 900보다 100 큰 수야.","mis":"M2-2-u1-X12"}],"explanation":["100이 10개 모이면 새로운 자리, 천의 자리가 생겨요.","그래서 10010이 아니라 1000이라고 써요.","지호가 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 1000에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아: 1000은 「일영영영」이라고 읽어.","correct":true,"mis_target":"M2-2-u1-X07"},{"t":"준우: 1000은 「천」이라고 읽어.","mis":"M2-2-u1-X07"},{"t":"라희: 1000은 999 다음 수야.","mis":"M2-2-u1-X01"}],"explanation":["1000은 「천」이라고 읽어요.","숫자를 하나씩 따로 읽지 않아요.","서아가 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L02_challenge#3','math',2,2,'u1','L02','g2_2_math_u1_L02_challenge','lesson_challenge','M2-2-u1-C7',3,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-2-u1-X10']::text[],true,'{"seq":3,"concept":"M2-2-u1-C7","difficulty":3,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"1000","correct":true},{"t":"9100","mis":"M2-2-u1-X10"},{"t":"910","mis":"M2-2-u1-X10"}],"explanation":["십 모형 10개는 백 모형 1개와 같아요.","그러면 백 모형이 9개와 1개 — 10개이니 1000이에요.","한 자리에 10개가 모이면 바로 윗자리 1개로 바꿔요."],"asset":{"type":"blocks4","th":0,"h":9,"t":10,"o":0},"variant_rule":{"alt":[{"stem":"100원짜리 동전 9개와 10원짜리 동전 10개는 모두 얼마인가요?","options":[{"t":"1000원","correct":true},{"t":"9100원","mis":"M2-2-u1-X10"},{"t":"910원","mis":"M2-2-u1-X10"}],"explanation":["10원짜리 10개는 100원짜리 1개와 같아요.","그러면 100원짜리가 10개 — 1000원이에요.","한 자리에 10개가 모이면 윗자리로 바꿔요."],"asset":{"type":"blocks4","th":0,"h":9,"t":10,"o":0,"unit":"coin"}},{"stem":"100원짜리 동전 8개와 10원짜리 동전 20개는 모두 얼마인가요?","options":[{"t":"1000원","correct":true},{"t":"8200원","mis":"M2-2-u1-X10"},{"t":"820원","mis":"M2-2-u1-X10"}],"explanation":["10원짜리 20개는 100원짜리 2개와 같아요.","100원짜리가 8개와 2개 — 10개이니 1000원이에요.","10개씩 모이면 윗자리로 바꿔 세요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L02_challenge#4','math',2,2,'u1','L02','g2_2_math_u1_L02_challenge','lesson_challenge','M2-2-u1-C1',3,'sa','auto','연이 한 상자에 100개씩 들어 있어요. 연 1000개를 담으려면 상자가 몇 개 있어야 하나요?','{}'::text[],true,'{"seq":4,"concept":"M2-2-u1-C1","difficulty":3,"kind":"sa","stem":"연이 한 상자에 100개씩 들어 있어요. 연 1000개를 담으려면 상자가 몇 개 있어야 하나요?","answer":["10","10개"],"explanation":["1000은 100이 10개예요.","그래서 100개씩 담으면 10상자예요.","100, 200, … 1000으로 세어 보세요."],"variant_rule":{"alt":[{"stem":"색종이 1000장을 100장씩 묶으면 몇 묶음이 되나요?","answer":["10","10묶음"],"explanation":["1000은 100이 10개예요.","100장씩이면 10묶음이에요.","100씩 세어 1000이 될 때까지 세어요."]},{"stem":"100원짜리 동전으로 1000원을 만들려면 몇 개가 있어야 하나요?","answer":["10","10개"],"explanation":["100원씩 세어요.","100원짜리 10개면 1000원이에요.","그래서 10개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L02_challenge#5','math',2,2,'u1','L02','g2_2_math_u1_L02_challenge','lesson_challenge','M2-2-u1-C1',3,'ox','auto','999 다음 수는 9910이에요.',ARRAY['M2-2-u1-X01']::text[],true,'{"seq":5,"concept":"M2-2-u1-C1","difficulty":3,"kind":"ox","stem":"999 다음 수는 9910이에요.","answer":"X","reason_options":[{"t":"999보다 1 큰 수는 1000이니까","correct":true},{"t":"9 다음에 10을 붙이면 되니까","mis":"M2-2-u1-X01"}],"mis":"M2-2-u1-X01","explanation":["999에 1을 더하면 일의 자리가 10이 돼요.","10은 윗자리로 넘어가 십·백의 자리도 차례로 넘어가고, 결국 1000이에요.","숫자를 이어 붙이지 않아요."],"variant_rule":{"alt":[{"stem":"990 다음에 10씩 뛰어 센 수는 1000이에요.","answer":"O","reason_options":[{"t":"990보다 10 큰 수는 1000이니까","correct":true},{"t":"990 다음은 9100이니까","mis":"M2-2-u1-X01"}],"explanation":["990에서 10을 더 뛰어요.","십·백의 자리가 넘어가 1000이에요.","그래서 맞는 말이에요."]},{"stem":"1000은 998보다 1 큰 수예요.","answer":"X","reason_options":[{"t":"998 다음은 999, 그다음이 1000이라 2 크니까","correct":true},{"t":"1000은 998 바로 다음 수니까","mis":"M2-2-u1-X12"}],"explanation":["998, 999, 1000이에요.","1000은 998보다 2 커요.","그래서 틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L02_challenge#6','math',2,2,'u1','L02','g2_2_math_u1_L02_challenge','lesson_challenge','M2-2-u1-C1',3,'mc','auto','100씩 뛰어 세었어요. 700, 800, 900 다음에 오는 수는 무엇인가요?',ARRAY['M2-2-u1-X01','M2-2-u1-X12']::text[],true,'{"seq":6,"concept":"M2-2-u1-C1","difficulty":3,"kind":"mc","stem":"100씩 뛰어 세었어요. 700, 800, 900 다음에 오는 수는 무엇인가요?","options":[{"t":"1000","correct":true},{"t":"9100","mis":"M2-2-u1-X01"},{"t":"910","mis":"M2-2-u1-X12"}],"explanation":["100씩 뛰면 백의 자리 숫자가 1씩 커져요.","900에서 100을 더 뛰면 백 모형이 10개 — 1000이에요.","9 다음에 100을 붙여 9100으로 쓰지 않아요."],"variant_rule":{"alt":[{"stem":"10씩 뛰어 세었어요. 970, 980, 990 다음에 오는 수는 무엇인가요?","options":[{"t":"1000","correct":true},{"t":"9100","mis":"M2-2-u1-X01"},{"t":"991","mis":"M2-2-u1-X12"}],"explanation":["10씩 뛰면 십의 자리 숫자가 1씩 커져요.","990 다음은 1000이에요.","숫자를 이어 붙이지 않아요."]},{"stem":"100씩 거꾸로 뛰어 세었어요. 1000 다음에 오는 수는 무엇인가요?","options":[{"t":"900","correct":true},{"t":"999","mis":"M2-2-u1-X12"},{"t":"990","mis":"M2-2-u1-X12"}],"explanation":["100씩 거꾸로 뛰면 100만큼씩 작아져요.","1000보다 100 작은 수는 900이에요.","1만큼 작은 999, 10만큼 작은 990과 헷갈리지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L02_challenge#7','math',2,2,'u1','L02','g2_2_math_u1_L02_challenge','lesson_challenge','M2-2-u1-C1',3,'mc','auto','1000이 아닌 것은 어느 것인가요?',ARRAY['M2-2-u1-X02','M2-2-u1-X12']::text[],true,'{"seq":7,"concept":"M2-2-u1-C1","difficulty":3,"kind":"mc","stem":"1000이 아닌 것은 어느 것인가요?","options":[{"t":"990보다 1 큰 수","correct":true},{"t":"100이 10개인 수","mis":"M2-2-u1-X02"},{"t":"900보다 100 큰 수","mis":"M2-2-u1-X12"}],"explanation":["100이 10개인 수, 900보다 100 큰 수는 모두 1000이에요.","990보다 1 큰 수는 991이에요.","얼마만큼 큰지 잘 읽어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 1000이 아닌 것은 어느 것인가요?","options":[{"t":"100이 9개인 수","correct":true},{"t":"999보다 1 큰 수","mis":"M2-2-u1-X01"},{"t":"800보다 200 큰 수","mis":"M2-2-u1-X12"}],"explanation":["999보다 1 큰 수, 800보다 200 큰 수는 1000이에요.","100이 9개인 수는 900이에요.","100이 10개여야 1000이에요."]},{"stem":"이번에는 다른 보기예요. 1000이 아닌 것은 어느 것인가요?","options":[{"t":"900보다 10 큰 수","correct":true},{"t":"500과 500을 모은 수","mis":"M2-2-u1-X02"},{"t":"990보다 10 큰 수","mis":"M2-2-u1-X12"}],"explanation":["500과 500을 모으면 1000, 990보다 10 큰 수도 1000이에요.","900보다 10 큰 수는 910이에요.","900보다 「100」 커야 1000이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L02_challenge#8','math',2,2,'u1','L02','g2_2_math_u1_L02_challenge','lesson_challenge','M2-2-u1-C1',4,'mc','auto','어떤 수보다 100만큼 더 큰 수가 1000이에요. 어떤 수보다 10만큼 더 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X15','M2-2-u1-X12']::text[],true,'{"seq":8,"concept":"M2-2-u1-C1","difficulty":4,"kind":"mc","stem":"어떤 수보다 100만큼 더 큰 수가 1000이에요. 어떤 수보다 10만큼 더 큰 수는 무엇인가요?","options":[{"t":"910","correct":true},{"t":"1010","mis":"M2-2-u1-X15"},{"t":"990","mis":"M2-2-u1-X12"}],"explanation":["1000보다 100 작은 수가 어떤 수예요 — 900이에요.","900보다 10 큰 수는 910이에요.","먼저 어떤 수를 찾고 나서 묻는 말을 풀어요."],"variant_rule":{"alt":[{"stem":"어떤 수보다 10만큼 더 큰 수가 1000이에요. 어떤 수보다 100만큼 더 큰 수는 무엇인가요?","options":[{"t":"1090","correct":true},{"t":"1100","mis":"M2-2-u1-X15"},{"t":"1000","mis":"M2-2-u1-X12"}],"explanation":["1000보다 10 작은 수가 어떤 수예요 — 990이에요.","990보다 100 큰 수는 1090이에요.","먼저 어떤 수를 찾고 나서 묻는 말을 풀어요."]},{"stem":"어떤 수보다 1만큼 더 큰 수가 1000이에요. 어떤 수보다 10만큼 더 작은 수는 무엇인가요?","options":[{"t":"989","correct":true},{"t":"1009","mis":"M2-2-u1-X15"},{"t":"990","mis":"M2-2-u1-X12"}],"explanation":["1000보다 1 작은 수가 어떤 수예요 — 999예요.","999보다 10 작은 수는 989예요.","「작은」인지 「큰」인지 잘 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L02_challenge#9','math',2,2,'u1','L02','g2_2_math_u1_L02_challenge','lesson_challenge','M2-2-u1-C7',4,'sa','auto','100원짜리 동전 6개와 10원짜리 동전 40개가 있어요. 모두 얼마인가요?','{}'::text[],true,'{"seq":9,"concept":"M2-2-u1-C7","difficulty":4,"kind":"sa","stem":"100원짜리 동전 6개와 10원짜리 동전 40개가 있어요. 모두 얼마인가요?","answer":["1000","1000원"],"explanation":["10원짜리 40개는 100원짜리 4개와 같아요.","100원짜리가 6개와 4개 — 10개이니 1000원이에요.","10개씩 모이면 윗자리로 바꿔 세요."],"variant_rule":{"alt":[{"stem":"100원짜리 동전 7개와 10원짜리 동전 30개가 있어요. 모두 얼마인가요?","answer":["1000","1000원"],"explanation":["10원짜리 30개는 100원짜리 3개와 같아요.","100원짜리가 7개와 3개 — 10개이니 1000원이에요.","10개씩 모이면 윗자리로 바꿔 세요."]},{"stem":"100원짜리 동전 5개와 10원짜리 동전 50개가 있어요. 모두 얼마인가요?","answer":["1000","1000원"],"explanation":["10원짜리 50개는 100원짜리 5개와 같아요.","100원짜리가 10개 — 1000원이에요.","10개씩 모이면 윗자리로 바꿔 세요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L02_challenge#10','math',2,2,'u1','L02','g2_2_math_u1_L02_challenge','lesson_challenge','M2-2-u1-C1',4,'essay','teacher','1000을 서로 다른 방법으로 두 가지 설명해 보세요. (예: ○○보다 ○만큼 더 큰 수)','{}'::text[],false,'{"seq":10,"concept":"M2-2-u1-C1","difficulty":4,"kind":"essay","stem":"1000을 서로 다른 방법으로 두 가지 설명해 보세요. (예: ○○보다 ○만큼 더 큰 수)","answer_guide":{"answer":"예: 999보다 1 큰 수, 990보다 10 큰 수, 900보다 100 큰 수, 100이 10개인 수 가운데 두 가지","scoring_points":["서로 다른 설명 두 가지를 썼는가","설명한 수가 정말 1000인가(얼마만큼 큰지 바른가)","1만큼·10만큼·100만큼을 구별해 썼는가"]},"explanation":["1000은 여러 가지로 말할 수 있어요.","999보다 1, 990보다 10, 900보다 100 큰 수 모두 1000이에요.","얼마만큼인지 바르게 써야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L03_basic#1','math',2,2,'u1','L03','g2_2_math_u1_L03_basic','lesson_basic','M2-2-u1-C2',1,'mc','auto','천 모형이 4개 있어요. 모두 얼마인가요?',ARRAY['M2-2-u1-X03']::text[],true,'{"seq":1,"concept":"M2-2-u1-C2","difficulty":1,"kind":"mc","stem":"천 모형이 4개 있어요. 모두 얼마인가요?","options":[{"t":"4000","correct":true},{"t":"1004","mis":"M2-2-u1-X03"},{"t":"400","mis":"M2-2-u1-X03"}],"explanation":["천 모형 하나는 1000이에요.","1000이 4개이면 4000이에요.","개수 4는 천의 자리에 써요."],"asset":{"type":"blocks4","th":4,"h":0,"t":0,"o":0},"variant_rule":{"alt":[{"stem":"천 모형이 6개 있어요. 모두 얼마인가요?","options":[{"t":"6000","correct":true},{"t":"1006","mis":"M2-2-u1-X03"},{"t":"600","mis":"M2-2-u1-X03"}],"explanation":["천 모형 하나는 1000이에요.","1000이 6개이면 6000이에요.","개수 6은 천의 자리에 써요."],"asset":{"type":"blocks4","th":6,"h":0,"t":0,"o":0}},{"stem":"천 모형이 3개 있어요. 모두 얼마인가요?","options":[{"t":"3000","correct":true},{"t":"1003","mis":"M2-2-u1-X03"},{"t":"300","mis":"M2-2-u1-X03"}],"explanation":["천 모형 하나는 1000이에요.","1000이 3개이면 3000이에요.","천 모형 3개는 백 모형 3개(300)와 달라요."],"asset":{"type":"blocks4","th":3,"h":0,"t":0,"o":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L03_basic#2','math',2,2,'u1','L03','g2_2_math_u1_L03_basic','lesson_basic','M2-2-u1-C2',1,'mc','auto','1000이 5개이면 얼마인가요?',ARRAY['M2-2-u1-X03']::text[],true,'{"seq":2,"concept":"M2-2-u1-C2","difficulty":1,"kind":"mc","stem":"1000이 5개이면 얼마인가요?","options":[{"t":"5000","correct":true},{"t":"1005","mis":"M2-2-u1-X03"},{"t":"500","mis":"M2-2-u1-X03"}],"explanation":["1000이 5개이면 5000이에요.","「오천」이라고 읽어요.","개수는 천의 자리에 쓰고, 백·십·일의 자리는 0이에요."],"variant_rule":{"n4":{"ask":"thou"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L03_basic#3','math',2,2,'u1','L03','g2_2_math_u1_L03_basic','lesson_basic','M2-2-u1-C2',1,'mc','auto','7000을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u1-X07','M2-2-u1-X03']::text[],true,'{"seq":3,"concept":"M2-2-u1-C2","difficulty":1,"kind":"mc","stem":"7000을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"칠천","correct":true},{"t":"칠영영영","mis":"M2-2-u1-X07"},{"t":"칠백","mis":"M2-2-u1-X03"}],"explanation":["7000은 1000이 7개예요.","「칠천」이라고 읽어요.","0인 자리는 읽지 않아요."],"variant_rule":{"alt":[{"stem":"3000을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"삼천","correct":true},{"t":"삼영영영","mis":"M2-2-u1-X07"},{"t":"삼백","mis":"M2-2-u1-X03"}],"explanation":["3000은 1000이 3개예요.","「삼천」이라고 읽어요.","0인 자리는 읽지 않아요."]},{"stem":"「구천」을 수로 쓰면 무엇인가요?","options":[{"t":"9000","correct":true},{"t":"91000","mis":"M2-2-u1-X05"},{"t":"900","mis":"M2-2-u1-X03"}],"explanation":["「구천」은 1000이 9개예요.","수로 쓰면 9000이에요.","9 뒤에 0을 세 개 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L03_basic#4','math',2,2,'u1','L03','g2_2_math_u1_L03_basic','lesson_basic','M2-2-u1-C2',1,'sa','auto','8000은 1000이 몇 개인가요?','{}'::text[],true,'{"seq":4,"concept":"M2-2-u1-C2","difficulty":1,"kind":"sa","stem":"8000은 1000이 몇 개인가요?","answer":["8","8개"],"explanation":["8000은 천의 자리 숫자가 8이에요.","1000이 8개예요.","천의 자리 숫자가 1000의 개수예요."],"variant_rule":{"n4":{"ask":"tcount"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L03_basic#5','math',2,2,'u1','L03','g2_2_math_u1_L03_basic','lesson_basic','M2-2-u1-C2',2,'mc','auto','돈은 모두 얼마인가요?',ARRAY['M2-2-u1-X03']::text[],true,'{"seq":5,"concept":"M2-2-u1-C2","difficulty":2,"kind":"mc","stem":"돈은 모두 얼마인가요?","options":[{"t":"6000원","correct":true},{"t":"1006원","mis":"M2-2-u1-X03"},{"t":"600원","mis":"M2-2-u1-X03"}],"explanation":["천 원짜리 한 장은 1000원이에요.","천 원짜리가 6장이면 6000원이에요.","1000씩 세어 보세요 — 1000, 2000, … 6000."],"asset":{"type":"blocks4","th":6,"h":0,"t":0,"o":0,"unit":"coin"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 돈은 모두 얼마인가요?","options":[{"t":"4000원","correct":true},{"t":"1004원","mis":"M2-2-u1-X03"},{"t":"400원","mis":"M2-2-u1-X03"}],"explanation":["천 원짜리 한 장은 1000원이에요.","천 원짜리가 4장이면 4000원이에요.","1000씩 세어 보세요."],"asset":{"type":"blocks4","th":4,"h":0,"t":0,"o":0,"unit":"coin"}},{"stem":"이번에는 다른 보기예요. 돈은 모두 얼마인가요?","options":[{"t":"8000원","correct":true},{"t":"1008원","mis":"M2-2-u1-X03"},{"t":"800원","mis":"M2-2-u1-X03"}],"explanation":["천 원짜리 한 장은 1000원이에요.","천 원짜리가 8장이면 8000원이에요.","1000씩 세어 보세요."],"asset":{"type":"blocks4","th":8,"h":0,"t":0,"o":0,"unit":"coin"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L03_basic#6','math',2,2,'u1','L03','g2_2_math_u1_L03_basic','lesson_basic','M2-2-u1-C2',2,'match','auto','같은 수끼리 이어 보세요.','{}'::text[],true,'{"seq":6,"concept":"M2-2-u1-C2","difficulty":2,"kind":"match","stem":"같은 수끼리 이어 보세요.","pairs":[{"l":"1000이 3개","r":"3000"},{"l":"이천","r":"2000"},{"l":"천 모형 9개","r":"9000"}],"mis":"M2-2-u1-X03","explanation":["1000이 3개는 3000, 천 모형 9개는 9000이에요.","「이천」은 2000이에요.","1000의 개수는 천의 자리 숫자예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 같은 수끼리 이어 보세요.","pairs":[{"l":"1000이 5개","r":"5000"},{"l":"칠천","r":"7000"},{"l":"천 모형 4개","r":"4000"}],"explanation":["1000이 5개는 5000, 천 모형 4개는 4000이에요.","「칠천」은 7000이에요.","1000의 개수는 천의 자리 숫자예요."]},{"stem":"이번에는 다른 보기예요. 같은 수끼리 이어 보세요.","pairs":[{"l":"육천","r":"6000"},{"l":"1000이 2개","r":"2000"},{"l":"팔천","r":"8000"}],"explanation":["「육천」은 6000, 「팔천」은 8000이에요.","1000이 2개는 2000이에요.","몇천은 천의 자리만 0이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L03_basic#7','math',2,2,'u1','L03','g2_2_math_u1_L03_basic','lesson_basic','M2-2-u1-C2',2,'blank','auto','5000은 1000이 (        )개인 수예요.',ARRAY['M2-2-u1-X03','M2-2-u1-X09']::text[],true,'{"seq":7,"concept":"M2-2-u1-C2","difficulty":2,"kind":"blank","stem":"5000은 1000이 (        )개인 수예요.","options":[{"t":"5","correct":true},{"t":"50","mis":"M2-2-u1-X03"},{"t":"500","mis":"M2-2-u1-X09"}],"explanation":["5000은 천의 자리 숫자가 5예요.","그래서 1000이 5개예요.","천의 자리 숫자가 1000의 개수예요."],"variant_rule":{"n4":{"ask":"tcount"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L03_basic#8','math',2,2,'u1','L03','g2_2_math_u1_L03_basic','lesson_basic','M2-2-u1-C2',2,'ox','auto','천 모형 3개가 나타내는 수는 300이에요.',ARRAY['M2-2-u1-X03']::text[],true,'{"seq":8,"concept":"M2-2-u1-C2","difficulty":2,"kind":"ox","stem":"천 모형 3개가 나타내는 수는 300이에요.","answer":"X","reason_options":[{"t":"천 모형 하나는 1000이라 3개면 3000이니까","correct":true},{"t":"모형이 3개니까 3을 백의 자리에 쓰면 되니까","mis":"M2-2-u1-X03"}],"mis":"M2-2-u1-X03","explanation":["천 모형 하나는 1000이에요.","천 모형 3개는 1000이 3개 — 3000이에요.","그래서 틀린 말이에요 — 300은 백 모형 3개예요."],"variant_rule":{"alt":[{"stem":"1000이 9개이면 9000이에요.","answer":"O","reason_options":[{"t":"1000씩 9번 세면 9000이니까","correct":true},{"t":"1000이 9개면 1009라서","mis":"M2-2-u1-X03"}],"explanation":["1000, 2000, … 9000이에요.","1000이 9개는 9000이에요.","그래서 맞는 말이에요."]},{"stem":"천 모형 5개와 백 모형 5개가 나타내는 수는 같아요.","answer":"X","reason_options":[{"t":"천 모형 5개는 5000, 백 모형 5개는 500이니까","correct":true},{"t":"모형이 둘 다 5개니까","mis":"M2-2-u1-X03"}],"explanation":["천 모형 5개는 1000이 5개 — 5000이에요.","백 모형 5개는 100이 5개 — 500이에요.","그래서 틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L03_basic#9','math',2,2,'u1','L03','g2_2_math_u1_L03_basic','lesson_basic','M2-2-u1-C2',2,'mc','auto','3000보다 1000만큼 더 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X12']::text[],true,'{"seq":9,"concept":"M2-2-u1-C2","difficulty":2,"kind":"mc","stem":"3000보다 1000만큼 더 큰 수는 무엇인가요?","options":[{"t":"4000","correct":true},{"t":"3100","mis":"M2-2-u1-X12"},{"t":"3010","mis":"M2-2-u1-X12"}],"explanation":["1000만큼 더 크면 천의 자리 숫자가 1 커져요.","3000보다 1000 큰 수는 4000이에요.","100만큼·10만큼과 헷갈리지 않아요."],"variant_rule":{"alt":[{"stem":"7000보다 1000만큼 더 작은 수는 무엇인가요?","options":[{"t":"6000","correct":true},{"t":"6900","mis":"M2-2-u1-X12"},{"t":"8000","mis":"M2-2-u1-X15"}],"explanation":["1000만큼 작으면 천의 자리 숫자가 1 작아져요.","7000보다 1000 작은 수는 6000이에요.","「작은」인지 「큰」인지 잘 읽어요."]},{"stem":"5000보다 1000만큼 더 큰 수는 무엇인가요?","options":[{"t":"6000","correct":true},{"t":"5100","mis":"M2-2-u1-X12"},{"t":"5001","mis":"M2-2-u1-X12"}],"explanation":["1000만큼 더 크면 천의 자리 숫자가 1 커져요.","5000보다 1000 큰 수는 6000이에요.","100만큼·1만큼과 헷갈리지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L03_basic#10','math',2,2,'u1','L03','g2_2_math_u1_L03_basic','lesson_basic','M2-2-u1-C2',3,'mc','auto','1000씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u1-X11']::text[],true,'{"seq":10,"concept":"M2-2-u1-C2","difficulty":3,"kind":"mc","stem":"1000씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"7000","correct":true},{"t":"6100","mis":"M2-2-u1-X11"},{"t":"6010","mis":"M2-2-u1-X11"}],"explanation":["1000씩 뛰면 천의 자리 숫자가 1씩 커져요.","6000에서 1000만큼 뛰면 7000이에요.","다른 자리 숫자는 그대로예요."],"asset":{"type":"jump_row","cells":[3000,4000,5000,6000,null],"step":1000},"variant_rule":{"skip4":{"ask":"next","step":[1000]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L03_challenge#1','math',2,2,'u1','L03','g2_2_math_u1_L03_challenge','lesson_challenge','M2-2-u1-C7',2,'mc','auto','3400은 100이 몇 개인가요?',ARRAY['M2-2-u1-X10','M2-2-u1-X03']::text[],true,'{"seq":1,"concept":"M2-2-u1-C7","difficulty":2,"kind":"mc","stem":"3400은 100이 몇 개인가요?","options":[{"t":"34","correct":true},{"t":"4","mis":"M2-2-u1-X10"},{"t":"3","mis":"M2-2-u1-X03"}],"explanation":["3400은 1000이 3개, 100이 4개예요.","1000 하나는 100이 10개 — 100이 30개와 4개, 모두 34개예요.","1000 속에도 100이 10개 들어 있어요."],"variant_rule":{"n4":{"ask":"hcount"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L03_challenge#2','math',2,2,'u1','L03','g2_2_math_u1_L03_challenge','lesson_challenge','M2-2-u1-C2',2,'error','auto','친구들이 6000에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u1-X03','M2-2-u1-X07','M2-2-u1-X12']::text[],true,'{"seq":2,"concept":"M2-2-u1-C2","difficulty":2,"kind":"error","stem":"친구들이 6000에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우: 6000은 1000이 60개야.","correct":true,"mis_target":"M2-2-u1-X03"},{"t":"하린: 6000은 「육천」이라고 읽어.","mis":"M2-2-u1-X07"},{"t":"도윤: 6000은 5000보다 1000 큰 수야.","mis":"M2-2-u1-X12"}],"explanation":["6000은 천의 자리 숫자가 6이에요.","그래서 1000이 6개예요 — 60개가 아니에요.","은우가 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"친구들이 3000에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라온: 1000이 3개니까 1003이라고 써.","correct":true,"mis_target":"M2-2-u1-X03"},{"t":"서준: 3000은 「삼천」이라고 읽어.","mis":"M2-2-u1-X07"},{"t":"지아: 3000은 2000보다 1000 큰 수야.","mis":"M2-2-u1-X12"}],"explanation":["1000이 3개이면 3000이에요.","개수를 일의 자리에 붙여 1003으로 쓰지 않아요.","라온이가 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L03_challenge#3','math',2,2,'u1','L03','g2_2_math_u1_L03_challenge','lesson_challenge','M2-2-u1-C7',3,'mc','auto','돈은 모두 얼마인가요?',ARRAY['M2-2-u1-X10']::text[],true,'{"seq":3,"concept":"M2-2-u1-C7","difficulty":3,"kind":"mc","stem":"돈은 모두 얼마인가요?","options":[{"t":"4000원","correct":true},{"t":"31000원","mis":"M2-2-u1-X10"},{"t":"3100원","mis":"M2-2-u1-X10"}],"explanation":["100원짜리 10개는 천 원짜리 1장과 같아요.","천 원짜리가 3장과 1장 — 4000원이에요.","한 자리에 10개가 모이면 윗자리 1개로 바꿔요."],"asset":{"type":"blocks4","th":3,"h":10,"t":0,"o":0,"unit":"coin"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 돈은 모두 얼마인가요?","options":[{"t":"6000원","correct":true},{"t":"51000원","mis":"M2-2-u1-X10"},{"t":"5100원","mis":"M2-2-u1-X10"}],"explanation":["100원짜리 10개는 천 원짜리 1장과 같아요.","천 원짜리가 5장과 1장 — 6000원이에요.","한 자리에 10개가 모이면 윗자리 1개로 바꿔요."],"asset":{"type":"blocks4","th":5,"h":10,"t":0,"o":0,"unit":"coin"}},{"stem":"이번에는 다른 보기예요. 돈은 모두 얼마인가요?","options":[{"t":"2900원","correct":true},{"t":"11900원","mis":"M2-2-u1-X10"},{"t":"1900원","mis":"M2-2-u1-X10"}],"explanation":["100원짜리 19개는 천 원짜리 1장과 100원짜리 9개로 바꿀 수 있어요.","천 원짜리 2장, 100원짜리 9개 — 2900원이에요.","10개씩 묶어 윗자리로 바꿔요."],"asset":{"type":"blocks4","th":1,"h":19,"t":0,"o":0,"unit":"coin"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L03_challenge#4','math',2,2,'u1','L03','g2_2_math_u1_L03_challenge','lesson_challenge','M2-2-u1-C2',3,'sa','auto','태극기 한 개가 1000원이에요. 태극기 7개를 사려면 얼마를 내야 하나요?','{}'::text[],true,'{"seq":4,"concept":"M2-2-u1-C2","difficulty":3,"kind":"sa","stem":"태극기 한 개가 1000원이에요. 태극기 7개를 사려면 얼마를 내야 하나요?","answer":["7000","7000원"],"explanation":["태극기 한 개에 1000원이에요.","1000이 7개이면 7000이에요.","1000씩 세어 보세요 — 1000, 2000, … 7000."],"variant_rule":{"alt":[{"stem":"공책 한 권이 1000원이에요. 5000원으로 공책을 몇 권 살 수 있나요?","answer":["5","5권"],"explanation":["5000은 1000이 5개예요.","한 권에 1000원이니 5권을 살 수 있어요.","1000씩 세어 5000이 될 때까지 세어요."]},{"stem":"연이 한 상자에 1000개씩 들어 있어요. 4상자에는 연이 모두 몇 개인가요?","answer":["4000","4000개"],"explanation":["한 상자에 1000개씩이에요.","1000이 4개이면 4000이에요.","1000씩 세어 보세요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L03_challenge#5','math',2,2,'u1','L03','g2_2_math_u1_L03_challenge','lesson_challenge','M2-2-u1-C7',3,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-2-u1-X10']::text[],true,'{"seq":5,"concept":"M2-2-u1-C7","difficulty":3,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"3000","correct":true},{"t":"21000","mis":"M2-2-u1-X10"},{"t":"2100","mis":"M2-2-u1-X10"}],"explanation":["백 모형 10개는 천 모형 1개와 같아요.","천 모형이 2개와 1개 — 3000이에요.","한 자리에 10개가 모이면 윗자리 1개로 바꿔요."],"asset":{"type":"blocks4","th":2,"h":10,"t":0,"o":0},"variant_rule":{"n4":{"ask":"build","carry":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L03_challenge#6','math',2,2,'u1','L03','g2_2_math_u1_L03_challenge','lesson_challenge','M2-2-u1-C2',3,'mc','auto','8000은 5000보다 1000이 몇 개 더 많은가요?',ARRAY['M2-2-u1-X09','M2-2-u1-X03']::text[],true,'{"seq":6,"concept":"M2-2-u1-C2","difficulty":3,"kind":"mc","stem":"8000은 5000보다 1000이 몇 개 더 많은가요?","options":[{"t":"3","correct":true},{"t":"3000","mis":"M2-2-u1-X09"},{"t":"30","mis":"M2-2-u1-X03"}],"explanation":["8000은 1000이 8개, 5000은 1000이 5개예요.","8은 5보다 3 커요.","그래서 1000이 3개 더 많아요."],"variant_rule":{"alt":[{"stem":"9000은 2000보다 1000이 몇 개 더 많은가요?","options":[{"t":"7","correct":true},{"t":"7000","mis":"M2-2-u1-X09"},{"t":"70","mis":"M2-2-u1-X03"}],"explanation":["9000은 1000이 9개, 2000은 1000이 2개예요.","9는 2보다 7 커요.","그래서 1000이 7개 더 많아요."]},{"stem":"6000은 4000보다 1000이 몇 개 더 많은가요?","options":[{"t":"2","correct":true},{"t":"2000","mis":"M2-2-u1-X09"},{"t":"20","mis":"M2-2-u1-X03"}],"explanation":["6000은 1000이 6개, 4000은 1000이 4개예요.","6은 4보다 2 커요.","그래서 1000이 2개 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L03_challenge#7','math',2,2,'u1','L03','g2_2_math_u1_L03_challenge','lesson_challenge','M2-2-u1-C7',3,'ox','auto','1000이 2개, 100이 10개이면 3000이에요.',ARRAY['M2-2-u1-X10']::text[],true,'{"seq":7,"concept":"M2-2-u1-C7","difficulty":3,"kind":"ox","stem":"1000이 2개, 100이 10개이면 3000이에요.","answer":"O","reason_options":[{"t":"100이 10개는 1000이라 1000이 3개가 되니까","correct":true},{"t":"2 뒤에 10을 붙여 210이 되니까","mis":"M2-2-u1-X10"}],"mis":"M2-2-u1-X10","explanation":["100이 10개는 1000이에요.","1000이 2개와 1개 — 1000이 3개라 3000이에요.","그래서 맞는 말이에요."],"variant_rule":{"alt":[{"stem":"100이 30개인 수는 3000이에요.","answer":"O","reason_options":[{"t":"100이 10개마다 1000 — 30개는 1000이 3개니까","correct":true},{"t":"100이 30개면 10030이니까","mis":"M2-2-u1-X02"}],"explanation":["100이 10개면 1000이에요.","100이 30개는 1000이 3개 — 3000이에요.","그래서 맞는 말이에요."]},{"stem":"1000이 4개, 100이 12개이면 41200이에요.","answer":"X","reason_options":[{"t":"100이 12개는 1000이 1개, 100이 2개라 5200이니까","correct":true},{"t":"개수를 차례로 이어 쓰면 되니까","mis":"M2-2-u1-X10"}],"explanation":["100이 12개는 1000이 1개, 100이 2개예요.","1000이 5개, 100이 2개 — 5200이에요.","그래서 틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L03_challenge#8','math',2,2,'u1','L03','g2_2_math_u1_L03_challenge','lesson_challenge','M2-2-u1-C2',4,'mc','auto','어떤 수는 1000이 4개인 수보다 1000이 3개 더 많아요. 어떤 수는 무엇인가요?',ARRAY['M2-2-u1-X03']::text[],true,'{"seq":8,"concept":"M2-2-u1-C2","difficulty":4,"kind":"mc","stem":"어떤 수는 1000이 4개인 수보다 1000이 3개 더 많아요. 어떤 수는 무엇인가요?","options":[{"t":"7000","correct":true},{"t":"4300","mis":"M2-2-u1-X03"},{"t":"4003","mis":"M2-2-u1-X03"}],"explanation":["1000이 4개에 3개가 더 많으면 1000이 7개예요.","1000이 7개인 수는 7000이에요.","1000의 개수는 모두 천의 자리에 모여요."],"variant_rule":{"alt":[{"stem":"어떤 수는 1000이 8개인 수보다 1000이 2개 더 적어요. 어떤 수는 무엇인가요?","options":[{"t":"6000","correct":true},{"t":"8200","mis":"M2-2-u1-X03"},{"t":"10000","mis":"M2-2-u1-X15"}],"explanation":["1000이 8개에서 2개가 적으면 1000이 6개예요.","1000이 6개인 수는 6000이에요.","「적어요」를 잘 읽어요."]},{"stem":"어떤 수는 1000이 2개인 수보다 1000이 5개 더 많아요. 어떤 수는 무엇인가요?","options":[{"t":"7000","correct":true},{"t":"2500","mis":"M2-2-u1-X03"},{"t":"2005","mis":"M2-2-u1-X03"}],"explanation":["1000이 2개에 5개가 더 많으면 1000이 7개예요.","1000이 7개인 수는 7000이에요.","1000의 개수는 모두 천의 자리에 모여요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L03_challenge#9','math',2,2,'u1','L03','g2_2_math_u1_L03_challenge','lesson_challenge','M2-2-u1-C2',4,'mc','auto','천 원짜리로 9000원을 내려고 해요. 지금 천 원짜리가 5장 있다면 몇 장이 더 있어야 하나요?',ARRAY['M2-2-u1-X09','M2-2-u1-X15']::text[],true,'{"seq":9,"concept":"M2-2-u1-C2","difficulty":4,"kind":"mc","stem":"천 원짜리로 9000원을 내려고 해요. 지금 천 원짜리가 5장 있다면 몇 장이 더 있어야 하나요?","options":[{"t":"4","correct":true},{"t":"4000","mis":"M2-2-u1-X09"},{"t":"9","mis":"M2-2-u1-X15"}],"explanation":["9000원은 천 원짜리 9장이에요.","5장이 있으니 9장이 되려면 4장 더 — 6, 7, 8, 9로 세어요.","묻는 것은 지폐 「장 수」예요."],"variant_rule":{"alt":[{"stem":"천 원짜리로 8000원을 내려고 해요. 지금 천 원짜리가 3장 있다면 몇 장이 더 있어야 하나요?","options":[{"t":"5","correct":true},{"t":"5000","mis":"M2-2-u1-X09"},{"t":"8","mis":"M2-2-u1-X15"}],"explanation":["8000원은 천 원짜리 8장이에요.","3장이 있으니 5장 더 있어야 해요.","묻는 것은 지폐 「장 수」예요."]},{"stem":"5000원짜리 선물을 사려고 천 원짜리 2장을 모았어요. 몇 장을 더 모아야 하나요?","options":[{"t":"3","correct":true},{"t":"3000","mis":"M2-2-u1-X09"},{"t":"5","mis":"M2-2-u1-X15"}],"explanation":["5000원은 천 원짜리 5장이에요.","2장이 있으니 3장 더 모아야 해요.","묻는 것은 지폐 「장 수」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L03_challenge#10','math',2,2,'u1','L03','g2_2_math_u1_L03_challenge','lesson_challenge','M2-2-u1-C7',4,'essay','teacher','5000을 「1000이 몇 개」와 「100이 몇 개」 두 가지로 나타내고, 그렇게 생각한 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-2-u1-C7","difficulty":4,"kind":"essay","stem":"5000을 「1000이 몇 개」와 「100이 몇 개」 두 가지로 나타내고, 그렇게 생각한 까닭을 써 보세요.","answer_guide":{"answer":"1000이 5개, 100이 50개. 1000 하나는 100이 10개이므로 1000이 5개는 100이 50개이다.","scoring_points":["1000이 5개라고 썼는가","100이 50개라고 썼는가","1000 하나가 100이 10개라는 까닭을 말했는가"]},"explanation":["5000은 천의 자리 숫자가 5 — 1000이 5개예요.","1000 하나는 100이 10개이니 100이 50개예요.","한 수를 여러 묶음으로 나타낼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L04_basic#1','math',2,2,'u1','L04','g2_2_math_u1_L04_basic','lesson_basic','M2-2-u1-C3',1,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-2-u1-X06','M2-2-u1-X05']::text[],true,'{"seq":1,"concept":"M2-2-u1-C3","difficulty":1,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"2543","correct":true},{"t":"3452","mis":"M2-2-u1-X06"},{"t":"2000500403","mis":"M2-2-u1-X05"}],"explanation":["1000이 2개, 100이 5개, 10이 4개, 1이 3개예요.","천의 자리 2, 백의 자리 5, 십의 자리 4, 일의 자리 3 — 2543이에요.","천·백·십·일 차례로 숫자를 써요."],"asset":{"type":"blocks4","th":2,"h":5,"t":4,"o":3},"variant_rule":{"n4":{"ask":"build"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L04_basic#2','math',2,2,'u1','L04','g2_2_math_u1_L04_basic','lesson_basic','M2-2-u1-C3',1,'sa','auto','1000이 3개, 100이 2개, 10이 5개, 1이 8개인 수는 무엇인가요?','{}'::text[],true,'{"seq":2,"concept":"M2-2-u1-C3","difficulty":1,"kind":"sa","stem":"1000이 3개, 100이 2개, 10이 5개, 1이 8개인 수는 무엇인가요?","answer":["3258"],"explanation":["1000이 3개, 100이 2개, 10이 5개, 1이 8개예요.","천의 자리 3, 백의 자리 2, 십의 자리 5, 일의 자리 8 — 3258이에요.","천·백·십·일 차례로 숫자를 써요."],"variant_rule":{"n4":{"ask":"build"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L04_basic#3','math',2,2,'u1','L04','g2_2_math_u1_L04_basic','lesson_basic','M2-2-u1-C3',1,'mc','auto','4392를 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u1-X07']::text[],true,'{"seq":3,"concept":"M2-2-u1-C3","difficulty":1,"kind":"mc","stem":"4392를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"사천삼백구십이","correct":true},{"t":"사삼구이","mis":"M2-2-u1-X07"},{"t":"사천삼구십이","mis":"M2-2-u1-X07"}],"explanation":["4392는 천의 자리 4, 백의 자리 3, 십의 자리 9, 일의 자리 2예요.","「사천삼백구십이」라고 읽어요.","숫자 뒤에 자리 이름(천·백·십)을 붙여 읽어요."],"variant_rule":{"n4":{"ask":"read"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L04_basic#4','math',2,2,'u1','L04','g2_2_math_u1_L04_basic','lesson_basic','M2-2-u1-C3',1,'mc','auto','「육천삼백오십이」를 수로 쓰면 무엇인가요?',ARRAY['M2-2-u1-X05','M2-2-u1-X06']::text[],true,'{"seq":4,"concept":"M2-2-u1-C3","difficulty":1,"kind":"mc","stem":"「육천삼백오십이」를 수로 쓰면 무엇인가요?","options":[{"t":"6352","correct":true},{"t":"6000300502","mis":"M2-2-u1-X05"},{"t":"6532","mis":"M2-2-u1-X06"}],"explanation":["「육천삼백오십이」는 1000이 6개, 100이 3개, 10이 5개, 1이 2개예요.","수로 쓰면 6352예요.","읽은 소리를 그대로 이어 쓰지 않아요 — 네 자리에 숫자 하나씩."],"variant_rule":{"n4":{"ask":"write"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L04_basic#5','math',2,2,'u1','L04','g2_2_math_u1_L04_basic','lesson_basic','M2-2-u1-C3',2,'mc','auto','1000이 3개, 10이 2개, 1이 7개인 수는 무엇인가요?',ARRAY['M2-2-u1-X04','M2-2-u1-X05']::text[],true,'{"seq":5,"concept":"M2-2-u1-C3","difficulty":2,"kind":"mc","stem":"1000이 3개, 10이 2개, 1이 7개인 수는 무엇인가요?","options":[{"t":"3027","correct":true},{"t":"327","mis":"M2-2-u1-X04"},{"t":"3000207","mis":"M2-2-u1-X05"}],"explanation":["1000이 3개, 10이 2개, 1이 7개예요 — 100은 없어요.","천의 자리 3, 백의 자리 0, 십의 자리 2, 일의 자리 7 — 3027이에요.","없는 자리에는 0을 써서 자리를 지켜요."],"variant_rule":{"n4":{"ask":"build","zero":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L04_basic#6','math',2,2,'u1','L04','g2_2_math_u1_L04_basic','lesson_basic','M2-2-u1-C3',2,'mc','auto','6035를 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u1-X07']::text[],true,'{"seq":6,"concept":"M2-2-u1-C3","difficulty":2,"kind":"mc","stem":"6035를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"육천삼십오","correct":true},{"t":"육천영백삼십오","mis":"M2-2-u1-X07"},{"t":"육영삼오","mis":"M2-2-u1-X07"}],"explanation":["6035는 천의 자리 6, 백의 자리 0, 십의 자리 3, 일의 자리 5예요.","「육천삼십오」라고 읽어요.","0이 있는 자리는 읽지 않아요."],"variant_rule":{"n4":{"ask":"read","zero":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L04_basic#7','math',2,2,'u1','L04','g2_2_math_u1_L04_basic','lesson_basic','M2-2-u1-C3',2,'mc','auto','돈은 모두 얼마인가요?',ARRAY['M2-2-u1-X06']::text[],true,'{"seq":7,"concept":"M2-2-u1-C3","difficulty":2,"kind":"mc","stem":"돈은 모두 얼마인가요?","options":[{"t":"3460원","correct":true},{"t":"6430원","mis":"M2-2-u1-X06"},{"t":"4360원","mis":"M2-2-u1-X06"}],"explanation":["천 원짜리 3장, 100원짜리 4개, 10원짜리 6개예요.","천 원짜리부터 차례로 세면 3460원이에요.","큰 돈부터 차례로 세어요."],"asset":{"type":"blocks4","th":3,"h":4,"t":6,"o":0,"unit":"coin"},"variant_rule":{"n4":{"ask":"build"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L04_basic#8','math',2,2,'u1','L04','g2_2_math_u1_L04_basic','lesson_basic','M2-2-u1-C3',2,'ox','auto','「구천이」를 수로 쓰면 92예요.',ARRAY['M2-2-u1-X04']::text[],true,'{"seq":8,"concept":"M2-2-u1-C3","difficulty":2,"kind":"ox","stem":"「구천이」를 수로 쓰면 92예요.","answer":"X","reason_options":[{"t":"백·십의 자리에 0을 써서 9002니까","correct":true},{"t":"읽은 숫자만 쓰면 되니까","mis":"M2-2-u1-X04"}],"mis":"M2-2-u1-X04","explanation":["「구천이」는 1000이 9개, 1이 2개예요.","백의 자리와 십의 자리에 0을 써서 9002예요.","그래서 틀린 말이에요."],"variant_rule":{"alt":[{"stem":"「삼천사백」을 수로 쓰면 3400이에요.","answer":"O","reason_options":[{"t":"십·일의 자리에 0을 써서 3400이니까","correct":true},{"t":"읽지 않은 자리는 쓰지 않으니까 34라서","mis":"M2-2-u1-X04"}],"explanation":["「삼천사백」은 1000이 3개, 100이 4개예요.","십의 자리와 일의 자리에 0을 써서 3400이에요.","그래서 맞는 말이에요."]},{"stem":"「육천팔」을 수로 쓰면 60008이에요.","answer":"X","reason_options":[{"t":"네 자리 수는 숫자가 네 개라 6008이니까","correct":true},{"t":"육천은 6000, 팔은 8이라 이어 쓰니까","mis":"M2-2-u1-X05"}],"explanation":["「육천팔」은 1000이 6개, 1이 8개예요.","백·십의 자리에 0을 써서 6008이에요.","읽은 소리를 이어 쓰지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L04_basic#9','math',2,2,'u1','L04','g2_2_math_u1_L04_basic','lesson_basic','M2-2-u1-C3',2,'match','auto','수와 읽기를 바르게 이어 보세요.','{}'::text[],true,'{"seq":9,"concept":"M2-2-u1-C3","difficulty":2,"kind":"match","stem":"수와 읽기를 바르게 이어 보세요.","pairs":[{"l":"3046","r":"삼천사십육"},{"l":"3406","r":"삼천사백육"},{"l":"3460","r":"삼천사백육십"}],"mis":"M2-2-u1-X04","explanation":["3046은 삼천사십육, 3406은 삼천사백육이에요.","3460은 삼천사백육십이에요.","0인 자리는 읽지 않아요 — 어느 자리가 0인지 잘 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 수와 읽기를 바르게 이어 보세요.","pairs":[{"l":"5815","r":"오천팔백십오"},{"l":"5085","r":"오천팔십오"},{"l":"5850","r":"오천팔백오십"}],"explanation":["5815는 오천팔백십오, 5085는 오천팔십오예요.","5850은 오천팔백오십이에요.","0인 자리는 읽지 않아요."]},{"stem":"이번에는 다른 보기예요. 수와 읽기를 바르게 이어 보세요.","pairs":[{"l":"7472","r":"칠천사백칠십이"},{"l":"7427","r":"칠천사백이십칠"},{"l":"7742","r":"칠천칠백사십이"}],"explanation":["7472는 칠천사백칠십이, 7427은 칠천사백이십칠이에요.","7742는 칠천칠백사십이예요.","자리 순서를 섞지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L04_basic#10','math',2,2,'u1','L04','g2_2_math_u1_L04_basic','lesson_basic','M2-2-u1-C7',3,'mc','auto','손수건이 1000장씩 2묶음, 100장씩 4묶음, 10장씩 3묶음, 낱장 15장 있어요. 손수건은 모두 몇 장인가요?',ARRAY['M2-2-u1-X10']::text[],true,'{"seq":10,"concept":"M2-2-u1-C7","difficulty":3,"kind":"mc","stem":"손수건이 1000장씩 2묶음, 100장씩 4묶음, 10장씩 3묶음, 낱장 15장 있어요. 손수건은 모두 몇 장인가요?","options":[{"t":"2445","correct":true},{"t":"24315","mis":"M2-2-u1-X10"},{"t":"2435","mis":"M2-2-u1-X10"}],"explanation":["낱장 15장은 10장씩 1묶음과 낱장 5장으로 바꿀 수 있어요.","그러면 1000이 2개, 100이 4개, 10이 4개, 1이 5개 — 2445예요.","한 자리에 10개가 넘으면 윗자리로 바꿔요."],"variant_rule":{"alt":[{"stem":"연이 1000개씩 3상자, 100개씩 12상자, 10개씩 5봉지 있어요. 연은 모두 몇 개인가요?","options":[{"t":"4250","correct":true},{"t":"31250","mis":"M2-2-u1-X10"},{"t":"3250","mis":"M2-2-u1-X10"}],"explanation":["100개씩 12상자는 1000개 1상자와 100개씩 2상자예요.","그러면 1000이 4개, 100이 2개, 10이 5개 — 4250이에요.","한 자리에 10개가 넘으면 윗자리로 바꿔요."]},{"stem":"색종이가 1000장씩 1묶음, 100장씩 6묶음, 10장씩 14묶음 있어요. 모두 몇 장인가요?","options":[{"t":"1740","correct":true},{"t":"16140","mis":"M2-2-u1-X10"},{"t":"1640","mis":"M2-2-u1-X10"}],"explanation":["10장씩 14묶음은 100장씩 1묶음과 10장씩 4묶음이에요.","그러면 1000이 1개, 100이 7개, 10이 4개 — 1740이에요.","한 자리에 10개가 넘으면 윗자리로 바꿔요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L04_challenge#1','math',2,2,'u1','L04','g2_2_math_u1_L04_challenge','lesson_challenge','M2-2-u1-C3',2,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-2-u1-X04','M2-2-u1-X05']::text[],true,'{"seq":1,"concept":"M2-2-u1-C3","difficulty":2,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"4060","correct":true},{"t":"46","mis":"M2-2-u1-X04"},{"t":"400060","mis":"M2-2-u1-X05"}],"explanation":["1000이 4개, 10이 6개예요 — 백 모형과 일 모형이 없어요.","천의 자리 4, 백의 자리 0, 십의 자리 6, 일의 자리 0 — 4060이에요.","없는 자리에는 0을 써서 자리를 지켜요."],"asset":{"type":"blocks4","th":4,"h":0,"t":6,"o":0},"variant_rule":{"n4":{"ask":"build","zero":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L04_challenge#2','math',2,2,'u1','L04','g2_2_math_u1_L04_challenge','lesson_challenge','M2-2-u1-C3',2,'sa','auto','「칠천십」을 수로 쓰면 무엇인가요?','{}'::text[],true,'{"seq":2,"concept":"M2-2-u1-C3","difficulty":2,"kind":"sa","stem":"「칠천십」을 수로 쓰면 무엇인가요?","answer":["7010"],"explanation":["「칠천십」은 1000이 7개, 10이 1개예요.","백의 자리와 일의 자리에 0을 써서 7010이에요.","읽지 않은 자리에는 0을 써요."],"variant_rule":{"n4":{"ask":"write","zero":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L04_challenge#3','math',2,2,'u1','L04','g2_2_math_u1_L04_challenge','lesson_challenge','M2-2-u1-C7',3,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-2-u1-X10']::text[],true,'{"seq":3,"concept":"M2-2-u1-C7","difficulty":3,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"4254","correct":true},{"t":"31254","mis":"M2-2-u1-X10"},{"t":"3254","mis":"M2-2-u1-X10"}],"explanation":["백 모형 12개는 천 모형 1개와 백 모형 2개로 바꿀 수 있어요.","1000이 4개, 100이 2개, 10이 5개, 1이 4개 — 4254예요.","한 자리에 10개가 모이면 바로 윗자리 1개로 바꿔요."],"asset":{"type":"blocks4","th":3,"h":12,"t":5,"o":4},"variant_rule":{"n4":{"ask":"build","carry":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L04_challenge#4','math',2,2,'u1','L04','g2_2_math_u1_L04_challenge','lesson_challenge','M2-2-u1-C3',3,'error','auto','친구들이 읽은 수를 썼어요. 잘못 쓴 친구는 누구인가요?',ARRAY['M2-2-u1-X04','M2-2-u1-X05']::text[],true,'{"seq":4,"concept":"M2-2-u1-C3","difficulty":3,"kind":"error","stem":"친구들이 읽은 수를 썼어요. 잘못 쓴 친구는 누구인가요?","options":[{"t":"서준: 「사천오」 → 45","correct":true,"mis_target":"M2-2-u1-X04"},{"t":"지아: 「사천오십」 → 4050","mis":"M2-2-u1-X04"},{"t":"민재: 「사천오백오십」 → 4550","mis":"M2-2-u1-X05"}],"explanation":["「사천오」는 1000이 4개, 1이 5개예요.","백·십의 자리에 0을 써서 4005라고 써야 해요.","서준이가 잘못 썼어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 읽은 수를 썼어요. 잘못 쓴 친구는 누구인가요?","options":[{"t":"하윤: 「이천칠백」 → 2000700","correct":true,"mis_target":"M2-2-u1-X05"},{"t":"도하: 「이천칠」 → 2007","mis":"M2-2-u1-X04"},{"t":"나은: 「이천칠백칠십」 → 2770","mis":"M2-2-u1-X06"}],"explanation":["「이천칠백」은 1000이 2개, 100이 7개예요.","네 자리에 숫자 하나씩 — 2700이라고 써야 해요.","하윤이가 잘못 썼어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L04_challenge#5','math',2,2,'u1','L04','g2_2_math_u1_L04_challenge','lesson_challenge','M2-2-u1-C7',3,'mc','auto','1000이 6개, 100이 13개, 10이 2개인 수는 무엇인가요?',ARRAY['M2-2-u1-X10']::text[],true,'{"seq":5,"concept":"M2-2-u1-C7","difficulty":3,"kind":"mc","stem":"1000이 6개, 100이 13개, 10이 2개인 수는 무엇인가요?","options":[{"t":"7320","correct":true},{"t":"61320","mis":"M2-2-u1-X10"},{"t":"6320","mis":"M2-2-u1-X10"}],"explanation":["100이 13개는 1000이 1개, 100이 3개예요.","그러면 1000이 7개, 100이 3개, 10이 2개 — 7320이에요.","한 자리에 10개가 넘으면 윗자리로 바꿔요."],"variant_rule":{"alt":[{"stem":"1000이 2개, 100이 5개, 10이 17개인 수는 무엇인가요?","options":[{"t":"2670","correct":true},{"t":"25170","mis":"M2-2-u1-X10"},{"t":"2570","mis":"M2-2-u1-X10"}],"explanation":["10이 17개는 100이 1개, 10이 7개예요.","그러면 1000이 2개, 100이 6개, 10이 7개 — 2670이에요.","한 자리에 10개가 넘으면 윗자리로 바꿔요."]},{"stem":"1000이 4개, 100이 11개, 1이 3개인 수는 무엇인가요?","options":[{"t":"5103","correct":true},{"t":"41103","mis":"M2-2-u1-X10"},{"t":"4103","mis":"M2-2-u1-X10"}],"explanation":["100이 11개는 1000이 1개, 100이 1개예요.","그러면 1000이 5개, 100이 1개, 10이 0개, 1이 3개 — 5103이에요.","한 자리에 10개가 넘으면 윗자리로 바꿔요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L04_challenge#6','math',2,2,'u1','L04','g2_2_math_u1_L04_challenge','lesson_challenge','M2-2-u1-C7',3,'mc','auto','100이 25개인 수는 얼마인가요?',ARRAY['M2-2-u1-X02','M2-2-u1-X10']::text[],true,'{"seq":6,"concept":"M2-2-u1-C7","difficulty":3,"kind":"mc","stem":"100이 25개인 수는 얼마인가요?","options":[{"t":"2500","correct":true},{"t":"10025","mis":"M2-2-u1-X02"},{"t":"250","mis":"M2-2-u1-X10"}],"explanation":["100이 10개면 1000이에요.","100이 25개는 1000이 2개, 100이 5개 — 2500이에요.","100이 10개 넘게 모이면 1000으로 바꿔 세요."],"variant_rule":{"n4":{"ask":"hund"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L04_challenge#7','math',2,2,'u1','L04','g2_2_math_u1_L04_challenge','lesson_challenge','M2-2-u1-C3',3,'ox','auto','천 모형 3개, 일 모형 8개를 수로 쓰면 38이에요.',ARRAY['M2-2-u1-X04']::text[],true,'{"seq":7,"concept":"M2-2-u1-C3","difficulty":3,"kind":"ox","stem":"천 모형 3개, 일 모형 8개를 수로 쓰면 38이에요.","answer":"X","reason_options":[{"t":"백·십의 자리에 0을 써서 3008이니까","correct":true},{"t":"없는 모형은 쓰지 않으니까","mis":"M2-2-u1-X04"}],"mis":"M2-2-u1-X04","explanation":["천 모형 3개, 일 모형 8개 — 백 모형과 십 모형은 없어요.","백·십의 자리에 0을 써서 3008이에요.","그래서 틀린 말이에요."],"variant_rule":{"alt":[{"stem":"천 모형 2개, 십 모형 5개, 일 모형 1개를 수로 쓰면 2051이에요.","answer":"O","reason_options":[{"t":"백의 자리에 0을 써서 2051이니까","correct":true},{"t":"백 모형이 없으니 251이라서","mis":"M2-2-u1-X04"}],"explanation":["천 모형 2개, 십 모형 5개, 일 모형 1개 — 백 모형은 없어요.","백의 자리에 0을 써서 2051이에요.","그래서 맞는 말이에요."]},{"stem":"천 모형 2개, 백 모형 9개, 일 모형 4개를 수로 쓰면 4092예요.","answer":"X","reason_options":[{"t":"천·백·십·일 차례로 써서 2904니까","correct":true},{"t":"많이 있는 모형부터 쓰니까","mis":"M2-2-u1-X06"}],"explanation":["천의 자리 2, 백의 자리 9, 십의 자리 0, 일의 자리 4예요.","그래서 2904예요.","자리 순서를 바꾸지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L04_challenge#8','math',2,2,'u1','L04','g2_2_math_u1_L04_challenge','lesson_challenge','M2-2-u1-C3',4,'mc','auto','천의 자리 숫자가 5, 백의 자리 숫자가 0이고, 십의 자리 숫자는 천의 자리 숫자보다 3 작고, 일의 자리 숫자는 십의 자리 숫자보다 1 큰 네 자리 수는 무엇인가요?',ARRAY['M2-2-u1-X04','M2-2-u1-X06']::text[],true,'{"seq":8,"concept":"M2-2-u1-C3","difficulty":4,"kind":"mc","stem":"천의 자리 숫자가 5, 백의 자리 숫자가 0이고, 십의 자리 숫자는 천의 자리 숫자보다 3 작고, 일의 자리 숫자는 십의 자리 숫자보다 1 큰 네 자리 수는 무엇인가요?","options":[{"t":"5023","correct":true},{"t":"523","mis":"M2-2-u1-X04"},{"t":"3205","mis":"M2-2-u1-X06"}],"explanation":["십의 자리 숫자는 5보다 3 작은 2, 일의 자리 숫자는 2보다 1 큰 3이에요.","천 5, 백 0, 십 2, 일 3 — 5023이에요.","백의 자리 0을 빠뜨리지 않아요."],"variant_rule":{"alt":[{"stem":"천의 자리 숫자가 7, 일의 자리 숫자가 0이고, 백의 자리 숫자는 천의 자리 숫자보다 2 작고, 십의 자리 숫자는 백의 자리 숫자와 같은 네 자리 수는 무엇인가요?","options":[{"t":"7550","correct":true},{"t":"755","mis":"M2-2-u1-X04"},{"t":"5570","mis":"M2-2-u1-X06"}],"explanation":["백의 자리 숫자는 7보다 2 작은 5, 십의 자리 숫자도 5예요.","천 7, 백 5, 십 5, 일 0 — 7550이에요.","일의 자리 0을 빠뜨리지 않아요."]},{"stem":"천의 자리 숫자가 3이고, 나머지 세 자리 숫자가 모두 천의 자리 숫자보다 1 큰 네 자리 수는 무엇인가요?","options":[{"t":"3444","correct":true},{"t":"3222","mis":"M2-2-u1-X15"},{"t":"4443","mis":"M2-2-u1-X06"}],"explanation":["3보다 1 큰 수는 4예요.","천 3, 백 4, 십 4, 일 4 — 3444예요.","「큰」을 잘 읽고, 천의 자리는 3 그대로예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L04_challenge#9','math',2,2,'u1','L04','g2_2_math_u1_L04_challenge','lesson_challenge','M2-2-u1-C7',4,'mc','auto','손수건이 1000장씩 2상자, 100장씩 9묶음, 10장씩 12묶음, 낱장 5장 있어요. 손수건은 모두 몇 장인가요?',ARRAY['M2-2-u1-X10']::text[],true,'{"seq":9,"concept":"M2-2-u1-C7","difficulty":4,"kind":"mc","stem":"손수건이 1000장씩 2상자, 100장씩 9묶음, 10장씩 12묶음, 낱장 5장 있어요. 손수건은 모두 몇 장인가요?","options":[{"t":"3025","correct":true},{"t":"29125","mis":"M2-2-u1-X10"},{"t":"2925","mis":"M2-2-u1-X10"}],"explanation":["10장씩 12묶음은 100장씩 1묶음과 10장씩 2묶음이에요.","100장씩 묶음이 9개와 1개 — 10개이니 1000장 1상자로 또 바꿔요.","1000이 3개, 100이 0개, 10이 2개, 1이 5개 — 3025예요."],"variant_rule":{"alt":[{"stem":"천 원짜리 1장, 100원짜리 9개, 10원짜리 15개는 모두 얼마인가요?","options":[{"t":"2050원","correct":true},{"t":"19150원","mis":"M2-2-u1-X10"},{"t":"1950원","mis":"M2-2-u1-X10"}],"explanation":["10원짜리 15개는 100원짜리 1개와 10원짜리 5개예요.","100원짜리가 9개와 1개 — 10개이니 천 원짜리 1장으로 바꿔요.","천 원짜리 2장, 10원짜리 5개 — 2050원이에요."]},{"stem":"연이 1000개씩 4상자, 100개씩 8상자, 10개씩 23봉지 있어요. 연은 모두 몇 개인가요?","options":[{"t":"5030","correct":true},{"t":"48230","mis":"M2-2-u1-X10"},{"t":"4830","mis":"M2-2-u1-X10"}],"explanation":["10개씩 23봉지는 100개씩 2상자와 10개씩 3봉지예요.","100개씩 상자가 8개와 2개 — 10개이니 1000개 1상자로 바꿔요.","1000이 5개, 10이 3개 — 5030이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L04_challenge#10','math',2,2,'u1','L04','g2_2_math_u1_L04_challenge','lesson_challenge','M2-2-u1-C3',4,'essay','teacher','「삼천오」를 35가 아니라 3005로 써야 하는 까닭을 친구에게 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-2-u1-C3","difficulty":4,"kind":"essay","stem":"「삼천오」를 35가 아니라 3005로 써야 하는 까닭을 친구에게 설명해 보세요.","answer_guide":{"answer":"삼천오는 1000이 3개, 100이 0개, 10이 0개, 1이 5개인 수이다. 35로 쓰면 10이 3개, 1이 5개인 두 자리 수가 되므로, 없는 백·십의 자리에 0을 써서 3005로 써야 한다.","scoring_points":["1000이 3개, 1이 5개라고 자리별로 말했는가","35는 다른 수(두 자리 수)라는 것을 말했는가","없는 자리에 0을 쓴다는 것을 말했는가"]},"explanation":["「삼천오」는 천의 자리 3, 백의 자리 0, 십의 자리 0, 일의 자리 5예요.","35는 십의 자리가 3인 다른 수예요.","없는 자리에는 0을 써서 자리를 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L05_basic#1','math',2,2,'u1','L05','g2_2_math_u1_L05_basic','lesson_basic','M2-2-u1-C4',1,'mc','auto','5836에서 백의 자리 숫자는 무엇인가요?',ARRAY['M2-2-u1-X08','M2-2-u1-X09']::text[],true,'{"seq":1,"concept":"M2-2-u1-C4","difficulty":1,"kind":"mc","stem":"5836에서 백의 자리 숫자는 무엇인가요?","options":[{"t":"8","correct":true},{"t":"3","mis":"M2-2-u1-X08"},{"t":"800","mis":"M2-2-u1-X09"}],"explanation":["5836은 천의 자리 5, 백의 자리 8, 십의 자리 3, 일의 자리 6이에요.","백의 자리 숫자는 8이에요.","자리는 왼쪽부터 천·백·십·일 — 숫자를 물으면 값이 아니라 숫자 하나로 답해요."],"variant_rule":{"pv4":{"ask":"digit"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L05_basic#2','math',2,2,'u1','L05','g2_2_math_u1_L05_basic','lesson_basic','M2-2-u1-C4',1,'mc','auto','5836에서 숫자 8이 나타내는 값은 얼마인가요?',ARRAY['M2-2-u1-X09','M2-2-u1-X08']::text[],true,'{"seq":2,"concept":"M2-2-u1-C4","difficulty":1,"kind":"mc","stem":"5836에서 숫자 8이 나타내는 값은 얼마인가요?","options":[{"t":"800","correct":true},{"t":"8","mis":"M2-2-u1-X09"},{"t":"80","mis":"M2-2-u1-X08"}],"explanation":["숫자 8은 백의 자리에 있어요.","백의 자리 8은 800을 나타내요.","같은 숫자라도 어느 자리에 있느냐에 따라 값이 달라요."],"variant_rule":{"pv4":{"ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L05_basic#3','math',2,2,'u1','L05','g2_2_math_u1_L05_basic','lesson_basic','M2-2-u1-C4',1,'mc','auto','4352를 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u1-X09','M2-2-u1-X08']::text[],true,'{"seq":3,"concept":"M2-2-u1-C4","difficulty":1,"kind":"mc","stem":"4352를 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"4000 + 300 + 50 + 2","correct":true},{"t":"4 + 3 + 5 + 2","mis":"M2-2-u1-X09"},{"t":"4000 + 500 + 30 + 2","mis":"M2-2-u1-X08"}],"explanation":["4352는 천의 자리 4, 백의 자리 3, 십의 자리 5, 일의 자리 2예요.","각 자리의 값은 4000, 300, 50, 2 — 4352 = 4000 + 300 + 50 + 2.","숫자 하나하나에 자리 값을 붙여야 해요."],"variant_rule":{"pv4":{"ask":"expand"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L05_basic#4','math',2,2,'u1','L05','g2_2_math_u1_L05_basic','lesson_basic','M2-2-u1-C4',1,'sa','auto','2795의 자릿값 표예요. 빈칸에 알맞은 값은 얼마인가요?','{}'::text[],true,'{"seq":4,"concept":"M2-2-u1-C4","difficulty":1,"kind":"sa","stem":"2795의 자릿값 표예요. 빈칸에 알맞은 값은 얼마인가요?","answer":["700"],"explanation":["빈칸은 백의 자리예요.","백의 자리 숫자 7은 700을 나타내요.","나타내는 값 = 숫자 × 자리(1000·100·10·1)."],"asset":{"type":"place_table","digits":[2,7,9,5],"values":[2000,null,90,5],"mark":"h"},"variant_rule":{"pv4":{"ask":"table"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L05_basic#5','math',2,2,'u1','L05','g2_2_math_u1_L05_basic','lesson_basic','M2-2-u1-C4',2,'mc','auto','숫자 7이 700을 나타내는 수는 어느 것인가요?',ARRAY['M2-2-u1-X08']::text[],true,'{"seq":5,"concept":"M2-2-u1-C4","difficulty":2,"kind":"mc","stem":"숫자 7이 700을 나타내는 수는 어느 것인가요?","options":[{"t":"2750","correct":true},{"t":"7250","mis":"M2-2-u1-X08"},{"t":"2507","mis":"M2-2-u1-X08"}],"explanation":["700은 백의 자리 값이에요.","숫자 7이 백의 자리에 있는 수는 2750이에요.","숫자가 어느 자리에 있는지 먼저 찾아요."],"variant_rule":{"pv4":{"ask":"which","place":"h"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L05_basic#6','math',2,2,'u1','L05','g2_2_math_u1_L05_basic','lesson_basic','M2-2-u1-C4',2,'mc','auto','7080에서 백의 자리 숫자는 무엇인가요?',ARRAY['M2-2-u1-X08']::text[],true,'{"seq":6,"concept":"M2-2-u1-C4","difficulty":2,"kind":"mc","stem":"7080에서 백의 자리 숫자는 무엇인가요?","options":[{"t":"0","correct":true},{"t":"8","mis":"M2-2-u1-X08"},{"t":"7","mis":"M2-2-u1-X08"}],"explanation":["7080은 천의 자리 7, 백의 자리 0, 십의 자리 8, 일의 자리 0이에요.","백의 자리 숫자는 0이에요.","읽을 때 소리가 나지 않아도 자리는 있어요."],"variant_rule":{"pv4":{"ask":"digit","zero":true,"place":"h"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L05_basic#7','math',2,2,'u1','L05','g2_2_math_u1_L05_basic','lesson_basic','M2-2-u1-C4',2,'ox','auto','1111에서 네 숫자 1이 나타내는 값은 모두 같아요.',ARRAY['M2-2-u1-X09']::text[],true,'{"seq":7,"concept":"M2-2-u1-C4","difficulty":2,"kind":"ox","stem":"1111에서 네 숫자 1이 나타내는 값은 모두 같아요.","answer":"X","reason_options":[{"t":"1000, 100, 10, 1로 자리마다 값이 다르니까","correct":true},{"t":"같은 숫자니까 값도 같아서","mis":"M2-2-u1-X09"}],"mis":"M2-2-u1-X09","explanation":["맨 앞 1은 천의 자리라 1000이에요.","그다음 1은 100, 10, 1을 나타내요.","그래서 틀린 말이에요 — 자리에 따라 값이 달라요."],"variant_rule":{"alt":[{"stem":"5591에서 두 숫자 5가 나타내는 값은 5000과 500이에요.","answer":"O","reason_options":[{"t":"천의 자리 5는 5000, 백의 자리 5는 500이니까","correct":true},{"t":"같은 숫자는 모두 5를 나타내니까","mis":"M2-2-u1-X09"}],"explanation":["앞의 5는 천의 자리라 5000이에요.","다음 5는 백의 자리라 500이에요.","그래서 맞는 말이에요."]},{"stem":"7080에서 8은 8을 나타내요.","answer":"X","reason_options":[{"t":"8은 십의 자리 숫자라 80을 나타내니까","correct":true},{"t":"숫자가 8이니까 값도 8이라서","mis":"M2-2-u1-X09"}],"explanation":["7080에서 8은 십의 자리에 있어요.","십의 자리 8은 80을 나타내요.","그래서 틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L05_basic#8','math',2,2,'u1','L05','g2_2_math_u1_L05_basic','lesson_basic','M2-2-u1-C4',2,'match','auto','3819에서 각 숫자가 나타내는 값끼리 이어 보세요.','{}'::text[],true,'{"seq":8,"concept":"M2-2-u1-C4","difficulty":2,"kind":"match","stem":"3819에서 각 숫자가 나타내는 값끼리 이어 보세요.","pairs":[{"l":"3","r":"3000"},{"l":"8","r":"800"},{"l":"1","r":"10"}],"mis":"M2-2-u1-X09","explanation":["3은 천의 자리라 3000이에요.","8은 백의 자리라 800, 1은 십의 자리라 10이에요.","숫자 × 자리로 값을 찾아요."],"variant_rule":{"alt":[{"stem":"6274에서 각 숫자가 나타내는 값끼리 이어 보세요.","pairs":[{"l":"6","r":"6000"},{"l":"2","r":"200"},{"l":"7","r":"70"}],"explanation":["6은 천의 자리라 6000이에요.","2는 백의 자리라 200, 7은 십의 자리라 70이에요.","숫자 × 자리로 값을 찾아요."]},{"stem":"1596에서 각 숫자가 나타내는 값끼리 이어 보세요.","pairs":[{"l":"1","r":"1000"},{"l":"5","r":"500"},{"l":"9","r":"90"}],"explanation":["1은 천의 자리라 1000이에요.","5는 백의 자리라 500, 9는 십의 자리라 90이에요.","숫자 × 자리로 값을 찾아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L05_basic#9','math',2,2,'u1','L05','g2_2_math_u1_L05_basic','lesson_basic','M2-2-u1-C4',2,'blank','auto','4000 + 300 + 50 + 2 = (        )',ARRAY['M2-2-u1-X05','M2-2-u1-X06']::text[],true,'{"seq":9,"concept":"M2-2-u1-C4","difficulty":2,"kind":"blank","stem":"4000 + 300 + 50 + 2 = (        )","options":[{"t":"4352","correct":true},{"t":"4000300502","mis":"M2-2-u1-X05"},{"t":"2534","mis":"M2-2-u1-X06"}],"explanation":["4000은 천, 300은 백, 50은 십, 2는 일의 자리 값이에요.","천 4, 백 3, 십 5, 일 2 — 4352예요.","값을 이어 쓰지 않고 자리마다 숫자 하나씩 써요."],"variant_rule":{"alt":[{"stem":"7000 + 80 = (        )","options":[{"t":"7080","correct":true},{"t":"780","mis":"M2-2-u1-X04"},{"t":"700080","mis":"M2-2-u1-X05"}],"explanation":["7000은 천의 자리, 80은 십의 자리 값이에요.","백·일의 자리에 0을 써서 7080이에요.","없는 자리에는 0을 써요."]},{"stem":"5000 + 800 + 30 + 6 = (        )","options":[{"t":"5836","correct":true},{"t":"5000800306","mis":"M2-2-u1-X05"},{"t":"6385","mis":"M2-2-u1-X06"}],"explanation":["5000은 천, 800은 백, 30은 십, 6은 일의 자리 값이에요.","천 5, 백 8, 십 3, 일 6 — 5836이에요.","자리마다 숫자 하나씩 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L05_basic#10','math',2,2,'u1','L05','g2_2_math_u1_L05_basic','lesson_basic','M2-2-u1-C4',3,'mc','auto','천의 자리 숫자가 나타내는 값이 가장 큰 수는 어느 것인가요?',ARRAY['M2-2-u1-X13']::text[],true,'{"seq":10,"concept":"M2-2-u1-C4","difficulty":3,"kind":"mc","stem":"천의 자리 숫자가 나타내는 값이 가장 큰 수는 어느 것인가요?","options":[{"t":"7120","correct":true},{"t":"6998","mis":"M2-2-u1-X13"},{"t":"5999","mis":"M2-2-u1-X13"}],"explanation":["천의 자리 숫자는 7, 6, 5예요.","7이 나타내는 7000이 가장 커요.","뒤쪽 숫자가 커도 천의 자리 값과는 상관없어요."],"variant_rule":{"alt":[{"stem":"백의 자리 숫자가 나타내는 값이 가장 큰 수는 어느 것인가요?","options":[{"t":"3912","correct":true},{"t":"8471","mis":"M2-2-u1-X08"},{"t":"9285","mis":"M2-2-u1-X08"}],"explanation":["백의 자리 숫자는 9, 4, 2예요.","9가 나타내는 900이 가장 커요.","천의 자리가 아니라 「백의 자리」를 봐요."]},{"stem":"십의 자리 숫자가 나타내는 값이 가장 작은 수는 어느 것인가요?","options":[{"t":"9405","correct":true},{"t":"1290","mis":"M2-2-u1-X08"},{"t":"5536","mis":"M2-2-u1-X08"}],"explanation":["십의 자리 숫자는 0, 9, 3이에요.","0이 가장 작아요 — 9405예요.","오른쪽에서 두 번째가 십의 자리예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L05_challenge#1','math',2,2,'u1','L05','g2_2_math_u1_L05_challenge','lesson_challenge','M2-2-u1-C4',2,'mc','auto','2647에서 6은 어느 자리 숫자이고, 얼마를 나타내나요?',ARRAY['M2-2-u1-X09','M2-2-u1-X08']::text[],true,'{"seq":1,"concept":"M2-2-u1-C4","difficulty":2,"kind":"mc","stem":"2647에서 6은 어느 자리 숫자이고, 얼마를 나타내나요?","options":[{"t":"백의 자리, 600","correct":true},{"t":"백의 자리, 6","mis":"M2-2-u1-X09"},{"t":"십의 자리, 60","mis":"M2-2-u1-X08"}],"explanation":["2647은 천 2, 백 6, 십 4, 일 7이에요.","6은 백의 자리 숫자이고 600을 나타내요.","자리를 찾고 나서 값을 말해요."],"variant_rule":{"alt":[{"stem":"9518에서 5는 어느 자리 숫자이고, 얼마를 나타내나요?","options":[{"t":"백의 자리, 500","correct":true},{"t":"백의 자리, 5","mis":"M2-2-u1-X09"},{"t":"천의 자리, 5000","mis":"M2-2-u1-X08"}],"explanation":["9518은 천 9, 백 5, 십 1, 일 8이에요.","5는 백의 자리 숫자이고 500을 나타내요.","자리를 찾고 나서 값을 말해요."]},{"stem":"4937에서 4는 어느 자리 숫자이고, 얼마를 나타내나요?","options":[{"t":"천의 자리, 4000","correct":true},{"t":"천의 자리, 4","mis":"M2-2-u1-X09"},{"t":"일의 자리, 4","mis":"M2-2-u1-X08"}],"explanation":["4937은 천 4, 백 9, 십 3, 일 7이에요.","4는 천의 자리 숫자이고 4000을 나타내요.","자리를 찾고 나서 값을 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L05_challenge#2','math',2,2,'u1','L05','g2_2_math_u1_L05_challenge','lesson_challenge','M2-2-u1-C4',2,'sa','auto','9372에서 숫자 9가 나타내는 값은 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M2-2-u1-C4","difficulty":2,"kind":"sa","stem":"9372에서 숫자 9가 나타내는 값은 얼마인가요?","answer":["9000"],"explanation":["숫자 9는 천의 자리에 있어요.","천의 자리 9는 9000을 나타내요.","같은 숫자라도 어느 자리에 있느냐에 따라 값이 달라요."],"variant_rule":{"pv4":{"ask":"value","place":"th"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L05_challenge#3','math',2,2,'u1','L05','g2_2_math_u1_L05_challenge','lesson_challenge','M2-2-u1-C4',3,'mc','auto','숫자 5가 나타내는 값이 가장 큰 수는 어느 것인가요?',ARRAY['M2-2-u1-X08']::text[],true,'{"seq":3,"concept":"M2-2-u1-C4","difficulty":3,"kind":"mc","stem":"숫자 5가 나타내는 값이 가장 큰 수는 어느 것인가요?","options":[{"t":"5231","correct":true},{"t":"3521","mis":"M2-2-u1-X08"},{"t":"2351","mis":"M2-2-u1-X08"}],"explanation":["5231의 5는 천의 자리라 5000이에요.","3521의 5는 500, 2351의 5는 50이에요.","숫자는 같아도 높은 자리에 있을수록 값이 커요."],"variant_rule":{"alt":[{"stem":"숫자 4가 나타내는 값이 가장 작은 수는 어느 것인가요?","options":[{"t":"1734","correct":true},{"t":"4817","mis":"M2-2-u1-X08"},{"t":"3481","mis":"M2-2-u1-X08"}],"explanation":["1734의 4는 일의 자리라 4예요.","4817의 4는 4000, 3481의 4는 400이에요.","낮은 자리에 있을수록 값이 작아요."]},{"stem":"숫자 8이 80을 나타내는 수는 어느 것인가요?","options":[{"t":"2381","correct":true},{"t":"8321","mis":"M2-2-u1-X08"},{"t":"3218","mis":"M2-2-u1-X08"}],"explanation":["80은 십의 자리 값이에요.","숫자 8이 십의 자리에 있는 수는 2381이에요.","숫자가 어느 자리에 있는지 먼저 찾아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L05_challenge#4','math',2,2,'u1','L05','g2_2_math_u1_L05_challenge','lesson_challenge','M2-2-u1-C4',3,'mc','auto','6000 + 7은 얼마인가요?',ARRAY['M2-2-u1-X04','M2-2-u1-X05']::text[],true,'{"seq":4,"concept":"M2-2-u1-C4","difficulty":3,"kind":"mc","stem":"6000 + 7은 얼마인가요?","options":[{"t":"6007","correct":true},{"t":"67","mis":"M2-2-u1-X04"},{"t":"60007","mis":"M2-2-u1-X05"}],"explanation":["6000은 천의 자리, 7은 일의 자리 값이에요.","백·십의 자리에 0을 써서 6007이에요.","없는 자리에는 0을 써요."],"variant_rule":{"alt":[{"stem":"5000 + 60은 얼마인가요?","options":[{"t":"5060","correct":true},{"t":"56","mis":"M2-2-u1-X04"},{"t":"500060","mis":"M2-2-u1-X05"}],"explanation":["5000은 천, 60은 십의 자리 값이에요.","백·일의 자리에 0을 써서 5060이에요.","없는 자리에는 0을 써요."]},{"stem":"9000 + 300 + 4는 얼마인가요?","options":[{"t":"9304","correct":true},{"t":"934","mis":"M2-2-u1-X04"},{"t":"90003004","mis":"M2-2-u1-X05"}],"explanation":["9000은 천, 300은 백, 4는 일의 자리 값이에요.","천 9, 백 3, 십 0, 일 4 — 9304예요.","0도 자리를 지켜요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L05_challenge#5','math',2,2,'u1','L05','g2_2_math_u1_L05_challenge','lesson_challenge','M2-2-u1-C4',3,'error','auto','친구들이 5555에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u1-X09','M2-2-u1-X08']::text[],true,'{"seq":5,"concept":"M2-2-u1-C4","difficulty":3,"kind":"error","stem":"친구들이 5555에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하윤: 네 숫자 5는 모두 5를 나타내.","correct":true,"mis_target":"M2-2-u1-X09"},{"t":"시우: 맨 앞의 5는 5000을 나타내.","mis":"M2-2-u1-X08"},{"t":"나은: 5555는 5000 + 500 + 50 + 5야.","mis":"M2-2-u1-X09"}],"explanation":["맨 앞 5는 5000, 그다음은 500, 50, 맨 뒤 5는 5를 나타내요.","네 숫자 5의 값은 모두 달라요.","하윤이가 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"친구들이 6006에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도하: 두 숫자 6은 모두 6000을 나타내.","correct":true,"mis_target":"M2-2-u1-X09"},{"t":"라온: 백의 자리 숫자는 0이야.","mis":"M2-2-u1-X08"},{"t":"세아: 6006은 6000 + 6이야.","mis":"M2-2-u1-X04"}],"explanation":["앞의 6은 6000, 뒤의 6은 6을 나타내요.","두 숫자 6의 값은 달라요.","도하가 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L05_challenge#6','math',2,2,'u1','L05','g2_2_math_u1_L05_challenge','lesson_challenge','M2-2-u1-C4',3,'mc','auto','백의 자리 숫자가 가장 큰 수는 어느 것인가요?',ARRAY['M2-2-u1-X08']::text[],true,'{"seq":6,"concept":"M2-2-u1-C4","difficulty":3,"kind":"mc","stem":"백의 자리 숫자가 가장 큰 수는 어느 것인가요?","options":[{"t":"1902","correct":true},{"t":"8471","mis":"M2-2-u1-X08"},{"t":"5390","mis":"M2-2-u1-X08"}],"explanation":["백의 자리 숫자는 1902가 9, 8471이 4, 5390이 3이에요.","백의 자리 숫자가 가장 큰 수는 1902예요.","가장 큰 수를 묻는 게 아니라 「백의 자리 숫자」를 물었어요."],"variant_rule":{"alt":[{"stem":"일의 자리 숫자가 가장 큰 수는 어느 것인가요?","options":[{"t":"2019","correct":true},{"t":"9702","mis":"M2-2-u1-X08"},{"t":"5833","mis":"M2-2-u1-X08"}],"explanation":["일의 자리 숫자는 2019가 9, 9702가 2, 5833이 3이에요.","일의 자리 숫자가 가장 큰 수는 2019예요.","가장 큰 수를 묻는 게 아니라 「일의 자리 숫자」를 물었어요."]},{"stem":"십의 자리 숫자가 가장 작은 수는 어느 것인가요?","options":[{"t":"9804","correct":true},{"t":"1253","mis":"M2-2-u1-X08"},{"t":"3176","mis":"M2-2-u1-X08"}],"explanation":["십의 자리 숫자는 9804가 0, 1253이 5, 3176이 7이에요.","십의 자리 숫자가 가장 작은 수는 9804예요.","가장 작은 수를 묻는 게 아니라 「십의 자리 숫자」를 물었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L05_challenge#7','math',2,2,'u1','L05','g2_2_math_u1_L05_challenge','lesson_challenge','M2-2-u1-C4',3,'sa','auto','천의 자리 숫자는 2, 백의 자리 숫자는 6, 십의 자리 숫자는 0, 일의 자리 숫자는 9인 수를 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M2-2-u1-C4","difficulty":3,"kind":"sa","stem":"천의 자리 숫자는 2, 백의 자리 숫자는 6, 십의 자리 숫자는 0, 일의 자리 숫자는 9인 수를 쓰세요.","answer":["2609"],"explanation":["천 2, 백 6, 십 0, 일 9예요.","수로 쓰면 2609예요.","십의 자리 0도 꼭 써요."],"variant_rule":{"alt":[{"stem":"천의 자리 숫자는 9, 백의 자리 숫자는 0, 십의 자리 숫자는 4, 일의 자리 숫자는 0인 수를 쓰세요.","answer":["9040"],"explanation":["천 9, 백 0, 십 4, 일 0이에요.","수로 쓰면 9040이에요.","백·일의 자리 0도 꼭 써요."]},{"stem":"천의 자리 숫자는 3, 백의 자리 숫자는 8, 십의 자리 숫자는 1, 일의 자리 숫자는 5인 수를 쓰세요.","answer":["3815"],"explanation":["천 3, 백 8, 십 1, 일 5예요.","수로 쓰면 3815예요.","천·백·십·일 차례로 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L05_challenge#8','math',2,2,'u1','L05','g2_2_math_u1_L05_challenge','lesson_challenge','M2-2-u1-C4',4,'mc','auto','□576에서 □가 나타내는 값은 4000이에요. 이 수에서 5가 나타내는 값과 □가 나타내는 값을 모으면 얼마인가요?',ARRAY['M2-2-u1-X09','M2-2-u1-X08']::text[],true,'{"seq":8,"concept":"M2-2-u1-C4","difficulty":4,"kind":"mc","stem":"□576에서 □가 나타내는 값은 4000이에요. 이 수에서 5가 나타내는 값과 □가 나타내는 값을 모으면 얼마인가요?","options":[{"t":"4500","correct":true},{"t":"9","mis":"M2-2-u1-X09"},{"t":"4005","mis":"M2-2-u1-X08"}],"explanation":["□는 천의 자리라서 4예요 — 수는 4576이에요.","5는 백의 자리라 500을 나타내요.","4000과 500을 모으면 4500이에요."],"variant_rule":{"alt":[{"stem":"3□82에서 □가 나타내는 값은 700이에요. 이 수에서 8이 나타내는 값과 □가 나타내는 값을 모으면 얼마인가요?","options":[{"t":"780","correct":true},{"t":"15","mis":"M2-2-u1-X09"},{"t":"7080","mis":"M2-2-u1-X08"}],"explanation":["□는 백의 자리라서 7이에요 — 수는 3782예요.","8은 십의 자리라 80을 나타내요.","700과 80을 모으면 780이에요."]},{"stem":"6□09에서 □가 나타내는 값은 200이에요. 이 수에서 6이 나타내는 값과 □가 나타내는 값을 모으면 얼마인가요?","options":[{"t":"6200","correct":true},{"t":"8","mis":"M2-2-u1-X09"},{"t":"6020","mis":"M2-2-u1-X08"}],"explanation":["□는 백의 자리라서 2예요 — 수는 6209예요.","6은 천의 자리라 6000을 나타내요.","6000과 200을 모으면 6200이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L05_challenge#9','math',2,2,'u1','L05','g2_2_math_u1_L05_challenge','lesson_challenge','M2-2-u1-C4',4,'mc','auto','수 카드 0, 2, 5, 7을 한 번씩 모두 써서, 숫자 7이 700을 나타내는 가장 큰 네 자리 수를 만들었어요. 무엇인가요?',ARRAY['M2-2-u1-X08','M2-2-u1-X15']::text[],true,'{"seq":9,"concept":"M2-2-u1-C4","difficulty":4,"kind":"mc","stem":"수 카드 0, 2, 5, 7을 한 번씩 모두 써서, 숫자 7이 700을 나타내는 가장 큰 네 자리 수를 만들었어요. 무엇인가요?","options":[{"t":"5720","correct":true},{"t":"7520","mis":"M2-2-u1-X08"},{"t":"2750","mis":"M2-2-u1-X15"}],"explanation":["7이 700을 나타내려면 7은 백의 자리에 놓아요.","남은 0, 2, 5 가운데 큰 수부터 천·십·일의 자리에 — 5, 2, 0이에요.","그래서 5720이에요 — 2750도 7이 700이지만 더 작아요."],"variant_rule":{"alt":[{"stem":"수 카드 1, 3, 6, 8을 한 번씩 모두 써서, 숫자 3이 30을 나타내는 가장 작은 네 자리 수를 만들었어요. 무엇인가요?","options":[{"t":"1638","correct":true},{"t":"8631","mis":"M2-2-u1-X15"},{"t":"3168","mis":"M2-2-u1-X08"}],"explanation":["3이 30을 나타내려면 3은 십의 자리에 놓아요.","남은 1, 6, 8 가운데 작은 수부터 천·백·일의 자리에 — 1, 6, 8이에요.","그래서 1638이에요."]},{"stem":"수 카드 4, 0, 9, 2를 한 번씩 모두 써서, 숫자 9가 9000을 나타내는 가장 작은 네 자리 수를 만들었어요. 무엇인가요?","options":[{"t":"9024","correct":true},{"t":"9420","mis":"M2-2-u1-X15"},{"t":"4029","mis":"M2-2-u1-X08"}],"explanation":["9가 9000을 나타내려면 9는 천의 자리에 놓아요.","남은 0, 2, 4 가운데 작은 수부터 백·십·일의 자리에 — 0, 2, 4예요.","그래서 9024예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L05_challenge#10','math',2,2,'u1','L05','g2_2_math_u1_L05_challenge','lesson_challenge','M2-2-u1-C4',4,'essay','teacher','5591에서 두 숫자 5가 나타내는 값이 어떻게 다른지 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-2-u1-C4","difficulty":4,"kind":"essay","stem":"5591에서 두 숫자 5가 나타내는 값이 어떻게 다른지 설명해 보세요.","answer_guide":{"answer":"앞의 5는 천의 자리라 5000, 다음 5는 백의 자리라 500을 나타낸다. 같은 숫자라도 자리에 따라 값이 다르다.","scoring_points":["두 숫자 5의 자리를 바르게 말했는가","5000·500을 바르게 썼는가","「자리에 따라 값이 다르다」는 까닭을 말했는가"]},"explanation":["5591 = 5000 + 500 + 90 + 1이에요.","같은 5라도 천·백의 자리에 따라 5000·500이에요.","숫자 × 자리로 값을 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L06_basic#1','math',2,2,'u1','L06','g2_2_math_u1_L06_basic','lesson_basic','M2-2-u1-C5',1,'mc','auto','1000씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u1-X11']::text[],true,'{"seq":1,"concept":"M2-2-u1-C5","difficulty":1,"kind":"mc","stem":"1000씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"6167","correct":true},{"t":"5267","mis":"M2-2-u1-X11"},{"t":"5177","mis":"M2-2-u1-X11"}],"explanation":["1000씩 뛰면 천의 자리 숫자가 1씩 커져요.","5167에서 1000만큼 뛰면 6167이에요.","다른 자리 숫자는 그대로예요."],"asset":{"type":"jump_row","cells":[2167,3167,4167,5167,null],"step":1000},"variant_rule":{"skip4":{"ask":"next","step":[1000]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
