INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L06_basic#3','math',2,2,'u1','L06','g2_2_math_u1_L06_basic','lesson_basic','M2-2-u1-C5',1,'mc','auto','10씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u1-X11']::text[],true,'{"seq":3,"concept":"M2-2-u1-C5","difficulty":1,"kind":"mc","stem":"10씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"3490","correct":true},{"t":"3481","mis":"M2-2-u1-X11"},{"t":"3580","mis":"M2-2-u1-X11"}],"explanation":["10씩 뛰면 십의 자리 숫자가 1씩 커져요.","3480에서 10만큼 뛰면 3490이에요.","다른 자리 숫자는 그대로예요."],"asset":{"type":"jump_row","cells":[3450,3460,3470,3480,null],"step":10},"variant_rule":{"skip4":{"ask":"next","step":[10]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L06_basic#4','math',2,2,'u1','L06','g2_2_math_u1_L06_basic','lesson_basic','M2-2-u1-C5',1,'mc','auto','1씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u1-X11']::text[],true,'{"seq":4,"concept":"M2-2-u1-C5","difficulty":1,"kind":"mc","stem":"1씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"7849","correct":true},{"t":"7858","mis":"M2-2-u1-X11"},{"t":"7948","mis":"M2-2-u1-X11"}],"explanation":["1씩 뛰면 일의 자리 숫자가 1씩 커져요.","7848에서 1만큼 뛰면 7849예요.","다른 자리 숫자는 그대로예요."],"asset":{"type":"jump_row","cells":[7845,7846,7847,7848,null],"step":1},"variant_rule":{"skip4":{"ask":"next","step":[1]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L06_basic#5','math',2,2,'u1','L06','g2_2_math_u1_L06_basic','lesson_basic','M2-2-u1-C5',2,'mc','auto','얼마씩 뛰어 세었나요?',ARRAY['M2-2-u1-X12']::text[],true,'{"seq":5,"concept":"M2-2-u1-C5","difficulty":2,"kind":"mc","stem":"얼마씩 뛰어 세었나요?","options":[{"t":"1000씩","correct":true},{"t":"100씩","mis":"M2-2-u1-X12"},{"t":"10씩","mis":"M2-2-u1-X12"}],"explanation":["2360, 3360, 4360 … 하고 천의 자리 숫자만 1씩 커져요.","그래서 1000씩 뛰어 세었어요.","어느 자리 숫자가 바뀌는지 보면 몇씩 뛰었는지 알 수 있어요."],"asset":{"type":"jump_row","cells":[2360,3360,4360,5360,6360],"step":null},"variant_rule":{"skip4":{"ask":"step","step":[1,10,100,1000],"dir":"both"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L06_basic#6','math',2,2,'u1','L06','g2_2_math_u1_L06_basic','lesson_basic','M2-2-u1-C5',2,'mc','auto','100씩 거꾸로 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u1-X11']::text[],true,'{"seq":6,"concept":"M2-2-u1-C5","difficulty":2,"kind":"mc","stem":"100씩 거꾸로 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"7669","correct":true},{"t":"7759","mis":"M2-2-u1-X11"},{"t":"6769","mis":"M2-2-u1-X11"}],"explanation":["100씩 거꾸로 뛰면 백의 자리 숫자가 1씩 작아져요.","7769에서 100만큼 거꾸로 뛰면 7669예요.","다른 자리 숫자는 그대로예요."],"asset":{"type":"jump_row","cells":[7869,7769,null,7569,7469],"step":100,"dir":"down"},"variant_rule":{"skip4":{"ask":"blank","step":[100],"dir":"down"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L06_basic#7','math',2,2,'u1','L06','g2_2_math_u1_L06_basic','lesson_basic','M2-2-u1-C5',2,'mc','auto','수 배열표에서 오른쪽으로 한 칸 가면 1씩, 아래로 한 칸 가면 10씩 커져요. 9945에서 아래로 두 칸 간 수는 무엇인가요?',ARRAY['M2-2-u1-X12']::text[],true,'{"seq":7,"concept":"M2-2-u1-C5","difficulty":2,"kind":"mc","stem":"수 배열표에서 오른쪽으로 한 칸 가면 1씩, 아래로 한 칸 가면 10씩 커져요. 9945에서 아래로 두 칸 간 수는 무엇인가요?","options":[{"t":"9965","correct":true},{"t":"9947","mis":"M2-2-u1-X12"},{"t":"9955","mis":"M2-2-u1-X12"}],"explanation":["아래로 한 칸에 10씩 커져요.","9945 → 9955 → 9965 — 두 칸이면 20만큼 커져요.","오른쪽(1씩)과 아래(10씩)를 헷갈리지 않아요."],"variant_rule":{"alt":[{"stem":"수 배열표에서 오른쪽으로 한 칸 가면 1씩, 아래로 한 칸 가면 10씩 커져요. 9963에서 오른쪽으로 세 칸 간 수는 무엇인가요?","options":[{"t":"9966","correct":true},{"t":"9993","mis":"M2-2-u1-X12"},{"t":"9964","mis":"M2-2-u1-X12"}],"explanation":["오른쪽으로 한 칸에 1씩 커져요.","9963 → 9964 → 9965 → 9966이에요.","세 칸이면 3만큼 커져요."]},{"stem":"수 배열표에서 오른쪽으로 한 칸 가면 1씩, 아래로 한 칸 가면 10씩 커져요. 9988에서 위로 한 칸 간 수는 무엇인가요?","options":[{"t":"9978","correct":true},{"t":"9998","mis":"M2-2-u1-X15"},{"t":"9987","mis":"M2-2-u1-X12"}],"explanation":["아래로 가면 10씩 커지니, 위로 가면 10씩 작아져요.","9988보다 10 작은 수는 9978이에요.","방향을 거꾸로 하지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L06_basic#8','math',2,2,'u1','L06','g2_2_math_u1_L06_basic','lesson_basic','M2-2-u1-C5',2,'ox','auto','3980부터 10씩 뛰어 세면 3980, 3990, 39100이에요.',ARRAY['M2-2-u1-X01']::text[],true,'{"seq":8,"concept":"M2-2-u1-C5","difficulty":2,"kind":"ox","stem":"3980부터 10씩 뛰어 세면 3980, 3990, 39100이에요.","answer":"X","reason_options":[{"t":"3990 다음은 4000이니까","correct":true},{"t":"9 다음에 10을 붙이면 되니까","mis":"M2-2-u1-X01"}],"mis":"M2-2-u1-X01","explanation":["3990에서 10을 더 뛰면 십의 자리가 10이 돼요.","십의 자리 10은 백의 자리로, 백의 자리 10은 천의 자리로 넘어가 4000이에요.","그래서 틀린 말이에요."],"variant_rule":{"alt":[{"stem":"5997부터 1씩 뛰어 세면 5997, 5998, 5999, 6000이에요.","answer":"O","reason_options":[{"t":"5999 다음은 6000이니까","correct":true},{"t":"5999 다음은 59910이니까","mis":"M2-2-u1-X01"}],"explanation":["5999에서 1을 더 뛰면 일의 자리가 10이 돼요.","십·백·천의 자리로 넘어가 6000이에요.","그래서 맞는 말이에요."]},{"stem":"8000부터 1000씩 거꾸로 뛰어 세면 8000, 7000, 6000이에요.","answer":"O","reason_options":[{"t":"천의 자리 숫자가 1씩 작아지니까","correct":true},{"t":"거꾸로 뛰면 천의 자리가 커지니까","mis":"M2-2-u1-X12"}],"explanation":["1000씩 거꾸로 뛰면 천의 자리 숫자가 1씩 작아져요.","8000, 7000, 6000이에요.","그래서 맞는 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L06_basic#9','math',2,2,'u1','L06','g2_2_math_u1_L06_basic','lesson_basic','M2-2-u1-C5',2,'match','auto','얼마씩 뛰어 센 것인지 이어 보세요.','{}'::text[],true,'{"seq":9,"concept":"M2-2-u1-C5","difficulty":2,"kind":"match","stem":"얼마씩 뛰어 센 것인지 이어 보세요.","pairs":[{"l":"2211, 2212, 2213","r":"1씩"},{"l":"2211, 2221, 2231","r":"10씩"},{"l":"2211, 3211, 4211","r":"1000씩"}],"mis":"M2-2-u1-X12","explanation":["일의 자리만 바뀌면 1씩이에요.","십의 자리만 바뀌면 10씩, 천의 자리만 바뀌면 1000씩이에요.","바뀐 자리를 보면 몇씩인지 보여요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 얼마씩 뛰어 센 것인지 이어 보세요.","pairs":[{"l":"5048, 5148, 5248","r":"100씩"},{"l":"5048, 5049, 5050","r":"1씩"},{"l":"5048, 6048, 7048","r":"1000씩"}],"explanation":["백의 자리만 바뀌면 100씩이에요.","5048, 5049, 5050은 1씩, 천의 자리만 바뀌면 1000씩이에요.","바뀐 자리를 보면 몇씩인지 보여요."]},{"stem":"얼마씩 거꾸로 뛰어 센 것인지 이어 보세요.","pairs":[{"l":"8620, 7620, 6620","r":"1000씩"},{"l":"8620, 8520, 8420","r":"100씩"},{"l":"8620, 8610, 8600","r":"10씩"}],"explanation":["천의 자리만 작아지면 1000씩이에요.","백의 자리만 작아지면 100씩, 십의 자리만 작아지면 10씩이에요.","바뀐 자리를 보면 몇씩인지 보여요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L06_basic#10','math',2,2,'u1','L06','g2_2_math_u1_L06_basic','lesson_basic','M2-2-u1-C5',3,'mc','auto','10씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u1-X01','M2-2-u1-X11']::text[],true,'{"seq":10,"concept":"M2-2-u1-C5","difficulty":3,"kind":"mc","stem":"10씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"4000","correct":true},{"t":"39100","mis":"M2-2-u1-X01"},{"t":"3991","mis":"M2-2-u1-X11"}],"explanation":["10씩 뛰면 십의 자리 숫자가 1씩 커져요.","3990에서 10만큼 뛰면 4000이에요.","십의 자리가 10이 되면 바로 윗자리가 1 커지고 십의 자리는 0이 돼요."],"asset":{"type":"jump_row","cells":[3970,3980,3990,null,4010],"step":10},"variant_rule":{"skip4":{"ask":"blank","step":[10],"cross":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
