INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L06_challenge#2','math',2,2,'u1','L06','g2_2_math_u1_L06_challenge','lesson_challenge','M2-2-u1-C5',2,'sa','auto','1000씩 거꾸로 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?','{}'::text[],true,'{"seq":2,"concept":"M2-2-u1-C5","difficulty":2,"kind":"sa","stem":"1000씩 거꾸로 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","answer":["6450"],"explanation":["1000씩 거꾸로 뛰면 천의 자리 숫자가 1씩 작아져요.","7450에서 1000만큼 거꾸로 뛰면 6450이에요.","다른 자리 숫자는 그대로예요."],"asset":{"type":"jump_row","cells":[9450,8450,7450,null,5450],"step":1000,"dir":"down"},"variant_rule":{"skip4":{"ask":"blank","step":[1000],"dir":"down"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L06_challenge#3','math',2,2,'u1','L06','g2_2_math_u1_L06_challenge','lesson_challenge','M2-2-u1-C5',3,'mc','auto','2360에서 1000씩 3번 뛰어 센 수는 무엇인가요?',ARRAY['M2-2-u1-X12']::text[],true,'{"seq":3,"concept":"M2-2-u1-C5","difficulty":3,"kind":"mc","stem":"2360에서 1000씩 3번 뛰어 센 수는 무엇인가요?","options":[{"t":"5360","correct":true},{"t":"2363","mis":"M2-2-u1-X12"},{"t":"2660","mis":"M2-2-u1-X12"}],"explanation":["2360, 3360, 4360, 5360 — 1000씩 3번이에요.","천의 자리만 1씩 커져요.","1000씩 3번은 1씩 3번, 100씩 3번과 달라요."],"variant_rule":{"alt":[{"stem":"4785에서 100씩 2번 뛰어 센 수는 무엇인가요?","options":[{"t":"4985","correct":true},{"t":"4805","mis":"M2-2-u1-X12"},{"t":"6785","mis":"M2-2-u1-X12"}],"explanation":["4785, 4885, 4985 — 100씩 2번이에요.","백의 자리만 1씩 커져요.","100씩 2번은 10씩 2번, 1000씩 2번과 달라요."]},{"stem":"5998에서 1씩 4번 뛰어 센 수는 무엇인가요?","options":[{"t":"6002","correct":true},{"t":"6038","mis":"M2-2-u1-X12"},{"t":"9998","mis":"M2-2-u1-X12"}],"explanation":["5998, 5999, 6000, 6001, 6002 — 1씩 4번이에요.","5999 다음은 6000이에요.","자리가 넘어가는 곳을 조심해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L06_challenge#4','math',2,2,'u1','L06','g2_2_math_u1_L06_challenge','lesson_challenge','M2-2-u1-C5',3,'mc','auto','어떤 수에서 1000씩 4번 뛰어 세었더니 8000이 되었어요. 어떤 수는 무엇인가요?',ARRAY['M2-2-u1-X15','M2-2-u1-X12']::text[],true,'{"seq":4,"concept":"M2-2-u1-C5","difficulty":3,"kind":"mc","stem":"어떤 수에서 1000씩 4번 뛰어 세었더니 8000이 되었어요. 어떤 수는 무엇인가요?","options":[{"t":"4000","correct":true},{"t":"12000","mis":"M2-2-u1-X15"},{"t":"7996","mis":"M2-2-u1-X12"}],"explanation":["8000에서 1000씩 거꾸로 4번 뛰어 세요.","8000, 7000, 6000, 5000, 4000 — 어떤 수는 4000이에요.","「어떤 수에서 뛰어 셌다」면 거꾸로 세어 찾아요."],"variant_rule":{"alt":[{"stem":"어떤 수에서 100씩 3번 뛰어 세었더니 5000이 되었어요. 어떤 수는 무엇인가요?","options":[{"t":"4700","correct":true},{"t":"5300","mis":"M2-2-u1-X15"},{"t":"4997","mis":"M2-2-u1-X12"}],"explanation":["5000에서 100씩 거꾸로 3번 뛰어 세요.","5000, 4900, 4800, 4700 — 어떤 수는 4700이에요.","「어떤 수에서 뛰어 셌다」면 거꾸로 세어 찾아요."]},{"stem":"어떤 수에서 10씩 5번 뛰어 세었더니 3020이 되었어요. 어떤 수는 무엇인가요?","options":[{"t":"2970","correct":true},{"t":"3070","mis":"M2-2-u1-X15"},{"t":"3015","mis":"M2-2-u1-X12"}],"explanation":["3020에서 10씩 거꾸로 5번 뛰어 세요.","3020, 3010, 3000, 2990, 2980, 2970 — 어떤 수는 2970이에요.","3000에서 10 작아지면 2990 — 천의 자리에서 빌려 와요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L06_challenge#5','math',2,2,'u1','L06','g2_2_math_u1_L06_challenge','lesson_challenge','M2-2-u1-C5',3,'mc','auto','얼마씩 거꾸로 뛰어 세었나요?',ARRAY['M2-2-u1-X12']::text[],true,'{"seq":5,"concept":"M2-2-u1-C5","difficulty":3,"kind":"mc","stem":"얼마씩 거꾸로 뛰어 세었나요?","options":[{"t":"100씩","correct":true},{"t":"1000씩","mis":"M2-2-u1-X12"},{"t":"10씩","mis":"M2-2-u1-X12"}],"explanation":["6505, 6405, 6305 … 하고 백의 자리 숫자만 1씩 작아져요.","그래서 100씩 거꾸로 뛰어 세었어요.","어느 자리 숫자가 바뀌는지 보면 몇씩 뛰었는지 알 수 있어요."],"asset":{"type":"jump_row","cells":[6505,6405,6305,6205,6105],"step":null,"dir":"down"},"variant_rule":{"skip4":{"ask":"step","step":[1,10,100,1000],"dir":"both"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L06_challenge#6','math',2,2,'u1','L06','g2_2_math_u1_L06_challenge','lesson_challenge','M2-2-u1-C5',3,'error','auto','5990부터 뛰어 센 다음 수를 썼어요. 잘못 쓴 친구는 누구인가요?',ARRAY['M2-2-u1-X01','M2-2-u1-X11']::text[],true,'{"seq":6,"concept":"M2-2-u1-C5","difficulty":3,"kind":"error","stem":"5990부터 뛰어 센 다음 수를 썼어요. 잘못 쓴 친구는 누구인가요?","options":[{"t":"서아: 10씩 뛰면 5990 다음은 59100이야.","correct":true,"mis_target":"M2-2-u1-X01"},{"t":"주원: 1씩 뛰면 5990 다음은 5991이야.","mis":"M2-2-u1-X11"},{"t":"라온: 1000씩 뛰면 5990 다음은 6990이야.","mis":"M2-2-u1-X11"}],"explanation":["5990에서 10을 더 뛰면 십의 자리가 10이 돼요.","백·천의 자리로 차례로 넘어가 6000이에요.","서아가 잘못 썼어요."],"variant_rule":{"alt":[{"stem":"4000부터 거꾸로 뛰어 센 다음 수를 썼어요. 잘못 쓴 친구는 누구인가요?","options":[{"t":"지호: 10씩 거꾸로 뛰면 4000 다음은 4990이야.","correct":true,"mis_target":"M2-2-u1-X01"},{"t":"하린: 1씩 거꾸로 뛰면 4000 다음은 3999야.","mis":"M2-2-u1-X11"},{"t":"도윤: 1000씩 거꾸로 뛰면 4000 다음은 3000이야.","mis":"M2-2-u1-X11"}],"explanation":["4000에서 10을 거꾸로 뛰면 천의 자리에서 하나를 빌려 와야 해요.","4000보다 10 작은 수는 3990이에요.","지호가 잘못 썼어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L06_challenge#7','math',2,2,'u1','L06','g2_2_math_u1_L06_challenge','lesson_challenge','M2-2-u1-C5',3,'ox','auto','7004부터 1씩 거꾸로 5번 뛰어 세면 7000이에요.',ARRAY['M2-2-u1-X01']::text[],true,'{"seq":7,"concept":"M2-2-u1-C5","difficulty":3,"kind":"ox","stem":"7004부터 1씩 거꾸로 5번 뛰어 세면 7000이에요.","answer":"X","reason_options":[{"t":"7003, 7002, 7001, 7000, 6999라서 6999니까","correct":true},{"t":"일의 자리 4에서 거꾸로 세면 0에서 멈추니까","mis":"M2-2-u1-X01"}],"mis":"M2-2-u1-X01","explanation":["1씩 거꾸로 5번이면 7003, 7002, 7001, 7000, 6999예요.","7000 다음 한 번 더 세면 6999가 돼요.","그래서 틀린 말이에요."],"variant_rule":{"alt":[{"stem":"2995부터 1씩 5번 뛰어 세면 3000이에요.","answer":"O","reason_options":[{"t":"2996, 2997, 2998, 2999, 3000이니까","correct":true},{"t":"2995, 2996, 2997, 2998, 2999라서","mis":"M2-2-u1-X12"}],"explanation":["1씩 5번이면 2996, 2997, 2998, 2999, 3000이에요.","2999 다음은 3000이에요.","그래서 맞는 말이에요."]},{"stem":"3900부터 100씩 2번 뛰어 세면 31100이에요.","answer":"X","reason_options":[{"t":"4000, 4100이라서 4100이니까","correct":true},{"t":"39 다음은 310, 311이라서","mis":"M2-2-u1-X01"}],"explanation":["3900, 4000, 4100이에요.","3900 다음은 4000 — 백의 자리가 넘어가 천의 자리가 1 커져요.","그래서 틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L06_challenge#8','math',2,2,'u1','L06','g2_2_math_u1_L06_challenge','lesson_challenge','M2-2-u1-C5',4,'mc','auto','규칙에 따라 뛰어 세었어요. 2350, 2450, 2550, ★, 2750 — ★보다 1000만큼 더 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X12']::text[],true,'{"seq":8,"concept":"M2-2-u1-C5","difficulty":4,"kind":"mc","stem":"규칙에 따라 뛰어 세었어요. 2350, 2450, 2550, ★, 2750 — ★보다 1000만큼 더 큰 수는 무엇인가요?","options":[{"t":"3650","correct":true},{"t":"2750","mis":"M2-2-u1-X12"},{"t":"2660","mis":"M2-2-u1-X12"}],"explanation":["100씩 뛰어 세었어요 — ★은 2650이에요.","2650보다 1000 큰 수는 3650이에요.","먼저 규칙으로 ★을 찾고 나서 묻는 말을 풀어요."],"variant_rule":{"alt":[{"stem":"규칙에 따라 뛰어 세었어요. 7408, 6408, 5408, ★, 3408 — ★보다 10만큼 더 큰 수는 무엇인가요?","options":[{"t":"4418","correct":true},{"t":"5408","mis":"M2-2-u1-X12"},{"t":"4409","mis":"M2-2-u1-X12"}],"explanation":["1000씩 거꾸로 뛰어 세었어요 — ★은 4408이에요.","4408보다 10 큰 수는 4418이에요.","먼저 규칙으로 ★을 찾아요."]},{"stem":"규칙에 따라 뛰어 세었어요. 6997, 6998, 6999, ★, 7001 — ★보다 100만큼 더 작은 수는 무엇인가요?","options":[{"t":"6900","correct":true},{"t":"7100","mis":"M2-2-u1-X15"},{"t":"6999","mis":"M2-2-u1-X12"}],"explanation":["1씩 뛰어 세었어요 — ★은 7000이에요.","7000보다 100 작은 수는 6900이에요.","먼저 규칙으로 ★을 찾아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L06_challenge#9','math',2,2,'u1','L06','g2_2_math_u1_L06_challenge','lesson_challenge','M2-2-u1-C5',4,'mc','auto','1740부터 100씩 뛰어 셀 때, 2000보다 큰 수 가운데 처음 나오는 수는 무엇인가요?',ARRAY['M2-2-u1-X11','M2-2-u1-X12']::text[],true,'{"seq":9,"concept":"M2-2-u1-C5","difficulty":4,"kind":"mc","stem":"1740부터 100씩 뛰어 셀 때, 2000보다 큰 수 가운데 처음 나오는 수는 무엇인가요?","options":[{"t":"2040","correct":true},{"t":"2100","mis":"M2-2-u1-X11"},{"t":"2140","mis":"M2-2-u1-X12"}],"explanation":["1740, 1840, 1940, 2040이에요.","2000보다 큰 수 가운데 처음 나오는 수는 2040이에요.","100씩 뛰면 십·일의 자리 40은 그대로예요."],"variant_rule":{"alt":[{"stem":"3650부터 1000씩 뛰어 셀 때, 8000보다 큰 수 가운데 처음 나오는 수는 무엇인가요?","options":[{"t":"8650","correct":true},{"t":"8001","mis":"M2-2-u1-X11"},{"t":"9000","mis":"M2-2-u1-X11"}],"explanation":["3650, 4650, 5650, 6650, 7650, 8650이에요.","8000보다 큰 수 가운데 처음 나오는 수는 8650이에요.","1000씩 뛰면 백·십·일의 자리는 그대로예요."]},{"stem":"6993부터 1씩 뛰어 셀 때, 7000보다 큰 수 가운데 처음 나오는 수는 무엇인가요?","options":[{"t":"7001","correct":true},{"t":"7010","mis":"M2-2-u1-X11"},{"t":"7000","mis":"M2-2-u1-X13"}],"explanation":["6993, … 6999, 7000, 7001이에요.","7000보다 큰 수 가운데 처음 나오는 수는 7001이에요.","7000은 7000보다 크지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L06_challenge#10','math',2,2,'u1','L06','g2_2_math_u1_L06_challenge','lesson_challenge','M2-2-u1-C5',4,'essay','teacher','3990부터 10씩 뛰어 세면 다음 수는 무엇인지 쓰고, 그 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-2-u1-C5","difficulty":4,"kind":"essay","stem":"3990부터 10씩 뛰어 세면 다음 수는 무엇인지 쓰고, 그 까닭을 설명해 보세요.","answer_guide":{"answer":"4000. 3990에서 10을 더하면 십의 자리가 10이 되어 백의 자리로 넘어가고, 백의 자리도 10이 되어 천의 자리로 넘어가므로 4000이 된다.","scoring_points":["다음 수를 4000이라고 바르게 썼는가","십의 자리가 10이 되어 윗자리로 넘어간다고 말했는가","39100처럼 이어 쓰지 않는 까닭을 말했는가"]},"explanation":["3990 다음 10씩이면 십의 자리가 10이 돼요.","10은 윗자리로 넘어가고, 백의 자리도 10이 되어 천의 자리가 1 커져 4000이에요.","숫자를 이어 붙이지 않고 자리를 넘겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_basic#1','math',2,2,'u1','L07','g2_2_math_u1_L07_basic','lesson_basic','M2-2-u1-C6',1,'mc','auto','3542와 3524 중에서 더 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X13']::text[],true,'{"seq":1,"concept":"M2-2-u1-C6","difficulty":1,"kind":"mc","stem":"3542와 3524 중에서 더 큰 수는 무엇인가요?","options":[{"t":"3542","correct":true},{"t":"3524","mis":"M2-2-u1-X13"}],"explanation":["천의 자리와 백의 자리가 같아요.","십의 자리를 보면 4는 2보다 커요 — 더 큰 수는 3542예요.","높은 자리가 다르면 낮은 자리는 보지 않아도 돼요."],"variant_rule":{"cmp4d":{"ask":"big","same":"thh"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_basic#2','math',2,2,'u1','L07','g2_2_math_u1_L07_basic','lesson_basic','M2-2-u1-C6',1,'mc','auto','6372와 6519 중에서 더 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X13']::text[],true,'{"seq":2,"concept":"M2-2-u1-C6","difficulty":1,"kind":"mc","stem":"6372와 6519 중에서 더 큰 수는 무엇인가요?","options":[{"t":"6519","correct":true},{"t":"6372","mis":"M2-2-u1-X13"}],"explanation":["천의 자리가 같아요.","백의 자리를 보면 5는 3보다 커요 — 더 큰 수는 6519예요.","십·일의 자리가 커도 백의 자리가 먼저예요."],"variant_rule":{"cmp4d":{"ask":"big","same":"th"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_basic#3','math',2,2,'u1','L07','g2_2_math_u1_L07_basic','lesson_basic','M2-2-u1-C6',1,'mc','auto','두 수의 크기를 바르게 비교한 것은 어느 것인가요?',ARRAY['M2-2-u1-X14']::text[],true,'{"seq":3,"concept":"M2-2-u1-C6","difficulty":1,"kind":"mc","stem":"두 수의 크기를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"1999 < 2005","correct":true},{"t":"1999 > 2005","mis":"M2-2-u1-X14"}],"explanation":["천의 자리에서 처음으로 달라요 — 2는 1보다 커요.","그래서 2005는 1999보다 커요 — 1999 < 2005.","> 와 < 는 벌어진 쪽이 큰 수를 향해요."],"variant_rule":{"cmp4d":{"ask":"sign"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_basic#4','math',2,2,'u1','L07','g2_2_math_u1_L07_basic','lesson_basic','M2-2-u1-C6',1,'mc','auto','5107과 5400 중에서 더 작은 수는 무엇인가요?',ARRAY['M2-2-u1-X13']::text[],true,'{"seq":4,"concept":"M2-2-u1-C6","difficulty":1,"kind":"mc","stem":"5107과 5400 중에서 더 작은 수는 무엇인가요?","options":[{"t":"5107","correct":true},{"t":"5400","mis":"M2-2-u1-X13"}],"explanation":["천의 자리가 같아요.","백의 자리를 보면 1은 4보다 작아요 — 더 작은 수는 5107이에요.","높은 자리부터 차례로 견주어요."],"variant_rule":{"cmp4d":{"ask":"small","same":"th"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_basic#5','math',2,2,'u1','L07','g2_2_math_u1_L07_basic','lesson_basic','M2-2-u1-C6',2,'mc','auto','6154, 5987, 5843 가운데 가장 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],true,'{"seq":5,"concept":"M2-2-u1-C6","difficulty":2,"kind":"mc","stem":"6154, 5987, 5843 가운데 가장 큰 수는 무엇인가요?","options":[{"t":"6154","correct":true},{"t":"5987","mis":"M2-2-u1-X13"},{"t":"5843","mis":"M2-2-u1-X15"}],"explanation":["높은 자리(천의 자리)부터 차례로 견주어요.","가장 큰 수는 6154예요.","뒤쪽 숫자가 크다고 큰 수가 아니에요 — 높은 자리가 먼저예요."],"variant_rule":{"cmp4d":{"ask":"max3"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_basic#6','math',2,2,'u1','L07','g2_2_math_u1_L07_basic','lesson_basic','M2-2-u1-C6',2,'mc','auto','7105, 7150, 7015 가운데 가장 작은 수는 무엇인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],true,'{"seq":6,"concept":"M2-2-u1-C6","difficulty":2,"kind":"mc","stem":"7105, 7150, 7015 가운데 가장 작은 수는 무엇인가요?","options":[{"t":"7015","correct":true},{"t":"7105","mis":"M2-2-u1-X13"},{"t":"7150","mis":"M2-2-u1-X15"}],"explanation":["천의 자리는 모두 7이에요 — 백의 자리를 견주어요.","백의 자리가 0인 7015가 가장 작아요.","일의 자리가 작다고 작은 수가 아니에요 — 높은 자리가 먼저예요."],"variant_rule":{"cmp4d":{"ask":"min3"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_basic#7','math',2,2,'u1','L07','g2_2_math_u1_L07_basic','lesson_basic','M2-2-u1-C6',2,'ox','auto','1999와 2005 가운데 뒤쪽 숫자가 큰 1999가 더 커요.',ARRAY['M2-2-u1-X13']::text[],true,'{"seq":7,"concept":"M2-2-u1-C6","difficulty":2,"kind":"ox","stem":"1999와 2005 가운데 뒤쪽 숫자가 큰 1999가 더 커요.","answer":"X","reason_options":[{"t":"천의 자리 2가 1보다 커서 2005가 더 크니까","correct":true},{"t":"9가 많으면 더 큰 수니까","mis":"M2-2-u1-X13"}],"mis":"M2-2-u1-X13","explanation":["천의 자리를 먼저 봐요 — 1과 2예요.","천의 자리 2가 더 커서 2005가 더 커요.","그래서 틀린 말이에요 — 1999의 뒤쪽 9들은 볼 필요가 없어요."],"variant_rule":{"alt":[{"stem":"2046은 1422보다 커요.","answer":"O","reason_options":[{"t":"천의 자리 2가 1보다 크니까","correct":true},{"t":"1422는 백의 자리 4가 커서 더 크니까","mis":"M2-2-u1-X13"}],"explanation":["천의 자리를 보면 2가 1보다 커요.","그래서 2046이 더 커요.","그래서 맞는 말이에요."]},{"stem":"일의 자리 숫자가 더 크면 더 큰 수예요.","answer":"X","reason_options":[{"t":"천의 자리부터 차례로 견주어야 하니까","correct":true},{"t":"일의 자리가 커야 크니까","mis":"M2-2-u1-X13"}],"explanation":["네 자리 수는 천의 자리부터 견주어요.","천의 자리가 같으면 백의 자리, 그다음 십·일의 자리를 봐요.","그래서 틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_basic#8','math',2,2,'u1','L07','g2_2_math_u1_L07_basic','lesson_basic','M2-2-u1-C6',2,'blank','auto','8130 (        ) 8103 — 빈칸에 알맞은 것은 어느 것인가요?',ARRAY['M2-2-u1-X14','M2-2-u1-X13']::text[],true,'{"seq":8,"concept":"M2-2-u1-C6","difficulty":2,"kind":"blank","stem":"8130 (        ) 8103 — 빈칸에 알맞은 것은 어느 것인가요?","options":[{"t":">","correct":true},{"t":"<","mis":"M2-2-u1-X14"},{"t":"=","mis":"M2-2-u1-X13"}],"explanation":["천의 자리와 백의 자리가 같아요.","십의 자리를 보면 3이 0보다 커서 8130이 더 커요.","큰 쪽으로 벌어지게 — 8130 > 8103이에요."],"variant_rule":{"alt":[{"stem":"4999 (        ) 5001 — 빈칸에 알맞은 것은 어느 것인가요?","options":[{"t":"<","correct":true},{"t":">","mis":"M2-2-u1-X14"},{"t":"=","mis":"M2-2-u1-X13"}],"explanation":["천의 자리를 보면 4가 5보다 작아요.","그래서 4999가 더 작아요.","작은 쪽을 뾰족하게 — 4999 < 5001이에요."]},{"stem":"2760 (        ) 2706 — 빈칸에 알맞은 것은 어느 것인가요?","options":[{"t":">","correct":true},{"t":"<","mis":"M2-2-u1-X14"},{"t":"=","mis":"M2-2-u1-X13"}],"explanation":["천의 자리와 백의 자리가 같아요.","십의 자리를 보면 6이 0보다 커요.","그래서 2760 > 2706이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_basic#9','math',2,2,'u1','L07','g2_2_math_u1_L07_basic','lesson_basic','M2-2-u1-C6',2,'match','auto','두 수 가운데 더 큰 수끼리 이어 보세요.','{}'::text[],true,'{"seq":9,"concept":"M2-2-u1-C6","difficulty":2,"kind":"match","stem":"두 수 가운데 더 큰 수끼리 이어 보세요.","pairs":[{"l":"3080과 3800","r":"3800"},{"l":"2999와 3001","r":"3001"},{"l":"7510과 7150","r":"7510"}],"mis":"M2-2-u1-X13","explanation":["3080과 3800은 백의 자리 8이 커서 3800이 커요.","2999와 3001은 천의 자리 3이 커서 3001, 7510과 7150은 백의 자리 5가 커서 7510이에요.","높은 자리부터 차례로 견주어요."],"variant_rule":{"alt":[{"stem":"두 수 가운데 더 작은 수끼리 이어 보세요.","pairs":[{"l":"6200과 6020","r":"6020"},{"l":"1999와 2000","r":"1999"},{"l":"8450과 8540","r":"8450"}],"explanation":["6200과 6020은 백의 자리 0이 작아서 6020이 작아요.","1999와 2000은 천의 자리 1이 작아서 1999, 8450과 8540은 8450이에요.","높은 자리부터 차례로 견주어요."]},{"stem":"이번에는 다른 보기예요. 두 수 가운데 더 큰 수끼리 이어 보세요.","pairs":[{"l":"5090과 5900","r":"5900"},{"l":"4000과 3999","r":"4000"},{"l":"2630과 2360","r":"2630"}],"explanation":["5090과 5900은 백의 자리 9가 커서 5900이에요.","4000과 3999는 천의 자리 4가 커서 4000, 2630과 2360은 2630이에요.","높은 자리부터 차례로 견주어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_basic#10','math',2,2,'u1','L07','g2_2_math_u1_L07_basic','lesson_basic','M2-2-u1-C6',3,'mc','auto','독도 방문자가 3월에 5591명, 4월에 5519명, 5월에 5951명이었어요. 방문자가 가장 많은 달은 언제인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],true,'{"seq":10,"concept":"M2-2-u1-C6","difficulty":3,"kind":"mc","stem":"독도 방문자가 3월에 5591명, 4월에 5519명, 5월에 5951명이었어요. 방문자가 가장 많은 달은 언제인가요?","options":[{"t":"5월","correct":true},{"t":"3월","mis":"M2-2-u1-X13"},{"t":"4월","mis":"M2-2-u1-X15"}],"explanation":["세 수의 천의 자리는 5로 같아요.","백의 자리는 5·5·9라 5월이 가장 커요.","그래서 방문자가 가장 많은 달은 5월이에요."],"variant_rule":{"alt":[{"stem":"손수건이 가 상자에 1536장, 나 상자에 1563장, 다 상자에 1356장 있어요. 가장 적게 든 상자는 어느 것인가요?","options":[{"t":"다 상자","correct":true},{"t":"가 상자","mis":"M2-2-u1-X13"},{"t":"나 상자","mis":"M2-2-u1-X15"}],"explanation":["세 수의 천의 자리는 1로 같아요.","백의 자리는 5·5·3이라 다 상자가 가장 적어요.","「가장 적게」를 잘 읽어요."]},{"stem":"연날리기에 연이 첫째 날 2108개, 둘째 날 2081개, 셋째 날 2180개 쓰였어요. 가장 많이 쓰인 날은 언제인가요?","options":[{"t":"셋째 날","correct":true},{"t":"첫째 날","mis":"M2-2-u1-X13"},{"t":"둘째 날","mis":"M2-2-u1-X15"}],"explanation":["세 수의 천의 자리는 2, 백의 자리는 1·0·1이에요.","2108과 2180은 십의 자리를 보면 8이 0보다 커요 — 셋째 날이에요.","일의 자리가 아니라 십의 자리부터 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_challenge#1','math',2,2,'u1','L07','g2_2_math_u1_L07_challenge','lesson_challenge','M2-2-u1-C6',2,'mc','auto','3871, 4120, 3817 가운데 가장 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],true,'{"seq":1,"concept":"M2-2-u1-C6","difficulty":2,"kind":"mc","stem":"3871, 4120, 3817 가운데 가장 큰 수는 무엇인가요?","options":[{"t":"4120","correct":true},{"t":"3871","mis":"M2-2-u1-X13"},{"t":"3817","mis":"M2-2-u1-X15"}],"explanation":["높은 자리(천의 자리)부터 차례로 견주어요.","가장 큰 수는 4120이에요.","뒤쪽 숫자가 크다고 큰 수가 아니에요 — 높은 자리가 먼저예요."],"variant_rule":{"cmp4d":{"ask":"max3"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_challenge#2','math',2,2,'u1','L07','g2_2_math_u1_L07_challenge','lesson_challenge','M2-2-u1-C6',2,'mc','auto','수 카드 3, 8, 5, 1을 한 번씩 모두 써서 만들 수 있는 가장 큰 네 자리 수는 무엇인가요?',ARRAY['M2-2-u1-X15','M2-2-u1-X16']::text[],true,'{"seq":2,"concept":"M2-2-u1-C6","difficulty":2,"kind":"mc","stem":"수 카드 3, 8, 5, 1을 한 번씩 모두 써서 만들 수 있는 가장 큰 네 자리 수는 무엇인가요?","options":[{"t":"8531","correct":true},{"t":"1358","mis":"M2-2-u1-X15"},{"t":"8513","mis":"M2-2-u1-X16"}],"explanation":["가장 큰 8을 천의 자리에 놓아요.","남은 카드도 큰 수부터 — 8531이에요.","높은 자리일수록 큰 숫자를 놓아요."],"variant_rule":{"cards4":{"ask":"max"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_challenge#3','math',2,2,'u1','L07','g2_2_math_u1_L07_challenge','lesson_challenge','M2-2-u1-C6',3,'mc','auto','수 카드 4, 0, 7, 2를 한 번씩 모두 써서 만들 수 있는 가장 작은 네 자리 수는 무엇인가요?',ARRAY['M2-2-u1-X16','M2-2-u1-X15']::text[],true,'{"seq":3,"concept":"M2-2-u1-C6","difficulty":3,"kind":"mc","stem":"수 카드 4, 0, 7, 2를 한 번씩 모두 써서 만들 수 있는 가장 작은 네 자리 수는 무엇인가요?","options":[{"t":"2047","correct":true},{"t":"247","mis":"M2-2-u1-X16"},{"t":"7420","mis":"M2-2-u1-X15"}],"explanation":["0은 천의 자리에 놓을 수 없어요(그러면 세 자리 수).","천의 자리에 2, 백의 자리에 0, 그다음 4, 7 — 2047이에요.","0이 있으면 천의 자리 다음 자리에 놓아요."],"variant_rule":{"cards4":{"ask":"min","zero":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_challenge#4','math',2,2,'u1','L07','g2_2_math_u1_L07_challenge','lesson_challenge','M2-2-u1-C6',3,'mc','auto','4518 < □618에서 □에 들어갈 수 있는 가장 작은 수는 무엇인가요? (□에는 1부터 9까지)',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],true,'{"seq":4,"concept":"M2-2-u1-C6","difficulty":3,"kind":"mc","stem":"4518 < □618에서 □에 들어갈 수 있는 가장 작은 수는 무엇인가요? (□에는 1부터 9까지)","options":[{"t":"4","correct":true},{"t":"5","mis":"M2-2-u1-X13"},{"t":"1","mis":"M2-2-u1-X15"}],"explanation":["□가 4이면 4618 — 천의 자리가 같으니 백의 자리 6과 5를 견주어요.","6이 5보다 커서 4618 > 4518이에요. □가 3이면 3618이라 작아요.","그래서 가장 작은 수는 4예요."],"variant_rule":{"alt":[{"stem":"3725 < □650에서 □에 들어갈 수 있는 가장 작은 수는 무엇인가요? (□에는 1부터 9까지)","options":[{"t":"4","correct":true},{"t":"3","mis":"M2-2-u1-X13"},{"t":"9","mis":"M2-2-u1-X15"}],"explanation":["□가 3이면 3650 — 백의 자리 6이 7보다 작아 3725보다 작아요.","□가 4이면 4650 — 천의 자리 4가 3보다 커요.","그래서 가장 작은 수는 4예요."]},{"stem":"7□48은 7562보다 커요. □에 들어갈 수 있는 가장 작은 수는 무엇인가요?","options":[{"t":"6","correct":true},{"t":"5","mis":"M2-2-u1-X13"},{"t":"0","mis":"M2-2-u1-X15"}],"explanation":["천의 자리는 7로 같으니 백의 자리를 견주어요.","□가 5이면 7548 — 십의 자리 4가 6보다 작아 7562보다 작아요. □가 6이면 7648이라 커요.","그래서 가장 작은 수는 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_challenge#5','math',2,2,'u1','L07','g2_2_math_u1_L07_challenge','lesson_challenge','M2-2-u1-C6',3,'sa','auto','6□45는 6345보다 작아요. □에 들어갈 수 있는 수는 모두 몇 개인가요?','{}'::text[],true,'{"seq":5,"concept":"M2-2-u1-C6","difficulty":3,"kind":"sa","stem":"6□45는 6345보다 작아요. □에 들어갈 수 있는 수는 모두 몇 개인가요?","answer":["3","3개"],"explanation":["천의 자리는 6으로 같으니 백의 자리를 견주어요.","□가 3이면 6345와 같아요 — □는 3보다 작은 0, 1, 2예요.","그래서 모두 3개예요."],"variant_rule":{"alt":[{"stem":"2□80은 2560보다 커요. □에 들어갈 수 있는 수는 모두 몇 개인가요?","answer":["5","5개"],"explanation":["천의 자리는 2로 같으니 백의 자리를 견주어요.","□가 5이면 2580 — 십의 자리 8이 6보다 커서 2560보다 커요. □는 5, 6, 7, 8, 9예요.","그래서 모두 5개예요 — □가 백의 자리 숫자 5와 같을 때도 꼭 살펴요."]},{"stem":"83□4는 8374보다 작아요. □에 들어갈 수 있는 수는 모두 몇 개인가요?","answer":["7","7개"],"explanation":["천·백의 자리가 같으니 십의 자리를 견주어요.","□가 7이면 8374와 같아요 — □는 0부터 6까지예요.","그래서 모두 7개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_challenge#6','math',2,2,'u1','L07','g2_2_math_u1_L07_challenge','lesson_challenge','M2-2-u1-C6',3,'error','auto','친구들이 두 수를 비교했어요. 잘못 비교한 친구는 누구인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X14']::text[],true,'{"seq":6,"concept":"M2-2-u1-C6","difficulty":3,"kind":"error","stem":"친구들이 두 수를 비교했어요. 잘못 비교한 친구는 누구인가요?","options":[{"t":"도하: 2998 > 3002 (9가 0보다 크니까)","correct":true,"mis_target":"M2-2-u1-X13"},{"t":"유진: 4500 < 5040","mis":"M2-2-u1-X14"},{"t":"세아: 6710 > 6170","mis":"M2-2-u1-X13"}],"explanation":["2998과 3002는 천의 자리부터 봐요 — 2는 3보다 작아요.","그래서 2998 < 3002예요.","도하가 잘못 비교했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 두 수를 비교했어요. 잘못 비교한 친구는 누구인가요?","options":[{"t":"준우: 8360 < 8291 (십의 자리 6이 9보다 작아서)","correct":true,"mis_target":"M2-2-u1-X13"},{"t":"서준: 9005 > 8999","mis":"M2-2-u1-X13"},{"t":"라희: 7120 < 7210","mis":"M2-2-u1-X14"}],"explanation":["8360과 8291은 천의 자리가 같으니 백의 자리를 봐요 — 3이 2보다 커요.","그래서 8360 > 8291이에요.","준우가 잘못 비교했어요 — 백의 자리를 건너뛰었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_challenge#7','math',2,2,'u1','L07','g2_2_math_u1_L07_challenge','lesson_challenge','M2-2-u1-C6',3,'mc','auto','독도 이야기에 나오는 연도 2005, 1982, 2010, 1999 가운데 가장 오래전 연도는 무엇인가요?',ARRAY['M2-2-u1-X15','M2-2-u1-X13']::text[],true,'{"seq":7,"concept":"M2-2-u1-C6","difficulty":3,"kind":"mc","stem":"독도 이야기에 나오는 연도 2005, 1982, 2010, 1999 가운데 가장 오래전 연도는 무엇인가요?","options":[{"t":"1982","correct":true},{"t":"2010","mis":"M2-2-u1-X15"},{"t":"1999","mis":"M2-2-u1-X13"}],"explanation":["수가 작을수록 오래전이에요 — 가장 작은 수를 찾아요.","천의 자리가 1인 1982와 1999 가운데 십의 자리 8이 9보다 작아요.","그래서 가장 오래전 연도는 1982예요."],"variant_rule":{"alt":[{"stem":"독도 이야기에 나오는 연도 2005, 1982, 2010, 1999 가운데 가장 최근 연도는 무엇인가요?","options":[{"t":"2010","correct":true},{"t":"1982","mis":"M2-2-u1-X15"},{"t":"2005","mis":"M2-2-u1-X13"}],"explanation":["수가 클수록 최근이에요 — 가장 큰 수를 찾아요.","천의 자리가 2인 2005와 2010 가운데 십의 자리 1이 0보다 커요.","그래서 가장 최근 연도는 2010이에요."]},{"stem":"연도 1953, 1935, 1995 가운데 가장 오래전 연도는 무엇인가요?","options":[{"t":"1935","correct":true},{"t":"1995","mis":"M2-2-u1-X15"},{"t":"1953","mis":"M2-2-u1-X13"}],"explanation":["천·백의 자리가 1, 9로 같아요.","십의 자리 3이 가장 작아 1935가 가장 작아요.","수가 작을수록 오래전이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_challenge#8','math',2,2,'u1','L07','g2_2_math_u1_L07_challenge','lesson_challenge','M2-2-u1-C6',4,'mc','auto','천의 자리 숫자가 5이고, 백의 자리 숫자가 십의 자리 숫자보다 큰 네 자리 수 가운데 5400보다 작은 가장 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],true,'{"seq":8,"concept":"M2-2-u1-C6","difficulty":4,"kind":"mc","stem":"천의 자리 숫자가 5이고, 백의 자리 숫자가 십의 자리 숫자보다 큰 네 자리 수 가운데 5400보다 작은 가장 큰 수는 무엇인가요?","options":[{"t":"5329","correct":true},{"t":"5399","mis":"M2-2-u1-X13"},{"t":"5432","mis":"M2-2-u1-X15"}],"explanation":["5400보다 작으니 백의 자리 숫자는 3까지예요(54□□는 5400 이상).","백의 자리가 3이면 십의 자리는 3보다 작아야 해요 — 가장 큰 것은 2, 일의 자리는 9예요.","그래서 5329예요."],"variant_rule":{"alt":[{"stem":"천의 자리 숫자가 3이고, 일의 자리 숫자가 십의 자리 숫자보다 큰 네 자리 수 가운데 가장 작은 수는 무엇인가요?","options":[{"t":"3001","correct":true},{"t":"3000","mis":"M2-2-u1-X13"},{"t":"3010","mis":"M2-2-u1-X16"}],"explanation":["가장 작은 수는 백·십의 자리를 0으로 해요.","일의 자리는 0보다 커야 하니 가장 작은 1이에요.","그래서 3001이에요."]},{"stem":"천의 자리 숫자가 7이고, 네 숫자가 모두 다른 수 가운데 7600보다 큰 가장 작은 수는 무엇인가요?","options":[{"t":"7601","correct":true},{"t":"7600","mis":"M2-2-u1-X13"},{"t":"7610","mis":"M2-2-u1-X16"}],"explanation":["7600보다 커야 하니 760□에서 □는 1부터예요.","7, 6, 0, 1은 모두 달라요.","그래서 7601이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_challenge#9','math',2,2,'u1','L07','g2_2_math_u1_L07_challenge','lesson_challenge','M2-2-u1-C6',4,'mc','auto','수 카드 6, 0, 2, 9, 4 가운데 네 장을 골라 만들 수 있는 네 자리 수 가운데 5000보다 작은 가장 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X15','M2-2-u1-X16']::text[],true,'{"seq":9,"concept":"M2-2-u1-C6","difficulty":4,"kind":"mc","stem":"수 카드 6, 0, 2, 9, 4 가운데 네 장을 골라 만들 수 있는 네 자리 수 가운데 5000보다 작은 가장 큰 수는 무엇인가요?","options":[{"t":"4962","correct":true},{"t":"9642","mis":"M2-2-u1-X15"},{"t":"4026","mis":"M2-2-u1-X16"}],"explanation":["5000보다 작으려면 천의 자리에 6·9는 올 수 없고 0도 올 수 없어요 — 가장 큰 4예요.","남은 카드 6, 0, 2, 9 가운데 큰 수부터 — 9, 6, 2예요.","그래서 4962예요."],"variant_rule":{"alt":[{"stem":"수 카드 1, 7, 0, 4, 8 가운데 네 장을 골라 만들 수 있는 네 자리 수 가운데 가장 작은 수는 무엇인가요?","options":[{"t":"1047","correct":true},{"t":"147","mis":"M2-2-u1-X16"},{"t":"8741","mis":"M2-2-u1-X15"}],"explanation":["0은 천의 자리에 올 수 없어요 — 가장 작은 1을 놓아요.","남은 카드 가운데 작은 0, 4, 7을 차례로 놓아요.","그래서 1047이에요."]},{"stem":"수 카드 5, 8, 3, 1, 6 가운데 네 장을 골라 만들 수 있는 네 자리 수 가운데 6000보다 큰 가장 작은 수는 무엇인가요?","options":[{"t":"6135","correct":true},{"t":"5136","mis":"M2-2-u1-X13"},{"t":"8653","mis":"M2-2-u1-X15"}],"explanation":["6000보다 크려면 천의 자리는 6이나 8 — 작은 6을 놓아요.","남은 카드 가운데 작은 1, 3, 5를 차례로 놓아요.","그래서 6135예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_L07_challenge#10','math',2,2,'u1','L07','g2_2_math_u1_L07_challenge','lesson_challenge','M2-2-u1-C6',4,'essay','teacher','1999와 2005 가운데 더 큰 수를 고르고, 높은 자리부터 비교하는 방법으로 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-2-u1-C6","difficulty":4,"kind":"essay","stem":"1999와 2005 가운데 더 큰 수를 고르고, 높은 자리부터 비교하는 방법으로 설명해 보세요.","answer_guide":{"answer":"2005가 더 크다. 천의 자리를 보면 2가 1보다 크므로 2005가 더 크다. 1999의 뒤쪽 9들은 볼 필요가 없다.","scoring_points":["2005를 골랐는가","천의 자리 2와 1을 견주어 설명했는가","뒤쪽 숫자(9)로 판단하지 않았는가"]},"explanation":["천의 자리를 먼저 봐요 — 1과 2예요.","2가 더 크니 2005가 더 커요.","높은 자리가 다르면 낮은 자리는 볼 필요가 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#1','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C1',1,'mc','auto','999보다 1만큼 더 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X01','M2-2-u1-X12']::text[],false,'{"seq":1,"concept":"M2-2-u1-C1","difficulty":1,"kind":"mc","stem":"999보다 1만큼 더 큰 수는 무엇인가요?","options":[{"t":"1000","correct":true},{"t":"9910","mis":"M2-2-u1-X01"},{"t":"998","mis":"M2-2-u1-X12"}],"explanation":["999 바로 다음 수예요.","999보다 1 큰 수는 1000이에요.","9 뒤에 10을 붙이지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#2','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C2',1,'mc','auto','1000이 5개이면 얼마인가요?',ARRAY['M2-2-u1-X03']::text[],true,'{"seq":2,"concept":"M2-2-u1-C2","difficulty":1,"kind":"mc","stem":"1000이 5개이면 얼마인가요?","options":[{"t":"5000","correct":true},{"t":"1005","mis":"M2-2-u1-X03"},{"t":"500","mis":"M2-2-u1-X03"}],"explanation":["1000이 5개이면 5000이에요.","「오천」이라고 읽어요.","개수는 천의 자리에 쓰고, 백·십·일의 자리는 0이에요."],"variant_rule":{"n4":{"ask":"thou"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#3','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C3',1,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-2-u1-X06','M2-2-u1-X05']::text[],true,'{"seq":3,"concept":"M2-2-u1-C3","difficulty":1,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"2475","correct":true},{"t":"5742","mis":"M2-2-u1-X06"},{"t":"2000400705","mis":"M2-2-u1-X05"}],"explanation":["1000이 2개, 100이 4개, 10이 7개, 1이 5개예요.","천의 자리 2, 백의 자리 4, 십의 자리 7, 일의 자리 5 — 2475예요.","천·백·십·일 차례로 숫자를 써요."],"asset":{"type":"blocks4","th":2,"h":4,"t":7,"o":5},"variant_rule":{"n4":{"ask":"build"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#4','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C3',1,'match','auto','수와 읽기를 바르게 이어 보세요.','{}'::text[],false,'{"seq":4,"concept":"M2-2-u1-C3","difficulty":1,"kind":"match","stem":"수와 읽기를 바르게 이어 보세요.","pairs":[{"l":"5207","r":"오천이백칠"},{"l":"5027","r":"오천이십칠"},{"l":"5270","r":"오천이백칠십"}],"mis":"M2-2-u1-X07","explanation":["5207은 「오천이백칠」이에요.","5027은 「오천이십칠」, 5270은 「오천이백칠십」이에요.","0인 자리는 읽지 않고, 숫자 뒤에 자리 이름을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#5','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C4',1,'mc','auto','4826에서 백의 자리 숫자는 무엇인가요?',ARRAY['M2-2-u1-X08','M2-2-u1-X09']::text[],true,'{"seq":5,"concept":"M2-2-u1-C4","difficulty":1,"kind":"mc","stem":"4826에서 백의 자리 숫자는 무엇인가요?","options":[{"t":"8","correct":true},{"t":"2","mis":"M2-2-u1-X08"},{"t":"800","mis":"M2-2-u1-X09"}],"explanation":["4826은 천의 자리 4, 백의 자리 8, 십의 자리 2, 일의 자리 6이에요.","백의 자리 숫자는 8이에요.","자리는 왼쪽부터 천·백·십·일 — 숫자를 물으면 값이 아니라 숫자 하나로 답해요."],"variant_rule":{"pv4":{"ask":"digit"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#6','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C5',1,'mc','auto','1000씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u1-X11']::text[],true,'{"seq":6,"concept":"M2-2-u1-C5","difficulty":1,"kind":"mc","stem":"1000씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"6500","correct":true},{"t":"5510","mis":"M2-2-u1-X11"},{"t":"5600","mis":"M2-2-u1-X11"}],"explanation":["1000씩 뛰면 천의 자리 숫자가 1씩 커져요.","5500에서 1000만큼 뛰면 6500이에요.","다른 자리 숫자는 그대로예요."],"asset":{"type":"jump_row","cells":[2500,3500,4500,5500,null],"step":1000},"variant_rule":{"skip4":{"ask":"next","step":[1000]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#7','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C6',1,'mc','auto','6380과 6830 중에서 더 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X13']::text[],true,'{"seq":7,"concept":"M2-2-u1-C6","difficulty":1,"kind":"mc","stem":"6380과 6830 중에서 더 큰 수는 무엇인가요?","options":[{"t":"6830","correct":true},{"t":"6380","mis":"M2-2-u1-X13"}],"explanation":["천의 자리가 같아요.","백의 자리를 보면 8은 3보다 커요 — 더 큰 수는 6830이에요.","높은 자리가 다르면 낮은 자리는 보지 않아도 돼요."],"variant_rule":{"cmp4d":{"ask":"big","same":"th"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#8','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C2',1,'sa','auto','6000은 1000이 몇 개인가요?','{}'::text[],true,'{"seq":8,"concept":"M2-2-u1-C2","difficulty":1,"kind":"sa","stem":"6000은 1000이 몇 개인가요?","answer":["6","6개"],"explanation":["6000은 천의 자리 숫자가 6이에요.","1000이 6개예요.","천의 자리 숫자가 1000의 개수예요."],"variant_rule":{"n4":{"ask":"tcount"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#9','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C1',2,'blank','auto','1000은 900보다 (        )만큼 더 큰 수예요.',ARRAY['M2-2-u1-X12']::text[],false,'{"seq":9,"concept":"M2-2-u1-C1","difficulty":2,"kind":"blank","stem":"1000은 900보다 (        )만큼 더 큰 수예요.","options":[{"t":"100","correct":true},{"t":"10","mis":"M2-2-u1-X12"},{"t":"1","mis":"M2-2-u1-X12"}],"explanation":["900 다음 100씩 뛰면 1000이에요.","그래서 1000은 900보다 100 커요.","백 모형 1개 차이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#10','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C3',2,'mc','auto','「사천구」를 수로 쓰면 무엇인가요?',ARRAY['M2-2-u1-X05','M2-2-u1-X04']::text[],true,'{"seq":10,"concept":"M2-2-u1-C3","difficulty":2,"kind":"mc","stem":"「사천구」를 수로 쓰면 무엇인가요?","options":[{"t":"4009","correct":true},{"t":"40009","mis":"M2-2-u1-X05"},{"t":"49","mis":"M2-2-u1-X04"}],"explanation":["「사천구」는 1000이 4개, 100이 0개, 10이 0개, 1이 9개예요.","수로 쓰면 4009예요.","읽지 않은 자리에는 0을 써요."],"variant_rule":{"n4":{"ask":"write","zero":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#11','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C4',2,'mc','auto','9475에서 숫자 4가 나타내는 값은 얼마인가요?',ARRAY['M2-2-u1-X08','M2-2-u1-X09']::text[],true,'{"seq":11,"concept":"M2-2-u1-C4","difficulty":2,"kind":"mc","stem":"9475에서 숫자 4가 나타내는 값은 얼마인가요?","options":[{"t":"400","correct":true},{"t":"4000","mis":"M2-2-u1-X08"},{"t":"4","mis":"M2-2-u1-X09"}],"explanation":["숫자 4는 백의 자리에 있어요.","백의 자리 4는 400을 나타내요.","같은 숫자라도 어느 자리에 있느냐에 따라 값이 달라요."],"variant_rule":{"pv4":{"ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#12','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C4',2,'mc','auto','3742를 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u1-X09','M2-2-u1-X08']::text[],true,'{"seq":12,"concept":"M2-2-u1-C4","difficulty":2,"kind":"mc","stem":"3742를 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"3000 + 700 + 40 + 2","correct":true},{"t":"3 + 7 + 4 + 2","mis":"M2-2-u1-X09"},{"t":"3000 + 400 + 70 + 2","mis":"M2-2-u1-X08"}],"explanation":["3742는 천의 자리 3, 백의 자리 7, 십의 자리 4, 일의 자리 2예요.","각 자리의 값은 3000, 700, 40, 2 — 3742 = 3000 + 700 + 40 + 2.","숫자 하나하나에 자리 값을 붙여야 해요."],"variant_rule":{"pv4":{"ask":"expand"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#13','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C5',2,'mc','auto','얼마씩 뛰어 세었나요?',ARRAY['M2-2-u1-X12']::text[],true,'{"seq":13,"concept":"M2-2-u1-C5","difficulty":2,"kind":"mc","stem":"얼마씩 뛰어 세었나요?","options":[{"t":"100씩","correct":true},{"t":"1000씩","mis":"M2-2-u1-X12"},{"t":"10씩","mis":"M2-2-u1-X12"}],"explanation":["5200, 5300, 5400 … 하고 백의 자리 숫자만 1씩 커져요.","그래서 100씩 뛰어 세었어요.","어느 자리 숫자가 바뀌는지 보면 몇씩 뛰었는지 알 수 있어요."],"asset":{"type":"jump_row","cells":[5200,5300,5400,5500,5600],"step":null},"variant_rule":{"skip4":{"ask":"step","step":[1,10,100,1000],"dir":"both"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#14','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C6',2,'mc','auto','두 수의 크기를 바르게 비교한 것은 어느 것인가요?',ARRAY['M2-2-u1-X14']::text[],true,'{"seq":14,"concept":"M2-2-u1-C6","difficulty":2,"kind":"mc","stem":"두 수의 크기를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"6030 > 5980","correct":true},{"t":"6030 < 5980","mis":"M2-2-u1-X14"}],"explanation":["천의 자리에서 처음으로 달라요 — 6은 5보다 커요.","그래서 6030은 5980보다 커요 — 6030 > 5980.","> 와 < 는 벌어진 쪽이 큰 수를 향해요."],"variant_rule":{"cmp4d":{"ask":"sign"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#15','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C2',2,'error','auto','친구들이 몇천에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u1-X03','M2-2-u1-X07','M2-2-u1-X12']::text[],false,'{"seq":15,"concept":"M2-2-u1-C2","difficulty":2,"kind":"error","stem":"친구들이 몇천에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우: 7000은 1000이 70개야.","correct":true,"mis_target":"M2-2-u1-X03"},{"t":"하린: 7000은 「칠천」이라고 읽어.","mis":"M2-2-u1-X07"},{"t":"도윤: 7000은 6000보다 1000 큰 수야.","mis":"M2-2-u1-X12"}],"explanation":["7000은 천의 자리 숫자가 7이에요.","그래서 1000이 7개예요 — 70개가 아니에요.","은우가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#16','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C7',2,'mc','auto','100이 23개인 수는 얼마인가요?',ARRAY['M2-2-u1-X02','M2-2-u1-X10']::text[],true,'{"seq":16,"concept":"M2-2-u1-C7","difficulty":2,"kind":"mc","stem":"100이 23개인 수는 얼마인가요?","options":[{"t":"2300","correct":true},{"t":"10023","mis":"M2-2-u1-X02"},{"t":"230","mis":"M2-2-u1-X10"}],"explanation":["100이 10개면 1000이에요.","100이 23개는 1000이 2개, 100이 3개 — 2300이에요.","100이 10개 넘게 모이면 1000으로 바꿔 세요."],"variant_rule":{"n4":{"ask":"hund"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#17','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C5',3,'mc','auto','10씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u1-X01','M2-2-u1-X11']::text[],true,'{"seq":17,"concept":"M2-2-u1-C5","difficulty":3,"kind":"mc","stem":"10씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"4000","correct":true},{"t":"39100","mis":"M2-2-u1-X01"},{"t":"3991","mis":"M2-2-u1-X11"}],"explanation":["10씩 뛰면 십의 자리 숫자가 1씩 커져요.","3990에서 10만큼 뛰면 4000이에요.","십의 자리가 10이 되면 바로 윗자리가 1 커지고 십의 자리는 0이 돼요."],"asset":{"type":"jump_row","cells":[3970,3980,3990,null,4010],"step":10},"variant_rule":{"skip4":{"ask":"blank","step":[10],"cross":true,"dir":"up"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#18','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C6',3,'mc','auto','4960, 5120, 4690 가운데 가장 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],true,'{"seq":18,"concept":"M2-2-u1-C6","difficulty":3,"kind":"mc","stem":"4960, 5120, 4690 가운데 가장 큰 수는 무엇인가요?","options":[{"t":"5120","correct":true},{"t":"4960","mis":"M2-2-u1-X13"},{"t":"4690","mis":"M2-2-u1-X15"}],"explanation":["높은 자리(천의 자리)부터 차례로 견주어요.","가장 큰 수는 5120이에요.","뒤쪽 숫자가 크다고 큰 수가 아니에요 — 높은 자리가 먼저예요."],"variant_rule":{"cmp4d":{"ask":"max3"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#19','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C7',3,'mc','auto','돈은 모두 얼마인가요?',ARRAY['M2-2-u1-X10']::text[],true,'{"seq":19,"concept":"M2-2-u1-C7","difficulty":3,"kind":"mc","stem":"돈은 모두 얼마인가요?","options":[{"t":"3340원","correct":true},{"t":"21340원","mis":"M2-2-u1-X10"},{"t":"2340원","mis":"M2-2-u1-X10"}],"explanation":["100원짜리 13개는 천 원짜리 1장과 100원짜리 3개로 바꿀 수 있어요.","천 원짜리 3장, 100원짜리 3개, 10원짜리 4개 — 3340원이에요.","한 자리에 10개가 모이면 바로 윗자리 1개로 바꿔요."],"asset":{"type":"blocks4","th":2,"h":13,"t":4,"o":0,"unit":"coin"},"variant_rule":{"n4":{"ask":"build","carry":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#20','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C3',3,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-2-u1-X10']::text[],true,'{"seq":20,"concept":"M2-2-u1-C3","difficulty":3,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"2263","correct":true},{"t":"11263","mis":"M2-2-u1-X10"},{"t":"1263","mis":"M2-2-u1-X10"}],"explanation":["백 모형 12개는 천 모형 1개와 백 모형 2개로 바꿀 수 있어요.","1000이 2개, 100이 2개, 10이 6개, 1이 3개 — 2263이에요.","한 자리에 10개가 모이면 바로 윗자리 1개로 바꿔요."],"asset":{"type":"blocks4","th":1,"h":12,"t":6,"o":3},"variant_rule":{"n4":{"ask":"build","carry":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#21','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C4',3,'ox','auto','7373에서 두 숫자 7이 나타내는 값은 같아요.',ARRAY['M2-2-u1-X09']::text[],false,'{"seq":21,"concept":"M2-2-u1-C4","difficulty":3,"kind":"ox","stem":"7373에서 두 숫자 7이 나타내는 값은 같아요.","answer":"X","reason_options":[{"t":"앞의 7은 7000, 뒤의 7은 70이니까","correct":true},{"t":"같은 숫자는 값도 같으니까","mis":"M2-2-u1-X09"}],"mis":"M2-2-u1-X09","explanation":["앞의 7은 천의 자리라 7000이에요.","뒤의 7은 십의 자리라 70이에요.","그래서 틀린 말이에요 — 자리에 따라 값이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#22','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C6',3,'mc','auto','수 카드 2, 9, 6, 3을 한 번씩 모두 써서 만들 수 있는 가장 큰 네 자리 수는 무엇인가요?',ARRAY['M2-2-u1-X15','M2-2-u1-X16']::text[],true,'{"seq":22,"concept":"M2-2-u1-C6","difficulty":3,"kind":"mc","stem":"수 카드 2, 9, 6, 3을 한 번씩 모두 써서 만들 수 있는 가장 큰 네 자리 수는 무엇인가요?","options":[{"t":"9632","correct":true},{"t":"2369","mis":"M2-2-u1-X15"},{"t":"9623","mis":"M2-2-u1-X16"}],"explanation":["가장 큰 9를 천의 자리에 놓아요.","남은 카드도 큰 수부터 — 9632예요.","높은 자리일수록 큰 숫자를 놓아요."],"variant_rule":{"cards4":{"ask":"max"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#23','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C7',4,'mc','auto','천 원짜리 3장과 100원짜리 동전 4개를 모두 100원짜리 동전으로 바꾸면 몇 개가 되나요?',ARRAY['M2-2-u1-X03','M2-2-u1-X04']::text[],false,'{"seq":23,"concept":"M2-2-u1-C7","difficulty":4,"kind":"mc","stem":"천 원짜리 3장과 100원짜리 동전 4개를 모두 100원짜리 동전으로 바꾸면 몇 개가 되나요?","options":[{"t":"34","correct":true},{"t":"7","mis":"M2-2-u1-X03"},{"t":"304","mis":"M2-2-u1-X04"}],"explanation":["천 원짜리 한 장은 100원짜리 10개예요.","천 원짜리 3장은 100원짜리 30개 — 4개를 더하면 34개예요.","3400원은 100이 34개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#24','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C6',4,'mc','auto','5□73은 5672보다 커요. □에 들어갈 수 있는 수는 모두 몇 개인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],false,'{"seq":24,"concept":"M2-2-u1-C6","difficulty":4,"kind":"mc","stem":"5□73은 5672보다 커요. □에 들어갈 수 있는 수는 모두 몇 개인가요?","options":[{"t":"4","correct":true},{"t":"3","mis":"M2-2-u1-X13"},{"t":"5","mis":"M2-2-u1-X15"}],"explanation":["천의 자리는 5로 같으니 백의 자리를 견주어요.","□가 6이면 5673 — 십의 자리는 같고 일의 자리 3이 2보다 커서 커요. □는 6, 7, 8, 9예요.","그래서 모두 4개예요 — □가 같을 때도 꼭 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_a#25','math',2,2,'u1','','g2_2_math_u1_review_a','unit_review','M2-2-u1-C5',4,'essay','teacher','2995부터 1씩 7번 뛰어 센 수를 차례로 쓰고, 자리가 바뀌는 곳을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-2-u1-C5","difficulty":4,"kind":"essay","stem":"2995부터 1씩 7번 뛰어 센 수를 차례로 쓰고, 자리가 바뀌는 곳을 설명해 보세요.","answer_guide":{"answer":"2996, 2997, 2998, 2999, 3000, 3001, 3002. 2999 다음에 일의 자리가 10이 되어 십의 자리로, 십·백의 자리도 차례로 10이 되어 천의 자리로 넘어가 3000이 된다.","scoring_points":["뛰어 센 수를 차례로 바르게 썼는가","자리가 넘어가는(바뀌는) 곳을 설명했는가","몇씩 뛰었는지에 맞는 자리만 바뀐다는 것을 말했는가"]},"explanation":["뛰는 자리 숫자만 1씩 바뀌어요.","그 자리가 10이 되면 윗자리로 넘어가고, 0에서 더 작아지면 윗자리에서 빌려 와요.","숫자를 이어 붙이지 않고 자리를 넘겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#1','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C1',1,'mc','auto','900보다 100만큼 더 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X12','M2-2-u1-X01']::text[],false,'{"seq":1,"concept":"M2-2-u1-C1","difficulty":1,"kind":"mc","stem":"900보다 100만큼 더 큰 수는 무엇인가요?","options":[{"t":"1000","correct":true},{"t":"910","mis":"M2-2-u1-X12"},{"t":"9100","mis":"M2-2-u1-X01"}],"explanation":["900에서 100을 더 뛰어요.","900보다 100 큰 수는 1000이에요.","100만큼과 10만큼을 헷갈리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#2','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C2',1,'mc','auto','1000이 7개이면 얼마인가요?',ARRAY['M2-2-u1-X03']::text[],true,'{"seq":2,"concept":"M2-2-u1-C2","difficulty":1,"kind":"mc","stem":"1000이 7개이면 얼마인가요?","options":[{"t":"7000","correct":true},{"t":"1007","mis":"M2-2-u1-X03"},{"t":"700","mis":"M2-2-u1-X03"}],"explanation":["1000이 7개이면 7000이에요.","「칠천」이라고 읽어요.","개수는 천의 자리에 쓰고, 백·십·일의 자리는 0이에요."],"variant_rule":{"n4":{"ask":"thou"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#3','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C3',1,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-2-u1-X06','M2-2-u1-X05']::text[],true,'{"seq":3,"concept":"M2-2-u1-C3","difficulty":1,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"3618","correct":true},{"t":"8163","mis":"M2-2-u1-X06"},{"t":"3000600108","mis":"M2-2-u1-X05"}],"explanation":["1000이 3개, 100이 6개, 10이 1개, 1이 8개예요.","천의 자리 3, 백의 자리 6, 십의 자리 1, 일의 자리 8 — 3618이에요.","천·백·십·일 차례로 숫자를 써요."],"asset":{"type":"blocks4","th":3,"h":6,"t":1,"o":8},"variant_rule":{"n4":{"ask":"build"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#4','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C3',1,'match','auto','수와 읽기를 바르게 이어 보세요.','{}'::text[],false,'{"seq":4,"concept":"M2-2-u1-C3","difficulty":1,"kind":"match","stem":"수와 읽기를 바르게 이어 보세요.","pairs":[{"l":"3108","r":"삼천백팔"},{"l":"3018","r":"삼천십팔"},{"l":"3180","r":"삼천백팔십"}],"mis":"M2-2-u1-X07","explanation":["3108은 「삼천백팔」이에요.","3018은 「삼천십팔」, 3180은 「삼천백팔십」이에요.","0인 자리는 읽지 않고, 숫자 뒤에 자리 이름을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#5','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C4',1,'mc','auto','7361에서 천의 자리 숫자는 무엇인가요?',ARRAY['M2-2-u1-X08','M2-2-u1-X09']::text[],true,'{"seq":5,"concept":"M2-2-u1-C4","difficulty":1,"kind":"mc","stem":"7361에서 천의 자리 숫자는 무엇인가요?","options":[{"t":"7","correct":true},{"t":"1","mis":"M2-2-u1-X08"},{"t":"7000","mis":"M2-2-u1-X09"}],"explanation":["7361은 천의 자리 7, 백의 자리 3, 십의 자리 6, 일의 자리 1이에요.","천의 자리 숫자는 7이에요.","자리는 왼쪽부터 천·백·십·일 — 숫자를 물으면 값이 아니라 숫자 하나로 답해요."],"variant_rule":{"pv4":{"ask":"digit"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#6','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C5',1,'mc','auto','100씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u1-X11']::text[],true,'{"seq":6,"concept":"M2-2-u1-C5","difficulty":1,"kind":"mc","stem":"100씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"6530","correct":true},{"t":"6440","mis":"M2-2-u1-X11"},{"t":"7430","mis":"M2-2-u1-X11"}],"explanation":["100씩 뛰면 백의 자리 숫자가 1씩 커져요.","6430에서 100만큼 뛰면 6530이에요.","다른 자리 숫자는 그대로예요."],"asset":{"type":"jump_row","cells":[6130,6230,6330,6430,null],"step":100},"variant_rule":{"skip4":{"ask":"next","step":[100]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#7','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C6',1,'mc','auto','4710과 4170 중에서 더 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X13']::text[],true,'{"seq":7,"concept":"M2-2-u1-C6","difficulty":1,"kind":"mc","stem":"4710과 4170 중에서 더 큰 수는 무엇인가요?","options":[{"t":"4710","correct":true},{"t":"4170","mis":"M2-2-u1-X13"}],"explanation":["천의 자리가 같아요.","백의 자리를 보면 7은 1보다 커요 — 더 큰 수는 4710이에요.","높은 자리가 다르면 낮은 자리는 보지 않아도 돼요."],"variant_rule":{"cmp4d":{"ask":"big","same":"th"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#8','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C2',1,'sa','auto','4000은 1000이 몇 개인가요?','{}'::text[],true,'{"seq":8,"concept":"M2-2-u1-C2","difficulty":1,"kind":"sa","stem":"4000은 1000이 몇 개인가요?","answer":["4","4개"],"explanation":["4000은 천의 자리 숫자가 4예요.","1000이 4개예요.","천의 자리 숫자가 1000의 개수예요."],"variant_rule":{"n4":{"ask":"tcount"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#9','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C1',2,'blank','auto','1000은 999보다 (        )만큼 더 큰 수예요.',ARRAY['M2-2-u1-X12']::text[],false,'{"seq":9,"concept":"M2-2-u1-C1","difficulty":2,"kind":"blank","stem":"1000은 999보다 (        )만큼 더 큰 수예요.","options":[{"t":"1","correct":true},{"t":"10","mis":"M2-2-u1-X12"},{"t":"100","mis":"M2-2-u1-X12"}],"explanation":["999 바로 다음 수가 1000이에요.","그래서 1000은 999보다 1 커요.","바로 다음 수는 1 큰 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#10','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C3',2,'mc','auto','「팔천육십」을 수로 쓰면 무엇인가요?',ARRAY['M2-2-u1-X05','M2-2-u1-X04']::text[],true,'{"seq":10,"concept":"M2-2-u1-C3","difficulty":2,"kind":"mc","stem":"「팔천육십」을 수로 쓰면 무엇인가요?","options":[{"t":"8060","correct":true},{"t":"800060","mis":"M2-2-u1-X05"},{"t":"86","mis":"M2-2-u1-X04"}],"explanation":["「팔천육십」은 1000이 8개, 100이 0개, 10이 6개, 1이 0개예요.","수로 쓰면 8060이에요.","읽지 않은 자리에는 0을 써요."],"variant_rule":{"n4":{"ask":"write","zero":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#11','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C4',2,'mc','auto','2638에서 숫자 6이 나타내는 값은 얼마인가요?',ARRAY['M2-2-u1-X08','M2-2-u1-X09']::text[],true,'{"seq":11,"concept":"M2-2-u1-C4","difficulty":2,"kind":"mc","stem":"2638에서 숫자 6이 나타내는 값은 얼마인가요?","options":[{"t":"600","correct":true},{"t":"6000","mis":"M2-2-u1-X08"},{"t":"6","mis":"M2-2-u1-X09"}],"explanation":["숫자 6은 백의 자리에 있어요.","백의 자리 6은 600을 나타내요.","같은 숫자라도 어느 자리에 있느냐에 따라 값이 달라요."],"variant_rule":{"pv4":{"ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#12','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C4',2,'mc','auto','5281을 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u1-X09','M2-2-u1-X08']::text[],true,'{"seq":12,"concept":"M2-2-u1-C4","difficulty":2,"kind":"mc","stem":"5281을 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"5000 + 200 + 80 + 1","correct":true},{"t":"5 + 2 + 8 + 1","mis":"M2-2-u1-X09"},{"t":"5000 + 800 + 20 + 1","mis":"M2-2-u1-X08"}],"explanation":["5281은 천의 자리 5, 백의 자리 2, 십의 자리 8, 일의 자리 1이에요.","각 자리의 값은 5000, 200, 80, 1 — 5281 = 5000 + 200 + 80 + 1.","숫자 하나하나에 자리 값을 붙여야 해요."],"variant_rule":{"pv4":{"ask":"expand"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#13','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C5',2,'mc','auto','얼마씩 거꾸로 뛰어 세었나요?',ARRAY['M2-2-u1-X12']::text[],true,'{"seq":13,"concept":"M2-2-u1-C5","difficulty":2,"kind":"mc","stem":"얼마씩 거꾸로 뛰어 세었나요?","options":[{"t":"1000씩","correct":true},{"t":"100씩","mis":"M2-2-u1-X12"},{"t":"10씩","mis":"M2-2-u1-X12"}],"explanation":["8150, 7150, 6150 … 하고 천의 자리 숫자만 1씩 작아져요.","그래서 1000씩 거꾸로 뛰어 세었어요.","어느 자리 숫자가 바뀌는지 보면 몇씩 뛰었는지 알 수 있어요."],"asset":{"type":"jump_row","cells":[8150,7150,6150,5150,4150],"step":null,"dir":"down"},"variant_rule":{"skip4":{"ask":"step","step":[1,10,100,1000],"dir":"both"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#14','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C6',2,'mc','auto','두 수의 크기를 바르게 비교한 것은 어느 것인가요?',ARRAY['M2-2-u1-X14']::text[],true,'{"seq":14,"concept":"M2-2-u1-C6","difficulty":2,"kind":"mc","stem":"두 수의 크기를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"4720 > 4270","correct":true},{"t":"4720 < 4270","mis":"M2-2-u1-X14"}],"explanation":["백의 자리에서 처음으로 달라요 — 7은 2보다 커요.","그래서 4720은 4270보다 커요 — 4720 > 4270.","> 와 < 는 벌어진 쪽이 큰 수를 향해요."],"variant_rule":{"cmp4d":{"ask":"sign"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#15','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C2',2,'error','auto','친구들이 몇천에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u1-X03','M2-2-u1-X07','M2-2-u1-X12']::text[],false,'{"seq":15,"concept":"M2-2-u1-C2","difficulty":2,"kind":"error","stem":"친구들이 몇천에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아: 1000이 4개이면 1004야.","correct":true,"mis_target":"M2-2-u1-X03"},{"t":"준우: 4000은 「사천」이라고 읽어.","mis":"M2-2-u1-X07"},{"t":"라희: 4000은 3000보다 1000 큰 수야.","mis":"M2-2-u1-X12"}],"explanation":["1000이 4개이면 4000이에요.","개수를 일의 자리에 붙여 1004로 쓰지 않아요.","서아가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#16','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C7',2,'mc','auto','100이 31개인 수는 얼마인가요?',ARRAY['M2-2-u1-X02','M2-2-u1-X10']::text[],true,'{"seq":16,"concept":"M2-2-u1-C7","difficulty":2,"kind":"mc","stem":"100이 31개인 수는 얼마인가요?","options":[{"t":"3100","correct":true},{"t":"10031","mis":"M2-2-u1-X02"},{"t":"310","mis":"M2-2-u1-X10"}],"explanation":["100이 10개면 1000이에요.","100이 31개는 1000이 3개, 100이 1개 — 3100이에요.","100이 10개 넘게 모이면 1000으로 바꿔 세요."],"variant_rule":{"n4":{"ask":"hund"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#17','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C5',3,'mc','auto','1씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u1-X01','M2-2-u1-X11']::text[],true,'{"seq":17,"concept":"M2-2-u1-C5","difficulty":3,"kind":"mc","stem":"1씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"6000","correct":true},{"t":"59910","mis":"M2-2-u1-X01"},{"t":"6009","mis":"M2-2-u1-X11"}],"explanation":["1씩 뛰면 일의 자리 숫자가 1씩 커져요.","5999에서 1만큼 뛰면 6000이에요.","일의 자리가 10이 되면 바로 윗자리가 1 커지고 일의 자리는 0이 돼요."],"asset":{"type":"jump_row","cells":[5998,5999,null,6001,6002],"step":1},"variant_rule":{"skip4":{"ask":"blank","step":[1],"cross":true,"dir":"up"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#18','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C6',3,'mc','auto','3180, 4020, 4910 가운데 가장 작은 수는 무엇인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],true,'{"seq":18,"concept":"M2-2-u1-C6","difficulty":3,"kind":"mc","stem":"3180, 4020, 4910 가운데 가장 작은 수는 무엇인가요?","options":[{"t":"3180","correct":true},{"t":"4020","mis":"M2-2-u1-X13"},{"t":"4910","mis":"M2-2-u1-X15"}],"explanation":["높은 자리(천의 자리)부터 차례로 견주어요.","가장 작은 수는 3180이에요.","뒤쪽 숫자가 크다고 큰 수가 아니에요 — 높은 자리가 먼저예요."],"variant_rule":{"cmp4d":{"ask":"min3"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#19','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C7',3,'mc','auto','돈은 모두 얼마인가요?',ARRAY['M2-2-u1-X10']::text[],true,'{"seq":19,"concept":"M2-2-u1-C7","difficulty":3,"kind":"mc","stem":"돈은 모두 얼마인가요?","options":[{"t":"3660원","correct":true},{"t":"35160원","mis":"M2-2-u1-X10"},{"t":"3560원","mis":"M2-2-u1-X10"}],"explanation":["10원짜리 16개는 100원짜리 1개와 10원짜리 6개로 바꿀 수 있어요.","천 원짜리 3장, 100원짜리 6개, 10원짜리 6개 — 3660원이에요.","한 자리에 10개가 모이면 바로 윗자리 1개로 바꿔요."],"asset":{"type":"blocks4","th":3,"h":5,"t":16,"o":0,"unit":"coin"},"variant_rule":{"n4":{"ask":"build","carry":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#20','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C3',3,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-2-u1-X10']::text[],true,'{"seq":20,"concept":"M2-2-u1-C3","difficulty":3,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"3552","correct":true},{"t":"34152","mis":"M2-2-u1-X10"},{"t":"3452","mis":"M2-2-u1-X10"}],"explanation":["십 모형 15개는 백 모형 1개와 십 모형 5개로 바꿀 수 있어요.","1000이 3개, 100이 5개, 10이 5개, 1이 2개 — 3552예요.","한 자리에 10개가 모이면 바로 윗자리 1개로 바꿔요."],"asset":{"type":"blocks4","th":3,"h":4,"t":15,"o":2},"variant_rule":{"n4":{"ask":"build","carry":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#21','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C4',3,'ox','auto','1991에서 두 숫자 1이 나타내는 값은 1000과 1이에요.',ARRAY['M2-2-u1-X09']::text[],false,'{"seq":21,"concept":"M2-2-u1-C4","difficulty":3,"kind":"ox","stem":"1991에서 두 숫자 1이 나타내는 값은 1000과 1이에요.","answer":"O","reason_options":[{"t":"천의 자리 1은 1000, 일의 자리 1은 1이니까","correct":true},{"t":"같은 숫자는 값도 같으니까","mis":"M2-2-u1-X09"}],"mis":"M2-2-u1-X09","explanation":["앞의 1은 천의 자리라 1000이에요.","뒤의 1은 일의 자리라 1이에요.","그래서 맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#22','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C6',3,'mc','auto','수 카드 5, 0, 3, 8을 한 번씩 모두 써서 만들 수 있는 가장 작은 네 자리 수는 무엇인가요?',ARRAY['M2-2-u1-X16','M2-2-u1-X15']::text[],true,'{"seq":22,"concept":"M2-2-u1-C6","difficulty":3,"kind":"mc","stem":"수 카드 5, 0, 3, 8을 한 번씩 모두 써서 만들 수 있는 가장 작은 네 자리 수는 무엇인가요?","options":[{"t":"3058","correct":true},{"t":"358","mis":"M2-2-u1-X16"},{"t":"8530","mis":"M2-2-u1-X15"}],"explanation":["0은 천의 자리에 놓을 수 없어요(그러면 세 자리 수).","천의 자리에 3, 백의 자리에 0, 그다음 5, 8 — 3058이에요.","0이 있으면 천의 자리 다음 자리에 놓아요."],"variant_rule":{"cards4":{"ask":"min","zero":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#23','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C7',4,'mc','auto','천 원짜리 2장을 모두 100원짜리 동전으로 바꾸면 몇 개가 되나요?',ARRAY['M2-2-u1-X02','M2-2-u1-X09']::text[],false,'{"seq":23,"concept":"M2-2-u1-C7","difficulty":4,"kind":"mc","stem":"천 원짜리 2장을 모두 100원짜리 동전으로 바꾸면 몇 개가 되나요?","options":[{"t":"20","correct":true},{"t":"2","mis":"M2-2-u1-X02"},{"t":"200","mis":"M2-2-u1-X09"}],"explanation":["천 원짜리 한 장은 100원짜리 10개예요.","천 원짜리 2장은 100원짜리 20개예요.","2000원은 100이 20개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#24','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C6',4,'mc','auto','□280은 4320보다 작아요. □에 들어갈 수 있는 수는 모두 몇 개인가요? (□에는 1부터 9까지)',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],false,'{"seq":24,"concept":"M2-2-u1-C6","difficulty":4,"kind":"mc","stem":"□280은 4320보다 작아요. □에 들어갈 수 있는 수는 모두 몇 개인가요? (□에는 1부터 9까지)","options":[{"t":"4","correct":true},{"t":"3","mis":"M2-2-u1-X13"},{"t":"5","mis":"M2-2-u1-X15"}],"explanation":["□가 4이면 4280 — 백의 자리 2가 3보다 작아 4320보다 작아요.","□가 5부터는 커요. □는 1, 2, 3, 4예요.","그래서 모두 4개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_b#25','math',2,2,'u1','','g2_2_math_u1_review_b','unit_review','M2-2-u1-C5',4,'essay','teacher','4960부터 10씩 4번 뛰어 센 수를 차례로 쓰고, 자리가 바뀌는 곳을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-2-u1-C5","difficulty":4,"kind":"essay","stem":"4960부터 10씩 4번 뛰어 센 수를 차례로 쓰고, 자리가 바뀌는 곳을 설명해 보세요.","answer_guide":{"answer":"4970, 4980, 4990, 5000. 4990 다음에 십의 자리가 10이 되어 백의 자리로, 백의 자리도 10이 되어 천의 자리로 넘어가 5000이 된다.","scoring_points":["뛰어 센 수를 차례로 바르게 썼는가","자리가 넘어가는(바뀌는) 곳을 설명했는가","몇씩 뛰었는지에 맞는 자리만 바뀐다는 것을 말했는가"]},"explanation":["뛰는 자리 숫자만 1씩 바뀌어요.","그 자리가 10이 되면 윗자리로 넘어가고, 0에서 더 작아지면 윗자리에서 빌려 와요.","숫자를 이어 붙이지 않고 자리를 넘겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#1','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C1',1,'mc','auto','100이 10개인 수는 무엇인가요?',ARRAY['M2-2-u1-X02']::text[],false,'{"seq":1,"concept":"M2-2-u1-C1","difficulty":1,"kind":"mc","stem":"100이 10개인 수는 무엇인가요?","options":[{"t":"1000","correct":true},{"t":"10010","mis":"M2-2-u1-X02"},{"t":"200","mis":"M2-2-u1-X02"}],"explanation":["100씩 10번 세어요.","100이 10개이면 1000이에요.","100을 늘어놓아 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#2','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C2',1,'mc','auto','1000이 3개이면 얼마인가요?',ARRAY['M2-2-u1-X03']::text[],true,'{"seq":2,"concept":"M2-2-u1-C2","difficulty":1,"kind":"mc","stem":"1000이 3개이면 얼마인가요?","options":[{"t":"3000","correct":true},{"t":"1003","mis":"M2-2-u1-X03"},{"t":"300","mis":"M2-2-u1-X03"}],"explanation":["1000이 3개이면 3000이에요.","「삼천」이라고 읽어요.","개수는 천의 자리에 쓰고, 백·십·일의 자리는 0이에요."],"variant_rule":{"n4":{"ask":"thou"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#3','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C3',1,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-2-u1-X06','M2-2-u1-X05']::text[],true,'{"seq":3,"concept":"M2-2-u1-C3","difficulty":1,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"5284","correct":true},{"t":"4825","mis":"M2-2-u1-X06"},{"t":"5000200804","mis":"M2-2-u1-X05"}],"explanation":["1000이 5개, 100이 2개, 10이 8개, 1이 4개예요.","천의 자리 5, 백의 자리 2, 십의 자리 8, 일의 자리 4 — 5284예요.","천·백·십·일 차례로 숫자를 써요."],"asset":{"type":"blocks4","th":5,"h":2,"t":8,"o":4},"variant_rule":{"n4":{"ask":"build"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#4','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C3',1,'match','auto','수와 읽기를 바르게 이어 보세요.','{}'::text[],false,'{"seq":4,"concept":"M2-2-u1-C3","difficulty":1,"kind":"match","stem":"수와 읽기를 바르게 이어 보세요.","pairs":[{"l":"6409","r":"육천사백구"},{"l":"6049","r":"육천사십구"},{"l":"6490","r":"육천사백구십"}],"mis":"M2-2-u1-X07","explanation":["6409는 「육천사백구」예요.","6049는 「육천사십구」, 6490은 「육천사백구십」이에요.","0인 자리는 읽지 않고, 숫자 뒤에 자리 이름을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#5','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C4',1,'mc','auto','1594에서 일의 자리 숫자는 무엇인가요?',ARRAY['M2-2-u1-X08']::text[],true,'{"seq":5,"concept":"M2-2-u1-C4","difficulty":1,"kind":"mc","stem":"1594에서 일의 자리 숫자는 무엇인가요?","options":[{"t":"4","correct":true},{"t":"1","mis":"M2-2-u1-X08"},{"t":"5","mis":"M2-2-u1-X08"}],"explanation":["1594는 천의 자리 1, 백의 자리 5, 십의 자리 9, 일의 자리 4예요.","일의 자리 숫자는 4예요.","자리는 왼쪽부터 천·백·십·일 — 숫자를 물으면 값이 아니라 숫자 하나로 답해요."],"variant_rule":{"pv4":{"ask":"digit"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#6','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C5',1,'mc','auto','1씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u1-X11']::text[],true,'{"seq":6,"concept":"M2-2-u1-C5","difficulty":1,"kind":"mc","stem":"1씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"3845","correct":true},{"t":"3944","mis":"M2-2-u1-X11"},{"t":"4844","mis":"M2-2-u1-X11"}],"explanation":["1씩 뛰면 일의 자리 숫자가 1씩 커져요.","3844에서 1만큼 뛰면 3845예요.","다른 자리 숫자는 그대로예요."],"asset":{"type":"jump_row","cells":[3841,3842,3843,3844,null],"step":1},"variant_rule":{"skip4":{"ask":"next","step":[1]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#7','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C6',1,'mc','auto','9250과 9520 중에서 더 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X13']::text[],true,'{"seq":7,"concept":"M2-2-u1-C6","difficulty":1,"kind":"mc","stem":"9250과 9520 중에서 더 큰 수는 무엇인가요?","options":[{"t":"9520","correct":true},{"t":"9250","mis":"M2-2-u1-X13"}],"explanation":["천의 자리가 같아요.","백의 자리를 보면 5는 2보다 커요 — 더 큰 수는 9520이에요.","높은 자리가 다르면 낮은 자리는 보지 않아도 돼요."],"variant_rule":{"cmp4d":{"ask":"big","same":"th"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#8','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C2',1,'sa','auto','8000은 1000이 몇 개인가요?','{}'::text[],true,'{"seq":8,"concept":"M2-2-u1-C2","difficulty":1,"kind":"sa","stem":"8000은 1000이 몇 개인가요?","answer":["8","8개"],"explanation":["8000은 천의 자리 숫자가 8이에요.","1000이 8개예요.","천의 자리 숫자가 1000의 개수예요."],"variant_rule":{"n4":{"ask":"tcount"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#9','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C1',2,'blank','auto','1000은 100이 (        )개인 수예요.',ARRAY['M2-2-u1-X02','M2-2-u1-X09']::text[],false,'{"seq":9,"concept":"M2-2-u1-C1","difficulty":2,"kind":"blank","stem":"1000은 100이 (        )개인 수예요.","options":[{"t":"10","correct":true},{"t":"1","mis":"M2-2-u1-X02"},{"t":"100","mis":"M2-2-u1-X09"}],"explanation":["100씩 세어 1000까지 가요.","10번 세면 1000이에요.","그래서 100이 10개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#10','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C3',2,'mc','auto','「칠천이」를 수로 쓰면 무엇인가요?',ARRAY['M2-2-u1-X05','M2-2-u1-X04']::text[],true,'{"seq":10,"concept":"M2-2-u1-C3","difficulty":2,"kind":"mc","stem":"「칠천이」를 수로 쓰면 무엇인가요?","options":[{"t":"7002","correct":true},{"t":"70002","mis":"M2-2-u1-X05"},{"t":"72","mis":"M2-2-u1-X04"}],"explanation":["「칠천이」는 1000이 7개, 100이 0개, 10이 0개, 1이 2개예요.","수로 쓰면 7002예요.","읽지 않은 자리에는 0을 써요."],"variant_rule":{"n4":{"ask":"write","zero":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#11','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C4',2,'mc','auto','5182에서 숫자 8이 나타내는 값은 얼마인가요?',ARRAY['M2-2-u1-X08','M2-2-u1-X09']::text[],true,'{"seq":11,"concept":"M2-2-u1-C4","difficulty":2,"kind":"mc","stem":"5182에서 숫자 8이 나타내는 값은 얼마인가요?","options":[{"t":"80","correct":true},{"t":"8000","mis":"M2-2-u1-X08"},{"t":"8","mis":"M2-2-u1-X09"}],"explanation":["숫자 8은 십의 자리에 있어요.","십의 자리 8은 80을 나타내요.","같은 숫자라도 어느 자리에 있느냐에 따라 값이 달라요."],"variant_rule":{"pv4":{"ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#12','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C4',2,'mc','auto','9614를 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u1-X09','M2-2-u1-X08']::text[],true,'{"seq":12,"concept":"M2-2-u1-C4","difficulty":2,"kind":"mc","stem":"9614를 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"9000 + 600 + 10 + 4","correct":true},{"t":"9 + 6 + 1 + 4","mis":"M2-2-u1-X09"},{"t":"9000 + 100 + 60 + 4","mis":"M2-2-u1-X08"}],"explanation":["9614는 천의 자리 9, 백의 자리 6, 십의 자리 1, 일의 자리 4예요.","각 자리의 값은 9000, 600, 10, 4 — 9614 = 9000 + 600 + 10 + 4.","숫자 하나하나에 자리 값을 붙여야 해요."],"variant_rule":{"pv4":{"ask":"expand"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#13','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C5',2,'mc','auto','얼마씩 뛰어 세었나요?',ARRAY['M2-2-u1-X12']::text[],true,'{"seq":13,"concept":"M2-2-u1-C5","difficulty":2,"kind":"mc","stem":"얼마씩 뛰어 세었나요?","options":[{"t":"10씩","correct":true},{"t":"1000씩","mis":"M2-2-u1-X12"},{"t":"100씩","mis":"M2-2-u1-X12"}],"explanation":["3470, 3480, 3490 … 하고 십의 자리 숫자만 1씩 커져요.","그래서 10씩 뛰어 세었어요.","어느 자리 숫자가 바뀌는지 보면 몇씩 뛰었는지 알 수 있어요."],"asset":{"type":"jump_row","cells":[3470,3480,3490,3500,3510],"step":null},"variant_rule":{"skip4":{"ask":"step","step":[1,10,100,1000],"dir":"both"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#14','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C6',2,'mc','auto','두 수의 크기를 바르게 비교한 것은 어느 것인가요?',ARRAY['M2-2-u1-X14']::text[],true,'{"seq":14,"concept":"M2-2-u1-C6","difficulty":2,"kind":"mc","stem":"두 수의 크기를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"8150 < 8510","correct":true},{"t":"8150 > 8510","mis":"M2-2-u1-X14"}],"explanation":["백의 자리에서 처음으로 달라요 — 5는 1보다 커요.","그래서 8510은 8150보다 커요 — 8150 < 8510.","> 와 < 는 벌어진 쪽이 큰 수를 향해요."],"variant_rule":{"cmp4d":{"ask":"sign"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#15','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C2',2,'error','auto','친구들이 몇천에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u1-X03','M2-2-u1-X07','M2-2-u1-X12']::text[],false,'{"seq":15,"concept":"M2-2-u1-C2","difficulty":2,"kind":"error","stem":"친구들이 몇천에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지호: 천 모형 8개는 800이야.","correct":true,"mis_target":"M2-2-u1-X03"},{"t":"하윤: 8000은 「팔천」이라고 읽어.","mis":"M2-2-u1-X07"},{"t":"시우: 8000은 9000보다 1000 작은 수야.","mis":"M2-2-u1-X12"}],"explanation":["천 모형 8개는 1000이 8개 — 8000이에요.","800은 백 모형 8개예요.","지호가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#16','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C7',2,'mc','auto','100이 17개인 수는 얼마인가요?',ARRAY['M2-2-u1-X02','M2-2-u1-X10']::text[],true,'{"seq":16,"concept":"M2-2-u1-C7","difficulty":2,"kind":"mc","stem":"100이 17개인 수는 얼마인가요?","options":[{"t":"1700","correct":true},{"t":"10017","mis":"M2-2-u1-X02"},{"t":"170","mis":"M2-2-u1-X10"}],"explanation":["100이 10개면 1000이에요.","100이 17개는 1000이 1개, 100이 7개 — 1700이에요.","100이 10개 넘게 모이면 1000으로 바꿔 세요."],"variant_rule":{"n4":{"ask":"hund"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#17','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C5',3,'mc','auto','100씩 거꾸로 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u1-X01','M2-2-u1-X11']::text[],true,'{"seq":17,"concept":"M2-2-u1-C5","difficulty":3,"kind":"mc","stem":"100씩 거꾸로 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"6900","correct":true},{"t":"7900","mis":"M2-2-u1-X01"},{"t":"6999","mis":"M2-2-u1-X11"}],"explanation":["100씩 거꾸로 뛰면 백의 자리 숫자가 1씩 작아져요.","7000에서 100만큼 거꾸로 뛰면 6900이에요.","백의 자리가 0에서 더 작아지면 바로 윗자리에서 1을 빌려 와요."],"asset":{"type":"jump_row","cells":[7200,7100,7000,null,6800],"step":100,"dir":"down"},"variant_rule":{"skip4":{"ask":"blank","step":[100],"cross":true,"dir":"down"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#18','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C6',3,'mc','auto','7500, 6990, 6570 가운데 가장 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],true,'{"seq":18,"concept":"M2-2-u1-C6","difficulty":3,"kind":"mc","stem":"7500, 6990, 6570 가운데 가장 큰 수는 무엇인가요?","options":[{"t":"7500","correct":true},{"t":"6990","mis":"M2-2-u1-X13"},{"t":"6570","mis":"M2-2-u1-X15"}],"explanation":["높은 자리(천의 자리)부터 차례로 견주어요.","가장 큰 수는 7500이에요.","뒤쪽 숫자가 크다고 큰 수가 아니에요 — 높은 자리가 먼저예요."],"variant_rule":{"cmp4d":{"ask":"max3"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#19','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C7',3,'mc','auto','돈은 모두 얼마인가요?',ARRAY['M2-2-u1-X10']::text[],true,'{"seq":19,"concept":"M2-2-u1-C7","difficulty":3,"kind":"mc","stem":"돈은 모두 얼마인가요?","options":[{"t":"2400원","correct":true},{"t":"11400원","mis":"M2-2-u1-X10"},{"t":"1400원","mis":"M2-2-u1-X10"}],"explanation":["100원짜리 14개는 천 원짜리 1장과 100원짜리 4개로 바꿀 수 있어요.","천 원짜리 2장, 100원짜리 4개 — 2400원이에요.","한 자리에 10개가 모이면 바로 윗자리 1개로 바꿔요."],"asset":{"type":"blocks4","th":1,"h":14,"t":0,"o":0,"unit":"coin"},"variant_rule":{"n4":{"ask":"build","carry":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#20','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C3',3,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-2-u1-X10']::text[],true,'{"seq":20,"concept":"M2-2-u1-C3","difficulty":3,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"3137","correct":true},{"t":"21137","mis":"M2-2-u1-X10"},{"t":"2137","mis":"M2-2-u1-X10"}],"explanation":["백 모형 11개는 천 모형 1개와 백 모형 1개로 바꿀 수 있어요.","1000이 3개, 100이 1개, 10이 3개, 1이 7개 — 3137이에요.","한 자리에 10개가 모이면 바로 윗자리 1개로 바꿔요."],"asset":{"type":"blocks4","th":2,"h":11,"t":3,"o":7},"variant_rule":{"n4":{"ask":"build","carry":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#21','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C4',3,'ox','auto','8580에서 두 숫자 8이 나타내는 값을 모으면 16이에요.',ARRAY['M2-2-u1-X09']::text[],false,'{"seq":21,"concept":"M2-2-u1-C4","difficulty":3,"kind":"ox","stem":"8580에서 두 숫자 8이 나타내는 값을 모으면 16이에요.","answer":"X","reason_options":[{"t":"8000과 80을 모으면 8080이니까","correct":true},{"t":"8과 8을 모으면 16이니까","mis":"M2-2-u1-X09"}],"mis":"M2-2-u1-X09","explanation":["앞의 8은 8000, 뒤의 8은 80을 나타내요.","8000과 80을 모으면 8080이에요.","그래서 틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#22','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C6',3,'mc','auto','수 카드 7, 1, 4, 6을 한 번씩 모두 써서 만들 수 있는 가장 작은 네 자리 수는 무엇인가요?',ARRAY['M2-2-u1-X16','M2-2-u1-X15']::text[],true,'{"seq":22,"concept":"M2-2-u1-C6","difficulty":3,"kind":"mc","stem":"수 카드 7, 1, 4, 6을 한 번씩 모두 써서 만들 수 있는 가장 작은 네 자리 수는 무엇인가요?","options":[{"t":"1467","correct":true},{"t":"1476","mis":"M2-2-u1-X16"},{"t":"7641","mis":"M2-2-u1-X15"}],"explanation":["가장 작은 1을 천의 자리에 놓아요.","남은 카드도 작은 수부터 — 1467이에요.","높은 자리일수록 작은 숫자를 놓아요."],"variant_rule":{"cards4":{"ask":"min"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#23','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C7',4,'mc','auto','100원짜리 동전 47개를 천 원짜리와 100원짜리로 바꾸어 돈의 개수를 가장 적게 하면 지폐와 동전은 모두 몇 개인가요?',ARRAY['M2-2-u1-X10','M2-2-u1-X15']::text[],false,'{"seq":23,"concept":"M2-2-u1-C7","difficulty":4,"kind":"mc","stem":"100원짜리 동전 47개를 천 원짜리와 100원짜리로 바꾸어 돈의 개수를 가장 적게 하면 지폐와 동전은 모두 몇 개인가요?","options":[{"t":"11","correct":true},{"t":"47","mis":"M2-2-u1-X10"},{"t":"4","mis":"M2-2-u1-X15"}],"explanation":["100원짜리 47개는 4700원 — 천 원짜리 4장과 100원짜리 7개로 바꿀 수 있어요.","지폐 4장과 동전 7개, 모두 11개예요.","묻는 것은 지폐와 동전 「모두」의 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#24','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C6',4,'mc','auto','73□9는 7339보다 작아요. □에 들어갈 수 있는 수는 모두 몇 개인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],false,'{"seq":24,"concept":"M2-2-u1-C6","difficulty":4,"kind":"mc","stem":"73□9는 7339보다 작아요. □에 들어갈 수 있는 수는 모두 몇 개인가요?","options":[{"t":"3","correct":true},{"t":"4","mis":"M2-2-u1-X13"},{"t":"6","mis":"M2-2-u1-X15"}],"explanation":["천·백의 자리가 같으니 십의 자리를 견주어요.","□가 3이면 7339와 같아요. □는 0, 1, 2예요.","그래서 모두 3개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_c#25','math',2,2,'u1','','g2_2_math_u1_review_c','unit_review','M2-2-u1-C5',4,'essay','teacher','6200부터 100씩 거꾸로 4번 뛰어 센 수를 차례로 쓰고, 자리가 바뀌는 곳을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-2-u1-C5","difficulty":4,"kind":"essay","stem":"6200부터 100씩 거꾸로 4번 뛰어 센 수를 차례로 쓰고, 자리가 바뀌는 곳을 설명해 보세요.","answer_guide":{"answer":"6100, 6000, 5900, 5800. 6000에서 100 작아질 때 백의 자리가 0이라 천의 자리에서 1을 빌려 와 5900이 된다.","scoring_points":["뛰어 센 수를 차례로 바르게 썼는가","자리가 넘어가는(바뀌는) 곳을 설명했는가","몇씩 뛰었는지에 맞는 자리만 바뀐다는 것을 말했는가"]},"explanation":["뛰는 자리 숫자만 1씩 바뀌어요.","그 자리가 10이 되면 윗자리로 넘어가고, 0에서 더 작아지면 윗자리에서 빌려 와요.","숫자를 이어 붙이지 않고 자리를 넘겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#1','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C1',1,'mc','auto','990보다 10만큼 더 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X01','M2-2-u1-X12']::text[],false,'{"seq":1,"concept":"M2-2-u1-C1","difficulty":1,"kind":"mc","stem":"990보다 10만큼 더 큰 수는 무엇인가요?","options":[{"t":"1000","correct":true},{"t":"9910","mis":"M2-2-u1-X01"},{"t":"991","mis":"M2-2-u1-X12"}],"explanation":["990에서 10을 더 뛰어요.","990보다 10 큰 수는 1000이에요.","얼마만큼 큰지 잘 세어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#2','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C2',1,'mc','auto','1000이 9개이면 얼마인가요?',ARRAY['M2-2-u1-X03']::text[],true,'{"seq":2,"concept":"M2-2-u1-C2","difficulty":1,"kind":"mc","stem":"1000이 9개이면 얼마인가요?","options":[{"t":"9000","correct":true},{"t":"1009","mis":"M2-2-u1-X03"},{"t":"900","mis":"M2-2-u1-X03"}],"explanation":["1000이 9개이면 9000이에요.","「구천」이라고 읽어요.","개수는 천의 자리에 쓰고, 백·십·일의 자리는 0이에요."],"variant_rule":{"n4":{"ask":"thou"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#3','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C3',1,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-2-u1-X06','M2-2-u1-X05']::text[],true,'{"seq":3,"concept":"M2-2-u1-C3","difficulty":1,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"4736","correct":true},{"t":"6374","mis":"M2-2-u1-X06"},{"t":"4000700306","mis":"M2-2-u1-X05"}],"explanation":["1000이 4개, 100이 7개, 10이 3개, 1이 6개예요.","천의 자리 4, 백의 자리 7, 십의 자리 3, 일의 자리 6 — 4736이에요.","천·백·십·일 차례로 숫자를 써요."],"asset":{"type":"blocks4","th":4,"h":7,"t":3,"o":6},"variant_rule":{"n4":{"ask":"build"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#4','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C3',1,'match','auto','수와 읽기를 바르게 이어 보세요.','{}'::text[],false,'{"seq":4,"concept":"M2-2-u1-C3","difficulty":1,"kind":"match","stem":"수와 읽기를 바르게 이어 보세요.","pairs":[{"l":"4105","r":"사천백오"},{"l":"4015","r":"사천십오"},{"l":"4150","r":"사천백오십"}],"mis":"M2-2-u1-X07","explanation":["4105는 「사천백오」예요.","4015는 「사천십오」, 4150은 「사천백오십」이에요.","0인 자리는 읽지 않고, 숫자 뒤에 자리 이름을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#5','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C4',1,'mc','auto','9273에서 십의 자리 숫자는 무엇인가요?',ARRAY['M2-2-u1-X08','M2-2-u1-X09']::text[],true,'{"seq":5,"concept":"M2-2-u1-C4","difficulty":1,"kind":"mc","stem":"9273에서 십의 자리 숫자는 무엇인가요?","options":[{"t":"7","correct":true},{"t":"2","mis":"M2-2-u1-X08"},{"t":"70","mis":"M2-2-u1-X09"}],"explanation":["9273은 천의 자리 9, 백의 자리 2, 십의 자리 7, 일의 자리 3이에요.","십의 자리 숫자는 7이에요.","자리는 왼쪽부터 천·백·십·일 — 숫자를 물으면 값이 아니라 숫자 하나로 답해요."],"variant_rule":{"pv4":{"ask":"digit"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#6','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C5',1,'mc','auto','10씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u1-X11']::text[],true,'{"seq":6,"concept":"M2-2-u1-C5","difficulty":1,"kind":"mc","stem":"10씩 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"1790","correct":true},{"t":"1880","mis":"M2-2-u1-X11"},{"t":"2780","mis":"M2-2-u1-X11"}],"explanation":["10씩 뛰면 십의 자리 숫자가 1씩 커져요.","1780에서 10만큼 뛰면 1790이에요.","다른 자리 숫자는 그대로예요."],"asset":{"type":"jump_row","cells":[1750,1760,1770,1780,null],"step":10},"variant_rule":{"skip4":{"ask":"next","step":[10]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#7','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C6',1,'mc','auto','3460과 3640 중에서 더 큰 수는 무엇인가요?',ARRAY['M2-2-u1-X13']::text[],true,'{"seq":7,"concept":"M2-2-u1-C6","difficulty":1,"kind":"mc","stem":"3460과 3640 중에서 더 큰 수는 무엇인가요?","options":[{"t":"3640","correct":true},{"t":"3460","mis":"M2-2-u1-X13"}],"explanation":["천의 자리가 같아요.","백의 자리를 보면 6은 4보다 커요 — 더 큰 수는 3640이에요.","높은 자리가 다르면 낮은 자리는 보지 않아도 돼요."],"variant_rule":{"cmp4d":{"ask":"big","same":"th"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#8','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C2',1,'sa','auto','2000은 1000이 몇 개인가요?','{}'::text[],true,'{"seq":8,"concept":"M2-2-u1-C2","difficulty":1,"kind":"sa","stem":"2000은 1000이 몇 개인가요?","answer":["2","2개"],"explanation":["2000은 천의 자리 숫자가 2예요.","1000이 2개예요.","천의 자리 숫자가 1000의 개수예요."],"variant_rule":{"n4":{"ask":"tcount"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#9','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C1',2,'blank','auto','1000은 980보다 (        )만큼 더 큰 수예요.',ARRAY['M2-2-u1-X12']::text[],false,'{"seq":9,"concept":"M2-2-u1-C1","difficulty":2,"kind":"blank","stem":"1000은 980보다 (        )만큼 더 큰 수예요.","options":[{"t":"20","correct":true},{"t":"2","mis":"M2-2-u1-X12"},{"t":"10","mis":"M2-2-u1-X12"}],"explanation":["980, 990, 1000 — 10씩 두 번 뛰어요.","그래서 1000은 980보다 20 커요.","10씩 몇 번 뛰었는지 세어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#10','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C3',2,'mc','auto','「오천삼백」을 수로 쓰면 무엇인가요?',ARRAY['M2-2-u1-X05','M2-2-u1-X04']::text[],true,'{"seq":10,"concept":"M2-2-u1-C3","difficulty":2,"kind":"mc","stem":"「오천삼백」을 수로 쓰면 무엇인가요?","options":[{"t":"5300","correct":true},{"t":"5000300","mis":"M2-2-u1-X05"},{"t":"53","mis":"M2-2-u1-X04"}],"explanation":["「오천삼백」은 1000이 5개, 100이 3개, 10이 0개, 1이 0개예요.","수로 쓰면 5300이에요.","읽지 않은 자리에는 0을 써요."],"variant_rule":{"n4":{"ask":"write","zero":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#11','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C4',2,'mc','auto','6957에서 숫자 9가 나타내는 값은 얼마인가요?',ARRAY['M2-2-u1-X08','M2-2-u1-X09']::text[],true,'{"seq":11,"concept":"M2-2-u1-C4","difficulty":2,"kind":"mc","stem":"6957에서 숫자 9가 나타내는 값은 얼마인가요?","options":[{"t":"900","correct":true},{"t":"9000","mis":"M2-2-u1-X08"},{"t":"9","mis":"M2-2-u1-X09"}],"explanation":["숫자 9는 백의 자리에 있어요.","백의 자리 9는 900을 나타내요.","같은 숫자라도 어느 자리에 있느냐에 따라 값이 달라요."],"variant_rule":{"pv4":{"ask":"value"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#12','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C4',2,'mc','auto','2375를 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u1-X09','M2-2-u1-X08']::text[],true,'{"seq":12,"concept":"M2-2-u1-C4","difficulty":2,"kind":"mc","stem":"2375를 각 자리의 값의 합으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"2000 + 300 + 70 + 5","correct":true},{"t":"2 + 3 + 7 + 5","mis":"M2-2-u1-X09"},{"t":"2000 + 700 + 30 + 5","mis":"M2-2-u1-X08"}],"explanation":["2375는 천의 자리 2, 백의 자리 3, 십의 자리 7, 일의 자리 5예요.","각 자리의 값은 2000, 300, 70, 5 — 2375 = 2000 + 300 + 70 + 5.","숫자 하나하나에 자리 값을 붙여야 해요."],"variant_rule":{"pv4":{"ask":"expand"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#13','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C5',2,'mc','auto','얼마씩 거꾸로 뛰어 세었나요?',ARRAY['M2-2-u1-X12']::text[],true,'{"seq":13,"concept":"M2-2-u1-C5","difficulty":2,"kind":"mc","stem":"얼마씩 거꾸로 뛰어 세었나요?","options":[{"t":"1씩","correct":true},{"t":"1000씩","mis":"M2-2-u1-X12"},{"t":"100씩","mis":"M2-2-u1-X12"}],"explanation":["6804, 6803, 6802 … 하고 일의 자리 숫자만 1씩 작아져요.","그래서 1씩 거꾸로 뛰어 세었어요.","어느 자리 숫자가 바뀌는지 보면 몇씩 뛰었는지 알 수 있어요."],"asset":{"type":"jump_row","cells":[6804,6803,6802,6801,6800],"step":null,"dir":"down"},"variant_rule":{"skip4":{"ask":"step","step":[1,10,100,1000],"dir":"both"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#14','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C6',2,'mc','auto','두 수의 크기를 바르게 비교한 것은 어느 것인가요?',ARRAY['M2-2-u1-X14']::text[],true,'{"seq":14,"concept":"M2-2-u1-C6","difficulty":2,"kind":"mc","stem":"두 수의 크기를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"2999 < 3001","correct":true},{"t":"2999 > 3001","mis":"M2-2-u1-X14"}],"explanation":["천의 자리에서 처음으로 달라요 — 3은 2보다 커요.","그래서 3001은 2999보다 커요 — 2999 < 3001.","> 와 < 는 벌어진 쪽이 큰 수를 향해요."],"variant_rule":{"cmp4d":{"ask":"sign"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#15','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C2',2,'error','auto','친구들이 몇천에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u1-X03','M2-2-u1-X07','M2-2-u1-X12']::text[],false,'{"seq":15,"concept":"M2-2-u1-C2","difficulty":2,"kind":"error","stem":"친구들이 몇천에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라온: 6000은 1000이 60개야.","correct":true,"mis_target":"M2-2-u1-X03"},{"t":"나은: 6000은 「육천」이라고 읽어.","mis":"M2-2-u1-X07"},{"t":"세아: 6000은 5000보다 1000 큰 수야.","mis":"M2-2-u1-X12"}],"explanation":["6000은 천의 자리 숫자가 6이에요.","그래서 1000이 6개예요 — 60개가 아니에요.","라온이가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#16','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C7',2,'mc','auto','100이 45개인 수는 얼마인가요?',ARRAY['M2-2-u1-X02','M2-2-u1-X10']::text[],true,'{"seq":16,"concept":"M2-2-u1-C7","difficulty":2,"kind":"mc","stem":"100이 45개인 수는 얼마인가요?","options":[{"t":"4500","correct":true},{"t":"10045","mis":"M2-2-u1-X02"},{"t":"450","mis":"M2-2-u1-X10"}],"explanation":["100이 10개면 1000이에요.","100이 45개는 1000이 4개, 100이 5개 — 4500이에요.","100이 10개 넘게 모이면 1000으로 바꿔 세요."],"variant_rule":{"n4":{"ask":"hund"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#17','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C5',3,'mc','auto','1씩 거꾸로 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u1-X01','M2-2-u1-X11']::text[],true,'{"seq":17,"concept":"M2-2-u1-C5","difficulty":3,"kind":"mc","stem":"1씩 거꾸로 뛰어 세었어요. 빈칸에 알맞은 수는 무엇인가요?","options":[{"t":"3999","correct":true},{"t":"4009","mis":"M2-2-u1-X01"},{"t":"3990","mis":"M2-2-u1-X11"}],"explanation":["1씩 거꾸로 뛰면 일의 자리 숫자가 1씩 작아져요.","4000에서 1만큼 거꾸로 뛰면 3999예요.","일의 자리가 0에서 더 작아지면 바로 윗자리에서 1을 빌려 와요."],"asset":{"type":"jump_row","cells":[4002,4001,4000,null,3998],"step":1,"dir":"down"},"variant_rule":{"skip4":{"ask":"blank","step":[1],"cross":true,"dir":"down"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#18','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C6',3,'mc','auto','5990, 6020, 6110 가운데 가장 작은 수는 무엇인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],true,'{"seq":18,"concept":"M2-2-u1-C6","difficulty":3,"kind":"mc","stem":"5990, 6020, 6110 가운데 가장 작은 수는 무엇인가요?","options":[{"t":"5990","correct":true},{"t":"6020","mis":"M2-2-u1-X13"},{"t":"6110","mis":"M2-2-u1-X15"}],"explanation":["높은 자리(천의 자리)부터 차례로 견주어요.","가장 작은 수는 5990이에요.","뒤쪽 숫자가 크다고 큰 수가 아니에요 — 높은 자리가 먼저예요."],"variant_rule":{"cmp4d":{"ask":"min3"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#19','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C7',3,'mc','auto','돈은 모두 얼마인가요?',ARRAY['M2-2-u1-X10']::text[],true,'{"seq":19,"concept":"M2-2-u1-C7","difficulty":3,"kind":"mc","stem":"돈은 모두 얼마인가요?","options":[{"t":"4920원","correct":true},{"t":"48120원","mis":"M2-2-u1-X10"},{"t":"4820원","mis":"M2-2-u1-X10"}],"explanation":["10원짜리 12개는 100원짜리 1개와 10원짜리 2개로 바꿀 수 있어요.","천 원짜리 4장, 100원짜리 9개, 10원짜리 2개 — 4920원이에요.","한 자리에 10개가 모이면 바로 윗자리 1개로 바꿔요."],"asset":{"type":"blocks4","th":4,"h":8,"t":12,"o":0,"unit":"coin"},"variant_rule":{"n4":{"ask":"build","carry":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#20','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C3',3,'mc','auto','수 모형이 나타내는 수는 얼마인가요?',ARRAY['M2-2-u1-X10']::text[],true,'{"seq":20,"concept":"M2-2-u1-C3","difficulty":3,"kind":"mc","stem":"수 모형이 나타내는 수는 얼마인가요?","options":[{"t":"5643","correct":true},{"t":"56313","mis":"M2-2-u1-X10"},{"t":"5633","mis":"M2-2-u1-X10"}],"explanation":["일 모형 13개는 십 모형 1개와 일 모형 3개로 바꿀 수 있어요.","1000이 5개, 100이 6개, 10이 4개, 1이 3개 — 5643이에요.","한 자리에 10개가 모이면 바로 윗자리 1개로 바꿔요."],"asset":{"type":"blocks4","th":5,"h":6,"t":3,"o":13},"variant_rule":{"n4":{"ask":"build","carry":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#21','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C4',3,'ox','auto','6262에서 두 숫자 2가 나타내는 값은 200과 2예요.',ARRAY['M2-2-u1-X09']::text[],false,'{"seq":21,"concept":"M2-2-u1-C4","difficulty":3,"kind":"ox","stem":"6262에서 두 숫자 2가 나타내는 값은 200과 2예요.","answer":"O","reason_options":[{"t":"백의 자리 2는 200, 일의 자리 2는 2니까","correct":true},{"t":"같은 숫자는 값도 같으니까","mis":"M2-2-u1-X09"}],"mis":"M2-2-u1-X09","explanation":["앞의 2는 백의 자리라 200이에요.","끝의 2는 일의 자리라 2예요.","그래서 맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#22','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C6',3,'mc','auto','수 카드 0, 8, 4, 1을 한 번씩 모두 써서 만들 수 있는 가장 큰 네 자리 수는 무엇인가요?',ARRAY['M2-2-u1-X15','M2-2-u1-X16']::text[],true,'{"seq":22,"concept":"M2-2-u1-C6","difficulty":3,"kind":"mc","stem":"수 카드 0, 8, 4, 1을 한 번씩 모두 써서 만들 수 있는 가장 큰 네 자리 수는 무엇인가요?","options":[{"t":"8410","correct":true},{"t":"1048","mis":"M2-2-u1-X15"},{"t":"8401","mis":"M2-2-u1-X16"}],"explanation":["가장 큰 8을 천의 자리에 놓아요.","남은 카드도 큰 수부터 — 8410이에요.","높은 자리일수록 큰 숫자를 놓아요."],"variant_rule":{"cards4":{"ask":"max","zero":true}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#23','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C7',4,'mc','auto','천 원짜리 5장과 100원짜리 동전 6개를 모두 100원짜리 동전으로 바꾸면 몇 개가 되나요?',ARRAY['M2-2-u1-X03','M2-2-u1-X04']::text[],false,'{"seq":23,"concept":"M2-2-u1-C7","difficulty":4,"kind":"mc","stem":"천 원짜리 5장과 100원짜리 동전 6개를 모두 100원짜리 동전으로 바꾸면 몇 개가 되나요?","options":[{"t":"56","correct":true},{"t":"11","mis":"M2-2-u1-X03"},{"t":"506","mis":"M2-2-u1-X04"}],"explanation":["천 원짜리 한 장은 100원짜리 10개예요.","천 원짜리 5장은 100원짜리 50개 — 6개를 더하면 56개예요.","5600원은 100이 56개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#24','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C6',4,'mc','auto','2□56은 2855보다 커요. □에 들어갈 수 있는 수는 모두 몇 개인가요?',ARRAY['M2-2-u1-X13','M2-2-u1-X15']::text[],false,'{"seq":24,"concept":"M2-2-u1-C6","difficulty":4,"kind":"mc","stem":"2□56은 2855보다 커요. □에 들어갈 수 있는 수는 모두 몇 개인가요?","options":[{"t":"2","correct":true},{"t":"1","mis":"M2-2-u1-X13"},{"t":"7","mis":"M2-2-u1-X15"}],"explanation":["천의 자리는 2로 같으니 백의 자리를 견주어요.","□가 8이면 2856 — 2855보다 커요. □는 8, 9예요.","그래서 모두 2개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u1_review_d#25','math',2,2,'u1','','g2_2_math_u1_review_d','unit_review','M2-2-u1-C5',4,'essay','teacher','8003부터 1씩 거꾸로 5번 뛰어 센 수를 차례로 쓰고, 자리가 바뀌는 곳을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-2-u1-C5","difficulty":4,"kind":"essay","stem":"8003부터 1씩 거꾸로 5번 뛰어 센 수를 차례로 쓰고, 자리가 바뀌는 곳을 설명해 보세요.","answer_guide":{"answer":"8002, 8001, 8000, 7999, 7998. 8000에서 1 작아질 때 일·십·백의 자리가 0이라 천의 자리에서 빌려 와 7999가 된다.","scoring_points":["뛰어 센 수를 차례로 바르게 썼는가","자리가 넘어가는(바뀌는) 곳을 설명했는가","몇씩 뛰었는지에 맞는 자리만 바뀐다는 것을 말했는가"]},"explanation":["뛰는 자리 숫자만 1씩 바뀌어요.","그 자리가 10이 되면 윗자리로 넘어가고, 0에서 더 작아지면 윗자리에서 빌려 와요.","숫자를 이어 붙이지 않고 자리를 넘겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
